"""AI subtitle pipeline orchestrator v2: wanted list -> faster-whisper ASR -> LLM translate -> Bazarr upload.

Self-looping daemon (flock guards single instance). Idempotent via JSONL state file.

v2 changes (rewrite track): faster-whisper large-v3-turbo int8 + Silero VAD
(replaces dead FunASR :9000), whisper-segment splitting to <=8s cues,
merge-aware 7B translation (chunk 10 + tail completion + echo retry +
per-line fallback), local Gemma JSON translation with glossary refs
AI provenance as a real first SRT cue
("[AI-generated by ASRSub]", config AI_MARKER_CUE), on-disk {stem}.{lang}.srt
(no .ai suffix; Bazarr rewrites names via subliminal anyway),
config-driven SDH placeholders, cps_merge reading-speed pass on
ASR-translated output (merges too-fast translated cues with the following
cue; CPS_MERGE_* env knobs; ladder output untouched), emotion pass on ASR
cues (emotion2vec+ per VAD window; EMO_ENABLED=1 + ASR_BACKEND=sensevoice;
see pipeline/emotion.py; ladder output untouched).
"""

