_REGISTRY_LOCK = threading.RLock()
_REGISTRY_LOCK_STATE = threading.local()


@contextmanager
def _registry_lock(path, exclusive=False):
    """Coordinate registry operations without creating files on reads."""
    lock_path = f"{path}.lock"
    directory = os.path.dirname(path) or "."
    requested = "exclusive" if exclusive else "shared"
    with _REGISTRY_LOCK:
        stack = getattr(_REGISTRY_LOCK_STATE, "stack", [])
        if stack and stack[-1]["path"] == path:
            entry = stack[-1]
            upgraded = exclusive and entry["mode"] == "shared"
            if upgraded:
                os.makedirs(directory, exist_ok=True)
                if entry["directory"] is None:
                    entry["directory"] = os.open(directory, os.O_RDONLY)
                fcntl.flock(entry["directory"], fcntl.LOCK_EX)
                if entry["handle"] is None:
                    entry["handle"] = open(lock_path, "a+", encoding="utf-8")
                fcntl.flock(entry["handle"].fileno(), fcntl.LOCK_EX)
                entry["mode"] = "exclusive"
            try:
                yield
            finally:
                if upgraded:
                    fcntl.flock(entry["handle"].fileno(), fcntl.LOCK_SH)
                    fcntl.flock(entry["directory"], fcntl.LOCK_SH)
                    entry["mode"] = "shared"
            return

        directory_handle = None
        handle = None
        try:
            if exclusive:
                os.makedirs(directory, exist_ok=True)
            elif not os.path.isdir(directory):
                entry = {"path": path, "handle": None, "directory": None, "mode": requested}
                stack.append(entry)
                _REGISTRY_LOCK_STATE.stack = stack
                try:
                    yield
                finally:
                    stack.pop()
                return
            directory_handle = os.open(directory, os.O_RDONLY)
            fcntl.flock(directory_handle, fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH)
            if exclusive:
                handle = open(lock_path, "a+", encoding="utf-8")
                fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
            elif os.path.exists(lock_path):
                handle = open(lock_path, "r", encoding="utf-8")
                fcntl.flock(handle.fileno(), fcntl.LOCK_SH)
            entry = {"path": path, "handle": handle, "directory": directory_handle, "mode": requested}
            stack.append(entry)
            _REGISTRY_LOCK_STATE.stack = stack
            try:
                yield
            finally:
                stack.pop()
                held_handle = entry["handle"]
                held_directory = entry["directory"]
                if held_handle is not None:
                    fcntl.flock(held_handle.fileno(), fcntl.LOCK_UN)
                    held_handle.close()
                if held_directory is not None:
                    fcntl.flock(held_directory, fcntl.LOCK_UN)
        finally:
            if directory_handle is not None:
                os.close(directory_handle)



_LANGUAGE_ALIASES = {
    "ja": "ja", "jp": "ja", "jpn": "ja",
    "id": "id", "ind": "id",
    "en": "en", "eng": "en", "enm": "en",
}
_EMBEDDED_LANGUAGE_TAGS = {
    "ja": {"jpn", "ja", "jp"},
    "id": {"ind", "id"},
    "en": {"eng", "en", "enm"},
}


def normalize_language(value):
    """Return the canonical application language while preserving unknowns."""
    normalized = re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())
    return _LANGUAGE_ALIASES.get(normalized, normalized)


def configured_languages(values):
    if isinstance(values, str):

        values = [values]
    result = []
    for value in values or []:
        lang = normalize_language(value)
        if lang and lang not in result:
            result.append(lang)
    return result


def embedded_language_tags(lang):
    normalized = normalize_language(lang)
    return {normalize_language(tag) for tag in _EMBEDDED_LANGUAGE_TAGS.get(normalized, {normalized})}


def sidecar_paths(stem, lang):
    aliases = {
        "ja": ("ja", "jpn", "jp"),
        "id": ("id", "ind"),
        "en": ("en", "eng", "enm"),


    }.get(normalize_language(lang), (normalize_language(lang),))
    return [
        f"{stem}.{alias}{flag}.srt"
        for alias in aliases
        for flag in ("", ".hi", ".forced", ".hi.forced", ".forced.hi")
    ]
def canonical_target_sidecar_path(stem, lang):
    """Return the sole canonical HI path for an ASRSub-owned target."""
    return f"{stem}.{normalize_language(lang)}.hi.srt"


def replaceable_target_sidecar_paths(stem, lang):
    """Return canonical HI first, then regular/HI aliases; never forced."""
    normalized = normalize_language(lang)
    aliases = {
        "ja": ("ja", "jpn", "jp"),
        "id": ("id", "ind"),
        "en": ("en", "eng", "enm"),
    }.get(normalized, (normalized,))
    paths = [canonical_target_sidecar_path(stem, normalized)]
    for alias in aliases:
        for flag in ("", ".hi"):
            path = f"{stem}.{alias}{flag}.srt"
            if path not in paths:
                paths.append(path)
    return paths


def registry_source_language(source, target_lang):
    """Map registry source aliases without changing source-kind semantics."""
    source_lang = normalize_language(source)
    if source_lang in ("ja", "jpn", "jp"):
        return "ja"
    if source_lang in ("en", "eng", "enm"):
        return "en"
    if source_lang in ("id", "ind"):
        return "id"
    if source_lang == "asr":
        return normalize_language(target_lang)
    return normalize_language(target_lang)

def canonicalize_new_provider_sidecar(stem, lang, before=None):
    """Move newly landed non-forced provider aliases to canonical HI."""
    canonical = canonical_target_sidecar_path(stem, lang)
    if before is not None:
        before_abs = {os.path.abspath(path) for path in before}
        new_paths = [
            path
            for path in replaceable_target_sidecar_paths(stem, lang)
            if path != canonical
            and os.path.isfile(path)
            and os.path.abspath(path) not in before_abs
        ]
        if new_paths:
            try:
                os.replace(new_paths[0], canonical)
            except OSError:
                return None
            for extra in new_paths[1:]:
                _silent_remove(extra)
            return canonical
    return canonical if os.path.isfile(canonical) else None


def normalize_late_provider_sidecars(cfg, root=None):
    """Reconcile valid unflagged provider aliases into canonical HI sidecars.

    An explicit root is used by hermetic callers; production defaults to the
    mapped Jellyfin media root. The bounded walk never touches other roots.
    LATE_PROVIDER_SIDECAR_BUDGET defaults to 25 candidates per pass.
    """
    result = {"moved": 0, "removed": 0, "skipped": 0, "failed": 0}
    if root is None:
        mapped_root = "/mnt/nas/share/media/jellyfin"
        root = mapped_root if os.path.isdir(mapped_root) else ((cfg or {}).get("JELLYFIN_MEDIA_ROOT") or JELLYFIN_MEDIA_ROOT)
    try:
        budget = max(0, int((cfg or {}).get("LATE_PROVIDER_SIDECAR_BUDGET", 25)))
    except (TypeError, ValueError):
        budget = 25

    target_langs = set(configured_languages((cfg or {}).get("TARGET_LANGS", [])))
    aliases = {
        "ja": ("ja", "jpn", "jp"),
        "id": ("id", "ind"),
        "en": ("en", "eng", "enm"),
    }
    alias_languages = {
        alias: lang
        for lang, names in aliases.items()
        if lang in target_langs
        for alias in names
    }

    def valid_srt(path):
        try:
            with open(path, "rb") as fh:
                raw = fh.read()
            if not raw:
                return False
            return bool(parse_srt(raw.decode("utf-8-sig")))
        except (OSError, UnicodeError):
            return False

    candidates = []
    try:
        for directory, _directories, filenames in os.walk(root):
            for filename in filenames:
                match = re.match(r"^(.+)\.([a-z]+)\.srt$", filename)
                if not match or match.group(2) not in alias_languages:
                    continue
                candidates.append((os.path.join(directory, filename), match.group(1), alias_languages[match.group(2)]))
    except (OSError, TypeError):
        return result

    for candidate, stem, lang in sorted(candidates)[:budget]:
        if not valid_srt(candidate):
            result["skipped"] += 1
            continue
        canonical = os.path.join(os.path.dirname(candidate), f"{stem}.{lang}.hi.srt")
        if os.path.exists(canonical):
            if not valid_srt(canonical):
                result["skipped"] += 1
                continue
            try:
                os.unlink(candidate)
                result["removed"] += 1
            except OSError:
                result["failed"] += 1
            continue
        try:
            os.link(candidate, canonical)
            os.unlink(candidate)
            result["moved"] += 1
        except FileExistsError:
            if valid_srt(canonical):
                try:
                    os.unlink(candidate)
                    result["removed"] += 1
                except OSError:
                    result["failed"] += 1
            else:
                result["skipped"] += 1
        except OSError:
            result["failed"] += 1
    return result

def _registry_current_row(stem, lang, media_path=None, row=None):
    with _registry_lock(REGISTRY_FILE):
        return _registry_current_row_locked(stem, lang, media_path=media_path, row=row)


def _registry_current_row_locked(stem, lang, media_path=None, row=None):
    """Return a row only when its source and target artifacts are current."""
    normalized = normalize_language(lang)
    row = row or registry_get(stem, normalized)
    if not row:
        return None
    source = row.get("source") or ""
    source_lang = registry_source_language(source, normalized)
    source_candidates = sidecar_paths(stem, source_lang)
    target_candidates = replaceable_target_sidecar_paths(stem, normalized)
    target_fields = "target_path" in row or "target_hash" in row

    def verified_path(path, digest, candidates):
        if not isinstance(path, str) or not path or not isinstance(digest, str) or not digest:
            return None
        try:
            if os.path.abspath(path) not in {os.path.abspath(candidate) for candidate in candidates}:
                return None
            return path if os.path.isfile(path) and file_sha256(path) == digest else None
        except (OSError, TypeError):
            return None

    source_path = row.get("source_path")
    source_hash = row.get("source_hash")
    current_source = verified_path(source_path, source_hash, source_candidates)
    if current_source is None and isinstance(source_path, str) and isinstance(source_hash, str):
        try:
            recognized_source = os.path.abspath(source_path) in {os.path.abspath(candidate) for candidate in source_candidates}
        except TypeError:
            recognized_source = False
        if recognized_source:
            for candidate in source_candidates:
                try:
                    if os.path.isfile(candidate) and file_sha256(candidate) == source_hash:
                        current_source = candidate
                        break
                except OSError:
                    pass
    if current_source is None:
        if media_path and target_fields and row.get("source_kind") == "embedded":
            current_target = verified_path(row.get("target_path"), row.get("target_hash"), target_candidates)
            if current_target and (source_lang == normalized or srt_has_ai_marker(current_target)):
                return row
        if media_path and source == "asr":
            sidecar = target_sidecar_exists(media_path, normalized)
            if sidecar and srt_has_ai_marker(sidecar):
                if not target_fields:
                    return row
                current_target = verified_path(row.get("target_path"), row.get("target_hash"), target_candidates)
                if current_target == sidecar:
                    return row
        return None

    if source == "asr" and not srt_has_ai_marker(current_source):
        return None

    current_target = None
    if target_fields:
        current_target = verified_path(row.get("target_path"), row.get("target_hash"), target_candidates)
        if current_target is None:
            try:
                target_aliases = {os.path.abspath(candidate) for candidate in target_candidates}
                if isinstance(row.get("target_path"), str) and os.path.abspath(row["target_path"]) in target_aliases:
                    for candidate in target_candidates:
                        if os.path.isfile(candidate) and file_sha256(candidate) == row.get("target_hash"):
                            current_target = candidate
                            break
            except (OSError, TypeError):
                pass
        if current_target is None:
            return None
    elif source_lang != normalized:
        if not media_path or not target_sidecar_exists(media_path, normalized):
            return None

    if source_lang != normalized:
        target = current_target or target_sidecar_exists(media_path, normalized)
        if not target or not srt_has_ai_marker(target):
            return None

    return row


def reconcile_registry(registry_path=None, budget=100):
    """Reconcile a registry while holding its stable sidecar lock."""
    path = registry_path or REGISTRY_FILE
    with _registry_lock(path, exclusive=True):
        return _reconcile_registry_locked(path, budget)


def _reconcile_registry_locked(path, budget=100):
    """Append canonical provenance rows for verifiable legacy registry entries."""
    try:
        limit = max(0, int(budget))
    except (TypeError, ValueError):
        limit = 100
    if limit <= 0:
        return {"scanned": 0, "reconciled": 0, "invalid": 0}
    try:
        rows = load_records_jsonl(path)
    except Exception:
        rows = []
    reconciled = 0
    invalid = 0
    scanned = 0
    existing = {}
    for prior in rows:
        normalized = normalize_language(prior.get("lang"))
        stem = prior.get("stem")
        if stem and normalized:
            existing[(stem, normalized)] = prior

    def paths(stem, lang):
        return sidecar_paths(stem, lang)

    def verify(candidate, digest, accepted):
        if not isinstance(candidate, str) or not isinstance(digest, str) or not candidate or not digest:
            return False
        try:
            if os.path.abspath(candidate) not in {os.path.abspath(item) for item in accepted}:
                return False
            if not os.path.isfile(candidate):
                return False
            return candidate if file_sha256(candidate) == digest else None
        except (OSError, TypeError):
            return False

    for row in rows:
        if scanned >= limit:
            break
        scanned += 1
        stem = row.get("stem")
        if not isinstance(stem, str) or not stem:
            invalid += 1
            continue
        normalized = normalize_language(row.get("lang"))
        if not normalized:
            invalid += 1
            continue
        source = row.get("source") or ""
        source_lang = registry_source_language(source, normalized)
        source_candidates = paths(stem, source_lang)
        target_candidates = replaceable_target_sidecar_paths(stem, normalized)
        source_path = row.get("source_path")
        source_hash = row.get("source_hash")
        current_source = verify(source_path, source_hash, source_candidates)
        if not current_source and source == "asr" and not source_path and not source_hash:
            for candidate in target_candidates:
                if os.path.isfile(candidate) and srt_has_ai_marker(candidate):
                    current_source = candidate
                    source_hash = file_sha256(candidate)
                    break
        temporary_embedded = False
        if not current_source and row.get("source_kind") == "embedded" and ("target_path" in row or "target_hash" in row):
            candidate = verify(row.get("target_path"), row.get("target_hash"), target_candidates)
            if candidate and (source_lang == normalized or srt_has_ai_marker(candidate)):
                temporary_embedded = True
        if not current_source and not temporary_embedded:
            invalid += 1
            continue
        if current_source and source == "asr" and not srt_has_ai_marker(current_source):
            invalid += 1
            continue
        target_path = row.get("target_path")
        target_hash = row.get("target_hash")
        if "target_path" in row or "target_hash" in row:
            current_target = verify(target_path, target_hash, target_candidates)
            if not current_target and isinstance(target_path, str) and isinstance(target_hash, str):
                try:
                    recognized_target = os.path.abspath(target_path) in {
                        os.path.abspath(candidate) for candidate in target_candidates
                    }
                except TypeError:
                    recognized_target = False
                if recognized_target:
                    for candidate in target_candidates:
                        try:
                            if os.path.isfile(candidate) and file_sha256(candidate) == target_hash:
                                current_target = candidate
                                break
                        except OSError:
                            pass
            if not current_target:
                invalid += 1
                continue
            target_path = current_target
        elif source_lang != normalized:
            target_path = target_sidecar_exists(stem + ".mkv", normalized)
            if not target_path:
                invalid += 1
                continue
            target_hash = file_sha256(target_path)
        if source_lang != normalized:
            if not target_path or not srt_has_ai_marker(target_path):
                invalid += 1
                continue
        canonical = dict(row)
        canonical["lang"] = normalized
        canonical["source_path"] = current_source
        canonical["source_hash"] = source_hash
        if target_path is not None:
            canonical["target_path"] = target_path
            canonical["target_hash"] = target_hash
        prior = existing.get((stem, normalized))
        if prior and prior.get("lang") == normalized and all(prior.get(key) == canonical.get(key) for key in ("source_path", "source_hash", "target_path", "target_hash")):
            continue
        rows_to_append = canonical
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(rows_to_append, ensure_ascii=False) + "\n")
        existing[(stem, normalized)] = canonical
        reconciled += 1
    return {"scanned": scanned, "reconciled": reconciled, "invalid": invalid}




def load_config():
    cfg = {}
    with open(ENV_FILE, "r", encoding="utf-8") as fh:
        for raw in fh:
            line = raw.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, _, v = line.partition("=")
            cfg[k.strip()] = v.strip()
    if os.path.exists(OVERRIDE_FILE):
        try:
            with open(OVERRIDE_FILE, "r", encoding="utf-8") as fh:
                ov = json.loads(fh.read())
            if isinstance(ov, dict):
                for k, v in ov.items():
                    cfg[str(k)] = str(v)
        except Exception as exc:
            log(f"WARNING: failed to load {OVERRIDE_FILE}: {exc}")
    cfg["MAX_EPS_PER_RUN"] = int(
        os.environ.get("MAX_EPS_PER_RUN", cfg.get("MAX_EPS_PER_RUN", "8"))
    )
    try:
        cfg["FILELESS_EPISODE_RECOVERY_BUDGET"] = int(
            cfg.get("FILELESS_EPISODE_RECOVERY_BUDGET", FILELESS_EPISODE_RECOVERY_BUDGET)
        )
    except (TypeError, ValueError):
        cfg["FILELESS_EPISODE_RECOVERY_BUDGET"] = 0
    cfg["FILELESS_EPISODE_RECOVERY_BUDGET"] = max(0, cfg["FILELESS_EPISODE_RECOVERY_BUDGET"])
    cfg["ALIGN_ENABLED"] = str(
        cfg.get("ALIGN_ENABLED", ALIGN_ENABLED)
    ).lower() in ("1", "true", "yes")
    cfg["REGEN_LIBRARY"] = str(
        os.environ.get("REGEN_LIBRARY", cfg.get("REGEN_LIBRARY", "false"))
    ).lower() in ("1", "true", "yes")
    cfg["MOVIE_LIBRARY"] = str(
        os.environ.get("MOVIE_LIBRARY", cfg.get("MOVIE_LIBRARY", "false"))
    ).lower() in ("1", "true", "yes")
    try:
        cfg["ALIGN_MAX_OFFSET_S"] = float(
            cfg.get("ALIGN_MAX_OFFSET_S", ALIGN_MAX_OFFSET_S)
        )
        cfg["ALIGN_MAX_OFFSET_SECONDS"] = float(
            cfg.get("ALIGN_MAX_OFFSET_SECONDS", ALIGN_MAX_OFFSET_SECONDS)
        )
    except (TypeError, ValueError):
        cfg["ALIGN_MAX_OFFSET_S"] = ALIGN_MAX_OFFSET_S
        cfg["ALIGN_MAX_OFFSET_SECONDS"] = ALIGN_MAX_OFFSET_SECONDS
    cfg["RETIME_ENABLED"] = str(
        cfg.get("RETIME_ENABLED", RETIME_ENABLED)
    ).lower() in ("1", "true", "yes")
    try:
        cfg["RETIME_TEXT_THRESHOLD"] = float(
            cfg.get("RETIME_TEXT_THRESHOLD", RETIME_TEXT_THRESHOLD)
        )
        cfg["RETIME_MAX_RATIO"] = float(
            cfg.get("RETIME_MAX_RATIO", RETIME_MAX_RATIO)
        )
        cfg["RETIME_MIN_ANCHOR_FRAC"] = float(
            cfg.get("RETIME_MIN_ANCHOR_FRAC", RETIME_MIN_ANCHOR_FRAC)
        )
    except (TypeError, ValueError):
        cfg["RETIME_TEXT_THRESHOLD"] = RETIME_TEXT_THRESHOLD
        cfg["RETIME_MAX_RATIO"] = RETIME_MAX_RATIO
        cfg["RETIME_MIN_ANCHOR_FRAC"] = RETIME_MIN_ANCHOR_FRAC
    tl = cfg.get("TARGET_LANGS", "id,en")
    if isinstance(tl, str) and tl.strip().startswith("["):
        try:
            import ast

            tl = ast.literal_eval(tl)
        except Exception:
            tl = "id,en"
    if isinstance(tl, list):
        cfg["TARGET_LANGS"] = configured_languages(tl)
    else:
        cfg["TARGET_LANGS"] = configured_languages(str(tl).split(","))
    cfg["BAZARR_URL_2"] = cfg.get("BAZARR_URL_2") or None
    cfg["BAZARR_API_KEY_2"] = cfg.get("BAZARR_API_KEY_2") or ""
    cfg["STATE_FILE"] = STATE_FILE
    cfg["JELLYFIN_URL"] = cfg.get("JELLYFIN_URL") or JELLYFIN_URL
    cfg["JELLYFIN_MEDIA_ROOT"] = cfg.get("JELLYFIN_MEDIA_ROOT") or JELLYFIN_MEDIA_ROOT
    sdh = cfg.get("sdh_placeholders")
    if isinstance(sdh, str):
        try:
            sdh = json.loads(sdh)
        except Exception:
            try:
                import ast

                sdh = ast.literal_eval(sdh)
            except Exception:
                sdh = None
    cfg["SDH_PLACEHOLDERS"] = list(sdh) if isinstance(sdh, list) else list(DEFAULT_SDH_PLACEHOLDERS)
    cfg["WEBHOOK_URLS"] = cfg.get("WEBHOOK_URLS") or ""
    cfg["WEBHOOK_SECRET"] = cfg.get("WEBHOOK_SECRET") or ""
    cfg["WEBHOOK_EVENTS"] = cfg.get("WEBHOOK_EVENTS") or ""
    return cfg


def _ladder_cfg(cfg):
    """Resolve ladder config from cfg (pipeline.env + config.overrides.json),
    falling back to the process-env defaults captured at import time."""
    def _gi(key, default):
        try:
            return int(cfg.get(key, default))
        except (TypeError, ValueError):
            return default

    def _gb(key, default):
        v = cfg.get(key, default)
        if isinstance(v, bool):
            return v
        return str(v).lower() in ("1", "true", "yes")

    def _gf(key, default):
        try:
            return float(cfg.get(key, default))
        except (TypeError, ValueError):
            return default

    return {
        "upgrade_budget": _gi("LADDER_UPGRADE_BUDGET", LADDER_UPGRADE_BUDGET),
        "cooldown_h": _gi("LADDER_COOLDOWN_H", LADDER_COOLDOWN_H),
        "jimaku_hunt_budget": _gi(
            "LADDER_JIMAKU_HUNT_BUDGET", LADDER_JIMAKU_HUNT_BUDGET
        ),
        "jimaku_hunt_budget_movies": _gi(
            "LADDER_JIMAKU_HUNT_BUDGET_MOVIES", LADDER_JIMAKU_HUNT_BUDGET_MOVIES
        ),
        "skip_refined": _gb("LADDER_SKIP_REFINED", LADDER_SKIP_REFINED),
        "jimaku_direct_enabled": _gb(
            "JIMAKU_DIRECT_ENABLED", JIMAKU_DIRECT_ENABLED
        ),
        "min_cues": _gi("LADDER_MIN_CUES", LADDER_MIN_CUES),
        "min_chars": _gi("LADDER_MIN_CHARS", LADDER_MIN_CHARS),
        "min_cjk": _gf("LADDER_MIN_CJK", LADDER_MIN_CJK),
        "span_tol": _gf("LADDER_SPAN_TOLERANCE", LADDER_SPAN_TOLERANCE),
        "align_enabled": _gb("ALIGN_ENABLED", ALIGN_ENABLED),
        "align_max_offset_s": _gf("ALIGN_MAX_OFFSET_S", ALIGN_MAX_OFFSET_S),
        "align_max_offset_seconds": _gf(
            "ALIGN_MAX_OFFSET_SECONDS", ALIGN_MAX_OFFSET_SECONDS
        ),
        "retime_enabled": _gb("RETIME_ENABLED", RETIME_ENABLED),
        "retime_text_threshold": _gf("RETIME_TEXT_THRESHOLD", RETIME_TEXT_THRESHOLD),
        "retime_max_ratio": _gf("RETIME_MAX_RATIO", RETIME_MAX_RATIO),
        "retime_min_anchor_frac": _gf("RETIME_MIN_ANCHOR_FRAC", RETIME_MIN_ANCHOR_FRAC),
        "retime_accept_min_anchor_frac": _gf(
            "RETIME_ACCEPT_MIN_ANCHOR_FRAC", RETIME_ACCEPT_MIN_ANCHOR_FRAC
        ),
        "retime_min_anchors": _gi("RETIME_MIN_ANCHORS", RETIME_MIN_ANCHORS),
        "retime_max_anchor_p75_ms": _gf("RETIME_MAX_ANCHOR_P75_MS", RETIME_MAX_ANCHOR_P75_MS),
        "retime_max_anchor_p90_ms": _gf("RETIME_MAX_ANCHOR_P90_MS", RETIME_MAX_ANCHOR_P90_MS),
    }


def log(msg):
    ts = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    with _LOG_LOCK:
        _LOG_RING.append(f"{ts} {msg}")
        print(f"{ts} {msg}", flush=True)


# ---------- state ----------


def load_state():
    entries = []
    if os.path.exists(STATE_FILE):
        with open(STATE_FILE, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line:
                    try:
                        entry = json.loads(line)
                        if not isinstance(entry, dict):
                            continue
                        if entry.get("language") is not None:
                            entry["language"] = normalize_language(entry["language"])
                        entries.append(entry)
                    except Exception:
                        pass
    if len(entries) > STATE_COMPACT_LINES:
        entries = _compact_state(entries)
    return entries


STATE_COMPACT_LINES = 2000
STATE_COMPACT_DAYS = 14
FILELESS_EPISODE_RECOVERY_BUDGET = 8
STATE_GC_AGE = 24 * 3600  # fileless rows older than this are pruned
STATE_GC_CAP = 500  # max unique episode ids queried per GC sweep
STATE_GC_CHUNK = 200  # per-call cap when a sweep must be chunked

# Session-memoized Sonarr knowledge for orphan GC. Never re-queried within one
# daemon lifetime. Value = {"monitored": bool, "hasFile": bool} for episodes
# known to Sonarr, None for ghosts (deleted from Sonarr). state.jsonl is only
# ever written by this daemon (append_state / _compact_state / gc_state), so
# no cross-process race on these writes.
_GC_KNOWN = {}


def fetch_sonarr_episode_map(cfg):
    """One series-list call + one episode-list call per series (~15 series ->
    ~16 calls instead of one call per episode). Returns
    {episode_id: {"monitored": bool, "hasFile": bool}} for every episode
    Sonarr knows; raises on HTTP failure, returns None when the response
    shape is unusable (never a partial/empty map that would look like every
    episode is a ghost)."""
    base = cfg["SONARR_URL"].rstrip("/")
    headers = {"X-Api-Key": cfg["SONARR_API_KEY"]}
    r = requests.get(base + "/series", headers=headers, timeout=60)
    r.raise_for_status()
    series = r.json()
    if not isinstance(series, list):
        return None
    info = {}
    for s in series:
        if not isinstance(s, dict):
            continue
        sid = s.get("id")
        if sid is None:
            continue
        r2 = requests.get(
            base + "/episode", params={"seriesId": sid}, headers=headers, timeout=60
        )
        r2.raise_for_status()
        eps = r2.json()
        if not isinstance(eps, list):
            return None
        for e in eps:
            if not isinstance(e, dict):
                continue
            eid = e.get("id")
            if isinstance(eid, int):
                info[eid] = {
                    "monitored": bool(e.get("monitored")),
                    "hasFile": bool(e.get("hasFile")),
                }
    return info


def mark_ghost(eid):
    """Record that Sonarr returned 404 for this episode id (get_episode in
    run_pass/consume_actions) so the next GC sweep prunes its state rows."""
    if isinstance(eid, int):
        _GC_KNOWN[eid] = None


def gc_state(cfg, entries, cap=STATE_GC_CAP, age=STATE_GC_AGE):
    """Orphan GC over state entries.

    Drops rows whose episode no longer exists in Sonarr (ghost) and rows for
    episodes with no video file when the row is older than 24h (age guard;
    unparseable ts is KEPT, same convention as _compact_state). Never drops
    rows for monitored episodes that have video files (retryable), and leaves
    unmonitored-but-fileless rows alone when fresh. Only checks episode ids
    not yet queried this daemon lifetime (_GC_KNOWN). Rewrites state.jsonl
    atomically (tmp + os.replace) when rows were dropped.

    Returns (kept_entries, {"dropped", "ghost", "fileless"})."""
    if not entries:
        return entries, {"dropped": 0, "ghost": 0, "fileless": 0}
    unique_ids = sorted(
        {
            e.get("sonarrEpisodeId")
            for e in entries
            if isinstance(e.get("sonarrEpisodeId"), int)
        }
    )
    if not unique_ids:
        return entries, {"dropped": 0, "ghost": 0, "fileless": 0}
    todo = [i for i in unique_ids if i not in _GC_KNOWN][:cap]
    if todo:
        try:
            info = fetch_sonarr_episode_map(cfg)
        except Exception as exc:
            log(f"GC: Sonarr scan failed ({exc}); skipping sweep, retry next pass")
            return entries, {"dropped": 0, "ghost": 0, "fileless": 0}
        if not info:
            log("GC: Sonarr returned no episode map; skipping sweep")
            return entries, {"dropped": 0, "ghost": 0, "fileless": 0}
        for i in todo:
            _GC_KNOWN[i] = info.get(i)  # absent => ghost
    cutoff = time.time() - age
    kept, ghost, fileless = [], 0, 0
    for e in entries:
        eid = e.get("sonarrEpisodeId")
        if not isinstance(eid, int) or eid not in _GC_KNOWN:
            kept.append(e)  # never checked yet: keep until a sweep resolves it
            continue
        st = _GC_KNOWN[eid]
        if st is None:
            ghost += 1
            continue
        if not st.get("hasFile"):
            ts = e.get("ts", "")
            try:
                row_age = datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()
            except Exception:
                row_age = cutoff + 1  # unknown age: keep (cannot prove old)
            if row_age < cutoff:
                fileless += 1
                continue
        kept.append(e)
    dropped = ghost + fileless
    if dropped:
        rewrite_jsonl(STATE_FILE, kept)
        log(
            f"state GC: dropped {dropped} rows ({ghost} ghost, {fileless} fileless) "
            f"from {len(entries)} entries, {len(kept)} kept"
        )
    return kept, {"dropped": dropped, "ghost": ghost, "fileless": fileless}


def _compact_state(entries):
    """Compact state.jsonl (>2000 entries): keep only the LATEST entry per
    (sonarrEpisodeId, language) and drop entries older than 14 days; write
    atomically (tmp + os.replace). Never changes the entry schema."""
    cutoff = time.time() - STATE_COMPACT_DAYS * 24 * 3600
    last_idx = {}
    for i, e in enumerate(entries):
        key = (e.get("sonarrEpisodeId"), normalize_language(e.get("language")))
        last_idx[key] = i
    kept = []
    for i, e in enumerate(entries):
        if last_idx.get((e.get("sonarrEpisodeId"), normalize_language(e.get("language")))) != i:
            continue  # newer entry exists for this (episode, language)
        ts = e.get("ts", "")
        try:
            age = datetime.fromisoformat(ts.replace("Z", "+00:00")).timestamp()
        except Exception:
            age = cutoff + 1  # unknown age: keep (cannot prove it is old)
        if age < cutoff:
            continue
        kept.append(e)
    if len(kept) < len(entries):
        rewrite_jsonl(STATE_FILE, kept)
        log(
            f"state compacted: {len(entries)} -> {len(kept)} entries "
            f"(latest per episode+language, <{STATE_COMPACT_DAYS}d kept)"
        )
    return kept


def append_state(entry):
    if entry.get("language") is not None:
        entry["language"] = normalize_language(entry["language"])
    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)
    entry["ts"] = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    with open(STATE_FILE, "a", encoding="utf-8") as fh:
        fh.write(json.dumps(entry, ensure_ascii=False) + "\n")


def load_records_jsonl(path):
    """Parse a jsonl of dicts, tolerating empty/garbage lines."""
    records = []
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                    if isinstance(record, dict):
                        records.append(record)
                except Exception:
                    continue
    return records


def consume_records_jsonl(path):
    """Read a jsonl and remove the consumed records in place.

    Holds an exclusive flock (fcntl) on the single "r+" handle around the
    read/truncate/write, so a producer appending under the same flock
    protocol is serialized: any bytes appended after our last readline are
    rewritten as the new file tail — the consumed prefix is gone, concurrent
    records survive, and no record is processed twice or lost."""
    records = []
    if os.path.exists(path):
        with open(path, "r+", encoding="utf-8") as fh:
            fcntl.flock(fh, fcntl.LOCK_EX)
            try:
                while True:
                    line = fh.readline()
                    if not line:
                        break
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        records.append(json.loads(line))
                    except Exception:
                        continue
                tail = fh.read()
                fh.seek(0)
                fh.truncate(0)
                fh.write(tail)
                fh.flush()
                os.fsync(fh.fileno())
            finally:
                fcntl.flock(fh, fcntl.LOCK_UN)
    return records


def rewrite_jsonl(path, records):
    """Atomic rewrite of a jsonl file (temp file + os.replace)."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        for rec in records:
            fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
    os.replace(tmp, path)


def parse_exclusions():
    """Excluded episode ids from exclusions.jsonl ({'episode_id': N, ...})."""
    ids = set()
    for rec in load_records_jsonl(EXCLUSIONS_FILE):
        eid = rec.get("episode_id")
        if isinstance(eid, int):
            ids.add(eid)
    return ids


# ---------- subtitle provenance registry ----------


def _registry_key(rec):
    """Row identity: (stem, lang) when the row carries a stem (the on-disk
    sidecar file {stem}.{lang}[.hi].srt is the unit of provenance — both the tdarr
    webhook, which only knows the file path, and the ladder, which knows the
    Sonarr ids, address the same row); legacy rows written before stems
    existed fall back to (episode_id, lang)."""
    lang = normalize_language(rec.get("lang"))
    if not lang:
        return None
    stem = rec.get("stem")
    if stem:
        return (stem, lang)
    eid = rec.get("episode_id")
    if isinstance(eid, int):
        return (eid, lang)
    return None


def load_registry():
    """All registry rows, keyed (stem, lang); the LAST row per key wins."""
    with _registry_lock(REGISTRY_FILE):
        out = {}
        for rec in load_records_jsonl(REGISTRY_FILE):
            key = _registry_key(rec)
            if key is not None:
                out[key] = rec
        return out


def registry_get(stem, lang, ep_id=None, media_path=None):
    """Return the latest alias-aware registry row for a stem or episode."""
    with _registry_lock(REGISTRY_FILE):
        if stem is None and media_path:
            stem = os.path.splitext(media_path)[0]
        normalized = normalize_language(lang)
        latest = None
        for rec in load_records_jsonl(REGISTRY_FILE):
            if normalize_language(rec.get("lang")) != normalized:
                continue
            if stem is not None and rec.get("stem") == stem:
                latest = rec
            elif stem is None and isinstance(rec.get("episode_id"), int) and rec.get("episode_id") == ep_id:
                latest = rec
        if latest is None and stem is not None and ep_id is not None:
            for rec in load_records_jsonl(REGISTRY_FILE):
                if (normalize_language(rec.get("lang")) == normalized and
                        isinstance(rec.get("episode_id"), int) and rec.get("episode_id") == ep_id):
                    latest = rec
        return latest


def registry_by_episode(ep_id, lang):
    """Return the latest alias-aware registry row for an episode/language."""
    with _registry_lock(REGISTRY_FILE):
        normalized = normalize_language(lang)
        latest = None
        for rec in load_records_jsonl(REGISTRY_FILE):
            if (normalize_language(rec.get("lang")) == normalized and
                    isinstance(rec.get("episode_id"), int) and rec.get("episode_id") == ep_id):
                latest = rec
        return latest


def _is_ai_marker_cue(cue):
    """Return whether a cue is the synthetic ASRSub marker."""
    return AI_MARKER in str((cue or {}).get("text") or "")


def _timeline_snapshot(cues):
    """Return cue boundaries as JSON-safe integer milliseconds."""
    snapshot = []
    for cue in cues or []:
        start = srt_ts_ms(cue.get("start"))
        end = srt_ts_ms(cue.get("end"))
        if start is None or end is None or end < start:
            return None
        snapshot.append([int(round(start)), int(round(end))])
    return snapshot


def _timeline_hash(snapshot):
    if not isinstance(snapshot, list):
        return None
    payload = json.dumps(snapshot, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()

def _cues_with_timeline(raw_cues, snapshot):
    """Apply a complete persisted effective timeline to raw source text."""
    if not isinstance(snapshot, list) or len(snapshot) != len(raw_cues or []):
        return None
    out = []
    previous = None
    for cue, pair in zip(raw_cues or [], snapshot):
        if not isinstance(pair, (list, tuple)) or len(pair) != 2:
            return None
        try:
            start, end = float(pair[0]), float(pair[1])
        except (TypeError, ValueError):
            return None
        if (
            not math.isfinite(start)
            or not math.isfinite(end)
            or start < 0
            or end < start
            or (previous is not None and start < previous)
        ):
            return None
        previous = start
        item = dict(cue)
        item["start"] = start
        item["end"] = end
        out.append(item)
    return out


def _effective_cues_from_row(row, raw_cues):
    """Load a current or safely legacy raw timeline from an external row."""
    if not row or row.get("source_kind") != "external":
        return None
    version = str(row.get("retime_policy_version"))
    if version != RETIME_POLICY_VERSION:
        # Rows created before effective timelines existed are safe to reuse
        # only when they never claimed a retime. Legacy retimed rows are
        # deliberately re-evaluated under the new policy.
        if row.get("retimed"):
            return None
        return [dict(cue) for cue in (raw_cues or [])]
    snapshot = row.get("effective_timeline")
    if row.get("effective_timeline_hash") and row["effective_timeline_hash"] != _timeline_hash(snapshot):
        return None
    return _cues_with_timeline(raw_cues, snapshot)


def _timeline_matches_source(rec, source):
    """Whether a target row used the same effective timeline as a source hit."""
    if str((rec or {}).get("retime_policy_version")) != RETIME_POLICY_VERSION:
        return False
    expected = source.get("effective_timeline") if source else None
    if expected is None and source:
        expected = _timeline_snapshot(source.get("cues") or [])
    return bool(expected) and rec.get("effective_timeline_hash") == _timeline_hash(expected)


def registry_upsert(
    stem,
    lang,
    source,
    source_path=None,
    source_hash=None,
    source_kind=None,
    ep_id=None,
    audio_id=None,
    retimed=None,
    matched_frac=None,
    kind=None,
    effective_timeline=None,
    timeline_kind=None,
    retime_status=None,
    retime_reason=None,
    retime_policy_version=None,
    target_path=None,
    target_hash=None,
):
    """Append a registry row for the current (stem, language) sidecar provenance."""
    with _registry_lock(REGISTRY_FILE, exclusive=True):
        now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        lang = normalize_language(lang)
        prev = registry_get(stem, lang, ep_id=ep_id)
        entry = {
            "stem": stem,
            "lang": lang,
            "episode_id": ep_id if isinstance(ep_id, int) else None,
            "source": source,
            "source_path": source_path or "",
            "source_hash": source_hash or "",
            "created_ts": (prev or {}).get("created_ts", now),
            "updated_ts": now,
            "ts": now,
        }
        if target_path is not None:
            entry["target_path"] = target_path or ""
        elif prev and "target_path" in prev:
            entry["target_path"] = prev["target_path"]
        if target_hash is not None:
            entry["target_hash"] = target_hash or ""
        elif prev and "target_hash" in prev:
            entry["target_hash"] = prev["target_hash"]
        if source_kind is not None:
            entry["source_kind"] = source_kind
        if audio_id is not None:
            entry["audio_id"] = audio_id
        if retimed is not None:
            entry["retimed"] = retimed
        if matched_frac is not None:
            entry["matched_frac"] = matched_frac
        if kind is not None:
            entry["kind"] = kind
        if effective_timeline is not None:
            if isinstance(effective_timeline, list) and (
                not effective_timeline or isinstance(effective_timeline[0], dict)
            ):
                snapshot = _timeline_snapshot(effective_timeline)
            else:
                snapshot = effective_timeline
            if isinstance(snapshot, list) and _timeline_hash(snapshot):
                entry["effective_timeline"] = snapshot
                entry["effective_timeline_hash"] = _timeline_hash(snapshot)
        if timeline_kind is not None:
            entry["timeline_kind"] = timeline_kind
        if retime_status is not None:
            entry["retime_status"] = retime_status
        if retime_reason is not None:
            entry["retime_reason"] = retime_reason
        if retime_policy_version is not None:
            entry["retime_policy_version"] = str(retime_policy_version)
        # NOTE: no jimaku_hunt_* fields here — hunt backoff lives in
        # HUNT_STATE_FILE (see _jimaku_hunt_record_attempt); this ledger is
        # provenance only. Legacy rows carrying those fields are left as-is
        # (append-only) and still honored via _hunt_state_get's fallback.
        os.makedirs(os.path.dirname(REGISTRY_FILE), exist_ok=True)
        with open(REGISTRY_FILE, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(entry, ensure_ascii=False) + "\n")
            fh.flush()
            os.fsync(fh.fileno())
        return entry


def registry_delete(stem=None, lang=None, ep_id=None):
    """Delete matching registry history rows without changing unrelated rows."""
    with _registry_lock(REGISTRY_FILE, exclusive=True):
        try:
            records = load_records_jsonl(REGISTRY_FILE)
            kept = []
            for rec in records:
                drop = (ep_id is not None and rec.get("episode_id") == ep_id) or (
                    stem is not None and rec.get("stem") == stem
                )
                if drop and lang is not None and normalize_language(rec.get("lang")) != normalize_language(lang):
                    drop = False
                if not drop:
                    kept.append(rec)
            if len(kept) < len(records):
                rewrite_jsonl(REGISTRY_FILE, kept)
        except Exception:
            pass

def srt_has_ai_marker(path):
    """Marker fallback for ownership: the first SRT cue contains the AI marker."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError:
        return False
    try:
        cues = parse_srt(text)
    except Exception:
        return False
    return bool(cues) and AI_MARKER in str(cues[0].get("text") or "")


def sub_is_ai_owned(registry, ep_id, lang, media_path):
    """True when the current target sidecar is an AI-owned output."""
    stem = os.path.splitext(media_path)[0]
    normalized_lang = normalize_language(lang)
    rec = registry.get((stem, normalized_lang)) or registry.get((ep_id, normalized_lang))
    if rec is not None:
        rec = _registry_current_row(stem, normalized_lang, media_path=media_path, row=rec)
        if rec is None:
            return False
    if rec:
        target = rec.get("target_path") or target_sidecar_exists(media_path, normalized_lang)
        if "target_path" in rec or "target_hash" in rec:
            try:
                if not target or not rec.get("target_hash") or file_sha256(target) != rec.get("target_hash"):
                    return False
            except OSError:
                return False
        return rec.get("source") in ("jpn", "eng", "asr") and bool(target) and srt_has_ai_marker(target)
    return any(srt_has_ai_marker(path) for path in replaceable_target_sidecar_paths(stem, lang) if os.path.isfile(path))


def load_refined_set():
    out = set()
    for rec in load_records_jsonl(REFINE_STATE_FILE):
        if rec.get("status") == "done":
            eid = rec.get("ep_id")
            lang = rec.get("lang")
            if isinstance(eid, int) and lang:
                out.add((eid, normalize_language(lang)))
    return out


# ---------- remote APIs ----------


def get_wanted(cfg):
    r = requests.get(
        cfg["BAZARR_URL"].rstrip("/") + "/episodes/wanted",
        params={"start": 0, "length": 500},
        headers={"X-API-KEY": cfg["BAZARR_API_KEY"]},
        timeout=60,
    )
    r.raise_for_status()
    data = r.json()
    url2 = cfg.get("BAZARR_URL_2")
    if not url2:
        return data
    try:
        r2 = requests.get(
            url2.rstrip("/") + "/episodes/wanted",
            params={"start": 0, "length": 500},
            headers={"X-API-KEY": cfg.get("BAZARR_API_KEY_2") or ""},
            timeout=60,
        )
        r2.raise_for_status()
        extra = r2.json()
    except Exception as exc:
        log(f"WARNING: secondary Bazarr wanted fetch failed ({exc}); using primary only")
        return data
    by_id = {}
    for it in data.get("data") or []:
        by_id[it.get("sonarrEpisodeId")] = it
    for it in extra.get("data") or []:
        eid = it.get("sonarrEpisodeId")
        primary = by_id.get(eid)
        if primary is None:
            by_id[eid] = it
            continue
        have = {
            normalize_language(m.get("code2"))
            for m in (primary.get("missing_subtitles") or [])
            if isinstance(m, dict)
        }
        merged = list(primary.get("missing_subtitles") or [])
        for m in it.get("missing_subtitles") or []:
            if not isinstance(m, dict):
                continue
            c = normalize_language(m.get("code2"))
            m = dict(m, code2=c)
            if c not in have:
                have.add(c)
                merged.append(m)
        primary["missing_subtitles"] = merged
    items = list(by_id.values())
    return {"total": len(items), "data": items}


def get_movies(cfg):
    """All Bazarr movies: GET /movies (same shape as /episodes/wanted:
    {"total": N, "data": [...]}). Items carry radarrId, title, path
    (container /data/jellyfin/radarr-movies/...), monitored, subtitles."""
    r = requests.get(
        cfg["BAZARR_URL"].rstrip("/") + "/movies",
        params={"start": 0, "length": 500},
        headers={"X-API-KEY": cfg["BAZARR_API_KEY"]},
        timeout=60,
    )
    r.raise_for_status()
    return r.json()


def movie_candidates(cfg, target_langs):
    """Bazarr movie sweep (public): every monitored movie file lacking AI-owned
    subs for a target language, as candidate rows (kind "movie"). See
    _movie_sweep for the full contract."""
    cands, _ = _movie_sweep(cfg, target_langs)
    return cands


def _movie_sweep(cfg, target_langs):
    """Core movie sweep: returns (candidates, total_movies). NEVER raises:
    a fetch failure logs and yields ([], 0) — movies are optional per-pass
    work (unlike the series wanted list, whose caller treats a fetch error
    as a failed pass). Per movie: skip unmonitored, empty-path, or
    missing-on-NFS entries; per (stem, lang): a registry row sourced
    asr/jpn/eng already owns the sidecar (self-draining, like REGEN_LIBRARY),
    and a target-language (id) sidecar on disk blocks ASR. Candidates are
    deduped by radarrId and sorted by it; each row carries ALL missing langs:
    {"radarrId", "sonarrEpisodeId" (== radarrId, the generic loop's ep_id),
    "movieTitle", "path", "missing_subtitles", "movie": True}."""
    try:
        movies = get_movies(cfg)
    except Exception as exc:
        log(f"ERROR fetching movies list: {exc}")
        return [], 0
    data = movies.get("data") or []
    total = movies.get("total", len(data))
    target_langs = set(configured_languages(target_langs))
    done_keys = {
        ((e.get("kind") or "series"), e.get("sonarrEpisodeId"), normalize_language(e.get("language")))
        for e in load_state()
        if e.get("status") == "done"
    }
    candidates = []
    seen = set()
    for m in data:
        rid = m.get("radarrId")
        if not isinstance(rid, int) or rid in seen:
            continue
        seen.add(rid)
        if not m.get("monitored", True):
            continue
        path = m.get("path") or ""
        if not path:
            continue
        media_path = map_path(path)
        if not os.path.isfile(media_path):
            continue
        stem = os.path.splitext(media_path)[0]
        title = m.get("title") or "?"
        missing_codes = {normalize_language(ms.get("code2")) for ms in (m.get("missing_subtitles") or [])}
        missing = []
        for lang in target_langs:
            if ("movie", rid, lang) in done_keys and lang not in missing_codes:
                log(f"movies: skip {title} [{lang}] already done (state)")
                continue
            registered = _registry_current_row(stem, lang, media_path=media_path)
            if registered and registered.get("source") in ("asr", "jpn", "eng"):
                log(
                    f"movies: skip {title} [{lang}] already registered "
                    f"({registered.get('source')})"
                )
                continue
            sidecar = target_sidecar_exists(media_path, lang)
            if sidecar:
                log(
                    f"movies: skip {title} [{lang}]: target-lang sidecar exists "
                    f"({os.path.basename(sidecar)})"
                )
                continue
            missing.append({"code2": lang})
        if missing:
            candidates.append(
                {
                    "radarrId": rid,
                    "sonarrEpisodeId": rid,
                    "movieTitle": title,
                    "path": path,
                    "dateAdded": (m.get("movieFile") or {}).get("dateAdded"),
                    "missing_subtitles": missing,
                    "movie": True,
                }
            )
    candidates.sort(key=lambda x: x["radarrId"])
    return candidates, total


def get_episode(cfg, ep_id):
    r = requests.get(
        cfg["SONARR_URL"].rstrip("/") + f"/episode/{ep_id}",
        headers={"X-Api-Key": cfg["SONARR_API_KEY"]},
        timeout=60,
    )
    if r.status_code == 404:
        # ghost: episode deleted from Sonarr; GC prunes its state rows next sweep
        mark_ghost(ep_id)
    r.raise_for_status()
    return r.json()


def map_path(container_path):
    if container_path.startswith("/data/"):
        return "/mnt/nas/share/media/" + container_path[len("/data/") :]
    return container_path


def target_sidecar_exists(media_path, lang=None):
    """Return an existing regular/HI logical target, never forced-only."""
    stem = os.path.splitext(media_path)[0]
    languages = configured_languages([lang]) if lang is not None else ["id"]
    candidates = replaceable_target_sidecar_paths(stem, lang) if lang is not None else [
        path for item in languages for path in replaceable_target_sidecar_paths(stem, item)
    ]
    allowed = {os.path.basename(path).casefold() for path in candidates}
    directory = os.path.dirname(media_path) or "."
    try:
        for name in os.listdir(directory):
            if name.casefold() in allowed and os.path.isfile(os.path.join(directory, name)):
                return os.path.join(directory, name)
    except OSError:
        pass
    return None


class _AudioStreams(list):
    """probe_audio result: a stream list with a format_duration side-channel
    for the ASR cache-key signature (kept off the stream dicts so
    choose_source stays untouched)."""

    format_duration = None


def probe_audio(path):
    p = subprocess.run(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration:stream=index,codec_name,codec_type,channels,channel_layout,duration:stream_tags=language",
            "-of",
            "json",
            path,
        ],
        capture_output=True,
        text=True,
        timeout=300,
    )
    if p.returncode != 0:
        raise RuntimeError(f"ffprobe failed: {p.stderr.strip()}")
    data = json.loads(p.stdout)
    streams = _AudioStreams(
        s for s in data.get("streams", []) if s.get("codec_type") == "audio"
    )
    try:
        streams.format_duration = float((data.get("format") or {}).get("duration"))
    except (TypeError, ValueError):
        streams.format_duration = None
    return streams


def audio_stream_signature(streams):
    """Deterministic fingerprint of the audio streams (count + per-stream
    index/codec/lang/layout/duration + container format duration) -> short
    sha256. Sonarr REUSES episode ids across file upgrades, so the ASR cache
    key must key on the media's audio signature, never the episode id."""
    format_dur = getattr(streams, "format_duration", None)
    parts = [
        "{}:{}:{}:{}:{}".format(
            s.get("index"),
            s.get("codec_name"),
            (s.get("tags") or {}).get("language"),
            s.get("channel_layout") or s.get("channels"),
            s.get("duration"),
        )
        for s in streams
    ]
    sig = "count={};fmt_dur={};{}".format(len(parts), format_dur, ";".join(parts))
    return hashlib.sha256(sig.encode("utf-8")).hexdigest()[:32]


def choose_source(streams, target_lang):
    if not streams:
        return None
    lang_of = lambda s: s.get("tags", {}).get("language")
    if normalize_language(target_lang) == "en":
        eng = next((s for s in streams if normalize_language(lang_of(s)) == "en"), None)
        if eng is not None:
            return {
                "stream_index": eng["index"],
                "asr_lang": "en",
                "needs_translate": False,
                "src_lang": "eng",
            }
    jpn = next((s for s in streams if normalize_language(lang_of(s)) == "ja"), None)
    s = jpn if jpn is not None else streams[0]
    tag = lang_of(s) or ""
    asr_lang = normalize_language(tag) if normalize_language(tag) in ("ja", "en") else "en"
    return {
        "stream_index": s["index"],
        "asr_lang": asr_lang,
        "needs_translate": asr_lang != normalize_language(target_lang),
        "src_lang": tag or "?",
    }


def extract_wav(path, stream_index, out_path):
    p = subprocess.run(
        [
            "ffmpeg",
            "-nostdin",
            "-v",
            "error",
            "-y",
            "-i",
            path,
            "-map",
            f"0:{stream_index}",
            "-ac",
            "1",
            "-ar",
            "16000",
            "-c:a",
            "pcm_s16le",
            out_path,
        ],
        capture_output=True,
        text=True,
        timeout=900,
    )
    if p.returncode != 0:
        raise RuntimeError(f"ffmpeg extract failed: {p.stderr.strip()}")


_SUB_TITLE_SKIP = ("commentary", "description")


def _configured_embedded_languages(cfg):
    return configured_languages((cfg or {}).get("TARGET_LANGS") if isinstance(cfg, dict) else None) or ["ja", "en"]


_TDARR_MAX_CONCURRENT = 6
# Cap concurrent tdarr-webhook extractions: unbounded ffmpeg demuxes of
# multi-GB files over NFS saturate the link (28/289 timed out at 900s).
_TDARR_SEM = threading.BoundedSemaphore(_TDARR_MAX_CONCURRENT)


def _subtitle_streams(path):
    """All subtitle streams with mkvmerge statistics tags (NUMBER_OF_FRAMES,
    a packet-count proxy present on this library's muxes) and disposition.
    No -count_packets: that forces ffprobe to scan the whole file and times
    out over NFS on large muxes. Header-only read, fast. Raises on ffprobe
    failure."""
    p = subprocess.run(
        [
            "ffprobe",
            "-v",
            "error",
            "-select_streams",
            "s",
            "-show_entries",
            "stream=index,codec_type,codec_name:stream_disposition=default,forced,hearing_impaired:stream_tags=language,title,NUMBER_OF_FRAMES",
            "-of",
            "json",
            path,
        ],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if p.returncode != 0:
        raise RuntimeError(f"ffprobe failed: {p.stderr.strip()}")
    return json.loads(p.stdout).get("streams", [])


def _pick_best_subtitle(streams, lang):
    """Best ASS/SSA/subrip (SRT) stream for a language, skipping tracks whose title
    contains 'commentary'/'description' (drpeppershaker convention). Primary
    score is the mkvmerge NUMBER_OF_FRAMES statistics tag (no whole-file
    read); if every candidate lacks it, fall back to disposition order:
    non-forced, then not hearing_impaired, then lower index. Returns the
    stream dict or None."""
    cands = []
    for s in streams:
        tags = s.get("tags") or {}
        if s.get("codec_type") != "subtitle":
            continue
        if s.get("codec_name") not in ("ass", "ssa", "subrip"):
            continue
        if normalize_language(tags.get("language")) not in embedded_language_tags(lang):
            continue
        title = (tags.get("title") or "").lower()
        if any(k in title for k in _SUB_TITLE_SKIP):
            continue
        cands.append(s)
    if not cands:
        return None
    scored = []
    for s in cands:
        try:
            frames = int((s.get("tags") or {}).get("NUMBER_OF_FRAMES") or 0)
        except (TypeError, ValueError):
            frames = 0
        scored.append((frames, s))
    if any(f > 0 for f, _ in scored):
        return max(scored, key=lambda fs: fs[0])[1]
    return min(
        cands,
        key=lambda s: (
            int((s.get("disposition") or {}).get("forced") or 0),
            int((s.get("disposition") or {}).get("hearing_impaired") or 0),
            s["index"],
        ),
    )


def _sidecar_unchanged(stem, lang, media_path, audio_id):
    """Return true only for an unchanged registry-owned embedded source."""
    row = _registry_current_row(stem, lang, media_path=media_path)
    if (
        not row
        or row.get("source_kind") != "embedded"
        or row.get("audio_id") != audio_id
        or not row.get("source_hash")
        or not isinstance(row.get("source_path"), str)
    ):
        return False
    try:
        return (
            os.path.isfile(row["source_path"])
            and file_sha256(row["source_path"]) == row["source_hash"]
        )
    except OSError:
        return False


def _ensure_sidecar_registered(stem, lang, cur_audio):
    """Refresh embedded provenance from its owned or canonical HI sidecar."""
    normalized = normalize_language(lang)
    row = _registry_current_row(stem, normalized)
    if not row or row.get("source_kind") != "embedded" or row.get("audio_id") != cur_audio:
        return
    owned = row.get("source_path")
    if isinstance(owned, str) and os.path.isfile(owned):
        try:
            if row.get("source_hash") == file_sha256(owned):
                return
        except OSError:
            pass
    canonical = canonical_target_sidecar_path(stem, normalized)
    if not os.path.isfile(canonical):
        return
    try:
        source_hash = file_sha256(canonical)
    except OSError:
        return
    registry_upsert(
        stem, normalized, row.get("source") or "embedded",
        source_path=canonical, source_hash=source_hash,
        source_kind="embedded", ep_id=row.get("episode_id"), audio_id=cur_audio,
        retimed=row.get("retimed"), matched_frac=row.get("matched_frac"),
        kind=row.get("kind"), effective_timeline=row.get("effective_timeline"),
        timeline_kind=row.get("timeline_kind"), retime_status=row.get("retime_status"),
        retime_reason=row.get("retime_reason"),
        retime_policy_version=row.get("retime_policy_version"),
        target_path=row.get("target_path"), target_hash=row.get("target_hash"),
    )


def run_embedded_srt_sweep(cfg, budget=None):
    """Library-wide embedded-subtitle extraction (client compatibility):
    several Jellyfin clients cannot render ASS/SSA. For every video under
    JELLYFIN_MEDIA_ROOT that has an embedded configured-target subtitle
    stream but NO {stem}.{lang}.srt sidecar on disk yet, extract the best
    stream to a
    canonical HI SRT sidecar and register it source_kind 'embedded' — exactly what
    the tdarr webhook does for files it sees, but as a full-library sweep.

    Guards: per-pass budget (EMBEDDED_SRT_SWEEP_BUDGET, default 25),
    skips videos that already have ANY sidecar for the lang (never
    clobbers Jimaku/Bazarr/AI output), never touches .tmp/.recalc files.
    Returns {"extracted": n, "scanned": n, "skipped_existing": n,
    "failed": [(path, reason)]}. NEVER raises."""
    if budget is None:
        try:
            budget = int(cfg.get("EMBEDDED_SRT_SWEEP_BUDGET", 25))
        except (TypeError, ValueError):
            budget = 25
    if budget <= 0:
        return {"extracted": 0, "scanned": 0, "skipped_existing": 0, "failed": []}
    # The library lives at the mapped NAS path (same one map_path produces);
    # JELLYFIN_MEDIA_ROOT is the Jellyfin-internal view and may be empty in
    # the container — prefer the real mount when it exists.
    root = "/mnt/nas/share/media/jellyfin"
    if not os.path.isdir(root):
        root = cfg.get("JELLYFIN_MEDIA_ROOT") or JELLYFIN_MEDIA_ROOT
    extracted = 0
    scanned = 0
    skipped = 0
    failed = []
    exts = (".mkv", ".mp4", ".avi", ".ts")
    for dirpath, _dirnames, filenames in os.walk(root):
        for fn in filenames:
            if extracted >= budget:
                break
            if not fn.lower().endswith(exts):
                continue
            media = os.path.join(dirpath, fn)
            stem = os.path.splitext(media)[0]
            # which langs lack any sidecar at all?
            todo_langs = [
                lang
                for lang in _configured_embedded_languages(cfg)
                if not target_sidecar_exists(media, lang)
            ]
            if not todo_langs:
                continue
            scanned += 1
            try:
                streams = _subtitle_streams(media)
            except Exception as exc:
                failed.append((fn, f"ffprobe: {exc}"))
                continue
            for lang in todo_langs:
                best = _pick_best_subtitle(streams, lang)
                if best is None:
                    continue  # no embedded track for this lang: fine
                out = canonical_target_sidecar_path(stem, lang)
                tmp = out + ".sweep.tmp"
                try:
                    pp = subprocess.run(
                        [
                            "ffmpeg",
                            "-nostdin",
                            "-v",
                            "error",
                            "-y",
                            "-i",
                            media,
                            "-map",
                            f"0:{best['index']}",
                            "-c:s",
                            "srt",
                            "-f",
                            "srt",
                            tmp,
                        ],
                        capture_output=True,
                        text=True,
                        timeout=1800,
                    )
                    ok = (
                        pp.returncode == 0
                        and os.path.isfile(tmp)
                        and os.path.getsize(tmp) > 0
                    )
                    if not ok:
                        failed.append((fn, f"ffmpeg [{lang}]: {pp.stderr.strip()[:120]}"))
                        _silent_remove(tmp)
                        continue
                    os.replace(tmp, out)
                except Exception as exc:
                    _silent_remove(tmp)
                    failed.append((fn, f"extract [{lang}]: {exc}"))
                    continue
                try:
                    audio_id = audio_stream_signature(probe_audio(media))
                except Exception:
                    audio_id = ""
                registry_upsert(
                    stem,
                    lang,
                    "embedded",
                    source_path=out,
                    source_hash=file_sha256(out),
                    source_kind="embedded",
                    audio_id=audio_id,
                )
                extracted += 1
                log(f"embedded-srt sweep: extracted {os.path.basename(out)}")
        if extracted >= budget:
            break
    return {
        "extracted": extracted,
        "scanned": scanned,
        "skipped_existing": skipped,
        "failed": failed,
    }


def extract_subtitle_sidecars(container_path, tdarr_id="", _owner_token=None, _operation_key=None):
    """Background task for POST /tdarr-webhook: pull the single best supported
    configured-target subtitle stream per language (scored by mkvmerge
    NUMBER_OF_FRAMES)
    with a disposition fallback, skipping commentary/description titles) out
    of the mux and write deterministic {stem}.{lang}.hi.srt sidecars next to the
    video. Extracts with the exact stream index (-map 0:<index>, never a
    language matcher), writes to {stem}.{lang}.hi.srt.tmp and os.replace()s on
    success so a failed run never leaves a 0-byte file or clobbers a good
    sidecar. Every written sidecar is registered in the provenance registry
    as (stem, lang) source_kind 'embedded' with the video's audio_id and the
    sidecar's content hash. A Tdarr restart/library rescan re-fires this
    webhook for every file, so each lang whose registry row is unchanged
    (audio_id + content hash match) is skipped entirely — the rescan storm
    costs a cheap header-only audio probe, never an ffmpeg job. Concurrent
    extractions are capped by _TDARR_SEM so each demux keeps NFS bandwidth.
    Defensive: missing file, no matching streams, or ffmpeg failure -> log
    and return; never raises. Wakes the main loop on success.

    Bazarr cleanup (verified live 2026-08-12): subtitle files NOT in Bazarr's
    managed list are deleted by Bazarr when an episode refresh is forced
    (upload_srt does exactly that) — webhook-extracted {stem}.jpn.srt sidecars
    are unmanaged and can vanish. The pipeline therefore never depends on a
    sidecar surviving: the registry rows plus the embedded-extract rung
    (fresh extraction from the video) are the durable source of truth; when
    the video itself lost its subtitle streams (Tdarr remux), the Jimaku
    .ja.hi.srt rung (a) is the fallback. Bazarr cleanup settings are not
    managed from here."""
    tmp_paths = []
    try:
        media_path = map_path(container_path)
        if not os.path.isfile(media_path):
            log(
                f"tdarr-webhook: file missing on NFS: {media_path} (id={tdarr_id})"
            )
            return
        stem = os.path.splitext(media_path)[0]
        embedded_langs = _configured_embedded_languages(load_config())
        try:
            cur_audio = audio_stream_signature(probe_audio(media_path))
        except Exception as exc:
            log(f"tdarr-webhook: audio probe failed for {media_path}: {exc}")
            cur_audio = ""
        if all(
            _sidecar_unchanged(stem, lang, media_path, cur_audio)
            for lang in embedded_langs
        ):
            for lang in embedded_langs:
                _ensure_sidecar_registered(stem, lang, cur_audio)
            log(f"webhook: {os.path.basename(media_path)} embedded targets unchanged, skip")
            return
        with _TDARR_SEM:
            try:
                streams = _subtitle_streams(media_path)
            except Exception as exc:
                log(f"tdarr-webhook: ffprobe failed for {media_path}: {exc}")
                return
            extracted = []
            for lang in embedded_langs:
                if _sidecar_unchanged(stem, lang, media_path, cur_audio):
                    _ensure_sidecar_registered(stem, lang, cur_audio)
                    log(f"webhook: {os.path.basename(media_path)} {lang} unchanged, skip")
                    continue
                existing = target_sidecar_exists(media_path, lang)
                existing_row = registry_get(stem, lang)
                if existing and not (existing_row and existing_row.get("source_kind") == "embedded" and existing_row.get("audio_id") != cur_audio):
                    _ensure_sidecar_registered(stem, lang, cur_audio)
                    log(f"webhook: {os.path.basename(media_path)} {lang} sidecar already exists, preserve")
                    continue
                best = _pick_best_subtitle(streams, lang)
                if best is None:
                    _ensure_sidecar_registered(stem, lang, cur_audio)
                    log(
                        f"tdarr-webhook: no supported subtitle stream '{lang}' in {media_path}"
                    )
                    continue
                index = best["index"]
                out_path = canonical_target_sidecar_path(stem, lang)
                tmp_path = _webhook_tmp_path(out_path, container_path)
                tmp_paths.append(tmp_path)
                pp = subprocess.run(
                    [
                        "ffmpeg",
                        "-nostdin",
                        "-v",
                        "error",
                        "-y",
                        "-i",
                        media_path,
                        "-map",
                        f"0:{index}",
                        "-c:s",
                        "srt",
                        "-f",
                        "srt",
                        tmp_path,
                    ],
                    capture_output=True,
                    text=True,
                    timeout=1800,
                )
                if (
                    pp.returncode == 0
                    and os.path.isfile(tmp_path)
                    and os.path.getsize(tmp_path) > 0
                ):
                    # Serialize owner-check -> os.replace -> post-publish verification
                    # under ONE exclusive per-sidecar/registry lock. This prevents an old
                    # owner from overwriting or deleting a newer owner's output.
                    # Ledger/owner-check errors fail closed without touching unknown out_path.
                    published = False
                    with _registry_lock(REGISTRY_FILE, exclusive=True):
                        # per-sidecar file lock nested inside registry lock for NFS-sidecar safety
                        # (flock on sidecar's .lock alongside the media; best-effort, never fails closed)
                        _sidecar_lock_handle = None
                        _sidecar_lock_path = f"{out_path}.lock"
                        try:
                            try:
                                os.makedirs(os.path.dirname(_sidecar_lock_path) or ".", exist_ok=True)
                                _sidecar_lock_handle = open(_sidecar_lock_path, "a+", encoding="utf-8")
                                fcntl.flock(_sidecar_lock_handle.fileno(), fcntl.LOCK_EX)
                            except Exception:
                                _sidecar_lock_handle = None
                            # fenced pre-publish ownership check
                            fenced_ok = True
                            ledger_error = False
                            if _owner_token and _operation_key:
                                try:
                                    import webhook_ledger as _wl2
                                    _op = _wl2.get_operation(_operation_key)
                                    if not _op or _op.get("lease_owner") != _owner_token or _op.get("status") != "processing":
                                        fenced_ok = False
                                        log(f"tdarr-webhook: stale owner, skip publish for {out_path} owner={(_owner_token[:8] if _owner_token else '?')}")
                                    elif _op.get("lease_expires_at") is not None:
                                        import time as _t
                                        if int(_t.time()) > int(_op["lease_expires_at"]):
                                            fenced_ok = False
                                            log(f"tdarr-webhook: lease expired, skip publish for {out_path}")
                                except Exception as exc:
                                    ledger_error = True
                                    fenced_ok = False
                                    log(f"tdarr-webhook: ledger check failed, fail-closed skip publish for {out_path}: {exc}")
                            if not fenced_ok:
                                # fail closed: clean tmp only, never delete unknown out_path
                                try:
                                    os.remove(tmp_path)
                                except OSError:
                                    pass
                                # continue outer loop after releasing locks
                                continue
                            # owner still valid, publish atomically
                            os.replace(tmp_path, out_path)
                            published = True
                            # post-publish verification under same lock
                            if _owner_token and _operation_key:
                                try:
                                    import webhook_ledger as _wl3
                                    _op2 = _wl3.get_operation(_operation_key)
                                    if not _op2 or _op2.get("lease_owner") != _owner_token:
                                        log(f"tdarr-webhook: stale owner after publish, skip registry for {out_path}")
                                        # Do NOT delete out_path blindly: it is unknown whether
                                        # it now belongs to a newer owner; fail closed preserves it.
                                        continue
                                    if _op2.get("lease_expires_at") is not None:
                                        import time as _t2
                                        if int(_t2.time()) > int(_op2["lease_expires_at"]):
                                            log(f"tdarr-webhook: lease expired after publish, skip registry for {out_path}")
                                            continue
                                    if _op2.get("status") != "processing":
                                        log(f"tdarr-webhook: not processing after publish, skip registry for {out_path}")
                                        continue
                                except Exception as exc:
                                    log(f"tdarr-webhook: ledger post-check failed, fail-closed preserve {out_path}: {exc}")
                                    # preserve published file, skip registry
                                    continue
                            extracted.append(out_path)
                            registry_upsert(
                                stem,
                                lang,
                                "embedded",
                                source_path=out_path,
                                source_hash=file_sha256(out_path),
                                source_kind="embedded",
                                audio_id=cur_audio,
                            )
                        finally:
                            if _sidecar_lock_handle is not None:
                                try:
                                    fcntl.flock(_sidecar_lock_handle.fileno(), fcntl.LOCK_UN)
                                finally:
                                    try:
                                        _sidecar_lock_handle.close()
                                    except Exception:
                                        pass
                    # if we published but then continued due to stale after publish, tmp already replaced
                    # if not published, tmp was removed inside lock
                    if published and out_path not in extracted:
                        # stale after publish case: we preserved file but didn't count as extracted
                        # ensure we don't double-count; nothing to do
                        pass
                else:
                    log(
                        f"tdarr-webhook: ffmpeg extract [{lang}] failed for {media_path}: {pp.stderr.strip()}"
                    )
                    # fenced delete: only cleanup our own tmp
                    try:
                        # owner check before delete already ensured tmp is unique per attempt, safe to remove
                        os.remove(tmp_path)
                    except OSError:
                        pass
            if extracted:
                log(
                    f"tdarr-webhook: extracted {len(extracted)} sidecar(s) for "
                    f"{os.path.basename(media_path)}: {[os.path.basename(x) for x in extracted]}"
                )
                WAKE_EVENT.set()
    except Exception as exc:
        for tmp_path in tmp_paths:
            try:
                os.remove(tmp_path)
            except OSError:
                pass
        log(f"tdarr-webhook: extraction failed for {container_path}: {exc}")


def _media_fingerprint(path):
    st = os.stat(path)
    return {"size": st.st_size, "mtime_ns": st.st_mtime_ns}


def _webhook_tmp_path(out_path, container_path=None):
    """Unique attempt-specific tmp path for extraction (ledger attempt or uuid)."""
    try:
        import webhook_ledger as _wl
        attempt = 0
        if container_path:
            try:
                key = _wl.compute_operation_key(container_path)
                op = _wl.get_operation(key)
                if op and isinstance(op.get("attempt"), int):
                    attempt = op["attempt"]
            except Exception:
                attempt = 0
        return _wl.attempt_tmp_path(out_path, attempt)
    except Exception:
        import uuid as _uuid
        return f"{out_path}.tmp.{_uuid.uuid4().hex[:8]}"


def _load_control_key():
    """Load CONTROL_API_KEY from Docker Compose secret file, with env as test fallback.

    Priority:
      1. File at CONTROL_API_KEY_FILE env var (if set) or /run/secrets/control_api_key
      2. Environment CONTROL_API_KEY (test fallback only; never plaintext in compose)
      3. Module global CONTROL_API_KEY (hermetic tests)
    Returns stripped key or "".
    No secret values are logged.
    """
    # explicit file path from env
    candidates = []
    env_file = os.environ.get("CONTROL_API_KEY_FILE")
    if env_file:
        candidates.append(env_file.strip())
    # also try the well-known Docker secret path (may be same as above)
    candidates.append("/run/secrets/control_api_key")
    # de-duplicate while preserving order
    seen = set()
    uniq = []
    for p in candidates:
        if p and p not in seen:
            seen.add(p)
            uniq.append(p)
    for p in uniq:
        try:
            if p and os.path.isfile(p):
                with open(p, "r", encoding="utf-8") as fh:
                    val = fh.read().strip()
                    if val:
                        return val
        except OSError:
            continue
    env_key = os.environ.get("CONTROL_API_KEY", "")
    if env_key and env_key.strip():
        return env_key.strip()
    try:
        return (globals().get("CONTROL_API_KEY", "") or "").strip()
    except Exception:
        return ""

def _webhook_current_key():
    """Current CONTROL_API_KEY via secret file (env fallback for tests)."""
    return _load_control_key()


def _handle_tdarr_webhook_core(payload, fingerprint_override=None):
    """Core durable webhook handler: ledger insert, claim, processing, worker launch.
    Assumes caller already authenticated. Returns True if worker started.
    Fails closed on invalid identity (no ledger row, no worker).
    """
    file_path = payload.get("file") if isinstance(payload, dict) else None
    tdarr_id = payload.get("_id") if isinstance(payload, dict) else ""
    tdarr_id = tdarr_id or ""
    if not isinstance(file_path, str) or not file_path.strip():
        log("tdarr-webhook: received POST without 'file' field")
        return False
    # validate identity via ledger (stable mapped path hash); missing/invalid fails closed
    try:
        import webhook_ledger as _wl
    except Exception as exc:
        log(f"tdarr-webhook: ledger unavailable ({exc}), failing closed with zero worker")
        return False
    try:
        operation_key = _wl.compute_operation_key(file_path)
    except Exception as exc:
        log(f"tdarr-webhook: invalid file identity {file_path!r}: {exc}")
        return False
    # fingerprint for source-generation conflict detection
    fingerprint = fingerprint_override
    if fingerprint is None:
        try:
            mapped = map_path(file_path)
            if os.path.isfile(mapped):
                fingerprint = _media_fingerprint(mapped)
            else:
                fingerprint = None
        except Exception:
            fingerprint = None
    # durable ledger: insert_received detects fingerprint conflicts (ambiguous)
    try:
        _wl.recover_stale_leases()
    except Exception:
        pass
    try:
        op, is_new = _wl.insert_received(file_path, tdarr_id, fingerprint=fingerprint)
    except ValueError as exc:
        log(f"tdarr-webhook: identity rejected {file_path!r}: {exc}")
        return False
    except Exception as exc:
        log(f"tdarr-webhook: ledger insert failed for {file_path!r}: {exc}")
        return False
    # source-generation conflict -> ambiguous, fail closed
    try:
        cur = _wl.get_operation(operation_key)
        if cur and cur.get("status") == "ambiguous":
            log(f"tdarr-webhook: fingerprint conflict for {file_path!r}, marked ambiguous")
            return False
    except Exception:
        pass
    # atomic claim before worker launch; duplicates yield one worker - fenced by ownership token
    claimed_token = None
    try:
        claimed_token = _wl.try_claim(operation_key)
    except Exception as exc:
        log(f"tdarr-webhook: claim failed for {file_path!r}: {exc}")
        return False
    if not claimed_token:
        # already claimed/processing/terminal -> suppress duplicate
        try:
            cur = _wl.get_operation(operation_key)
            log(f"tdarr-webhook: duplicate suppressed for {file_path!r} status={cur.get('status') if cur else '?'}")
        except Exception:
            pass
        return False
    # move to processing, fenced by token; heartbeat will keep lease alive for long NFS extraction
    try:
        try:
            _wl.set_status(operation_key, "processing", expected_owner=claimed_token)
        except TypeError:
            _wl.set_status(operation_key, "processing")
    except Exception:
        pass

    def _run(token=claimed_token):
        stop_evt = threading.Event()
        hb_thread = None
        try:
            # heartbeat loop for long extraction (conservative lease handling)
            def _heartbeat_loop():
                interval = max(60, getattr(_wl, "DEFAULT_LEASE_TTL", 1800) // 3)
                while not stop_evt.wait(timeout=interval):
                    try:
                        if hasattr(_wl, "heartbeat"):
                            if not _wl.heartbeat(operation_key, token):
                                log(f"tdarr-webhook: heartbeat lost ownership for {file_path!r}, aborting finalize")
                                break
                    except Exception:
                        pass
            try:
                hb_thread = threading.Thread(target=_heartbeat_loop, daemon=True)
                hb_thread.start()
            except Exception:
                pass
            # pass ownership token and operation key for fenced publish; fallback for mocks that don't accept kwargs
            try:
                extract_subtitle_sidecars(file_path, tdarr_id=tdarr_id, _owner_token=token, _operation_key=operation_key)
            except TypeError as exc:
                if "_owner_token" in str(exc) or "_operation_key" in str(exc) or "unexpected keyword" in str(exc):
                    extract_subtitle_sidecars(file_path, tdarr_id=tdarr_id)
                else:
                    raise
            # fenced finalization: only succeed if still owner and still processing
            try:
                cur2 = _wl.get_operation(operation_key)
                if cur2 and cur2.get("lease_owner") == token and cur2.get("status") == "processing":
                    try:
                        if hasattr(_wl, "finalize_operation"):
                            _wl.finalize_operation(operation_key, token, "succeeded")
                        else:
                            _wl.set_status(operation_key, "succeeded", expected_owner=token)
                    except TypeError:
                        _wl.set_status(operation_key, "succeeded")
                else:
                    log(f"tdarr-webhook: stale owner, not finalizing {file_path!r} owner={token[:8] if token else '?'} cur_owner={(cur2.get('lease_owner') or '')[:8] if cur2 else '?'} status={cur2.get('status') if cur2 else '?'}")
            except Exception:
                pass
        except Exception as exc:
            try:
                try:
                    if hasattr(_wl, "finalize_operation"):
                        _wl.finalize_operation(operation_key, token, "failed_retryable", last_error=str(exc)[:500])
                    else:
                        _wl.set_status(operation_key, "failed_retryable", last_error=str(exc)[:500], expected_owner=token)
                except TypeError:
                    _wl.set_status(operation_key, "failed_retryable", last_error=str(exc)[:500])
            except Exception:
                pass
            log(f"tdarr-webhook: worker failed for {file_path!r}: {exc}")
        finally:
            try:
                stop_evt.set()
            except Exception:
                pass

    threading.Thread(target=_run, daemon=True).start()
    return True


def handle_tdarr_webhook_authenticated(payload, token=None, fingerprint_override=None):
    """Module-level authenticated handler for tests / internal callers."""
    return _handle_tdarr_webhook_core(payload, fingerprint_override=fingerprint_override)


def handle_tdarr_webhook_dispatch(payload, token=None):
    """Authenticated dispatch: checks token before any ledger access, returns (code, body)."""
    expected = _webhook_current_key()
    # if expected not configured, treat token=="valid" as test seam; otherwise strict
    authorized = False
    if expected:
        authorized = (token == expected)
    else:
        # no key configured -> only test token "valid" is considered authorized
        authorized = (token == "valid")
    if not authorized:
        return 401, {"error": "unauthorized"}
    ok = _handle_tdarr_webhook_core(payload)
    # always 200 on accepted webhook (even if duplicate suppressed)
    return 200, {"ok": True, "started": bool(ok)}


def get_webhook_status(token=None):
    """Authenticated status of webhook ledger: token must match CONTROL_API_KEY."""
    expected = _webhook_current_key()
    authorized = False
    if expected:
        authorized = (token == expected)
    else:
        authorized = (token == "valid")
    if not authorized:
        return 401, {"error": "unauthorized"}
    try:
        import webhook_ledger as _wl
        ops = _wl.list_operations(limit=100)
        return 200, {"operations": ops, "count": len(ops)}
    except Exception as exc:
        return 500, {"error": str(exc)}


def handle_webhook_status(token=None):
    return get_webhook_status(token=token)


# ---------- source ladder: detection + adequacy gates ----------


def assess_source_file(cfg, path, kind, duration):
    """Adequacy gates for a jpn/eng SRT translation source. kind in
    {'jpn', 'eng'}. Returns {"ok", "reason", "cues", "source_hash", "span_s"}.

    A source file is usable only when ALL gates pass:
      - >= LADDER_MIN_CUES cues (non-empty after ASS-strip)
      - >= LADDER_MIN_CHARS non-space characters in the cleaned text
      - >= LADDER_MIN_CJK ratio of CJK (jpn) or latin (eng) chars over
        non-space chars
      - time span (last cue end) within LADDER_SPAN_TOLERANCE of the video
        duration (span gate skipped when the duration is unknown)
    """
    lc = _ladder_cfg(cfg)
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError as exc:
        return {
            "ok": False,
            "reason": f"unreadable: {exc}",
            "cues": None,
            "source_hash": None,
            "span_s": None,
        }
    cues = []
    for cue in parse_srt(text):
        if _is_ai_marker_cue(cue):
            continue
        cleaned = clean_ass_text(cue["text"])
        if cleaned:
            cues.append({"start": cue["start"], "end": cue["end"], "text": cleaned})
    non_space = re.sub(r"\s", "", "".join(c["text"] for c in cues))
    n_chars = len(non_space)
    if kind == "jpn":
        ratio = len(re.findall(r"[\u3040-\u30ff\u3400-\u9fff]", non_space)) / max(
            n_chars, 1
        )
    else:
        ratio = len(re.findall(r"[A-Za-z]", non_space)) / max(n_chars, 1)
    if len(cues) < lc["min_cues"]:
        return {
            "ok": False,
            "reason": f"cues {len(cues)} < {lc['min_cues']}",
            "cues": None,
            "source_hash": None,
            "span_s": None,
        }
    if n_chars < lc["min_chars"]:
        return {
            "ok": False,
            "reason": f"chars {n_chars} < {lc['min_chars']}",
            "cues": None,
            "source_hash": None,
            "span_s": None,
        }
    if ratio < lc["min_cjk"]:
        return {
            "ok": False,
            "reason": f"{kind} ratio {ratio:.2f} < {lc['min_cjk']}",
            "cues": None,
            "source_hash": None,
            "span_s": None,
        }
    span_s = None
    if duration:
        span_s = srt_ts_ms(cues[-1]["end"])
        if span_s is not None:
            span_s /= 1000.0
            if abs(span_s - duration) / duration > lc["span_tol"]:
                return {
                    "ok": False,
                    "reason": f"span {span_s:.0f}s vs duration {duration:.0f}s",
                    "cues": None,
                    "source_hash": None,
                    "span_s": span_s,
                }
    return {
        "ok": True,
        "reason": "ok",
        "cues": cues,
        "source_hash": file_sha256(path),
        "span_s": span_s,
    }


def extract_embedded_subtitle(media_path, lang, out_path):
    """Extract the best ASS/SSA/subrip (SRT) subtitle stream for lang to out_path (SRT).
    Same picker/recipe as the tdarr webhook (mkvmerge stats, skip commentary/
    description). Returns True on success; never raises."""
    try:
        streams = _subtitle_streams(media_path)
        best = _pick_best_subtitle(streams, lang)
    except Exception:
        best = None
    if best is None:
        return False
    try:
        pp = subprocess.run(
            [
                "ffmpeg",
                "-nostdin",
                "-v",
                "error",
                "-y",
                "-i",
                media_path,
                "-map",
                f"0:{best['index']}",
                "-c:s",
                "srt",
                "-f",
                "srt",
                out_path,
            ],
            capture_output=True,
            text=True,
            timeout=1800,
        )
    except Exception:
        return False
    return (
        pp.returncode == 0
        and os.path.isfile(out_path)
        and os.path.getsize(out_path) > 0
    )


_BAZARR_JPN_TRIED = set()
_BAZARR_JPN_CACHE = {}
_BAZARR_JPN_MOVIE_TRIED = set()
_BAZARR_JPN_MOVIE_CACHE = {}


def bazarr_jpn_movie_candidate(cfg, radarr_id, media_path, tmp_dir, return_meta=False, allow_existing=True):
    """Pull-based Japanese subtitle for a movie via Bazarr (two-step providers flow):

    Mirror of bazarr_jpn_candidate but against the /movies endpoints (verified
    live swagger.json on :6767):
      1. check Bazarr's existing movie records for a jpn/ja sub whose local
         file already exists (allow_existing=True only): GET /movies?radarrid=<id>
      2. otherwise search+download via the per-movie providers flow:
         STEP A: GET {base}/providers/movies?radarrid=<id> -> {data: [candidate...]}
         (candidate: provider, subtitle, score, language ...)
         sorted by score desc, top taken.
         STEP B: POST {base}/providers/movies?radarrid=<id>
         &hi=true&forced=false&original_format=False&provider=<p>&subtitle=<s>
         -> 204 on success; subliminal writes {stem}.<lang>.srt.

    Returns the local SRT path or None. Semantics identical to
    bazarr_jpn_candidate: return_meta, allow_existing, one-shot dedup
    (_BAZARR_JPN_MOVIE_TRIED), positive cache (_BAZARR_JPN_MOVIE_CACHE).
    Never raises."""
    def _ret(path, meta):
        return (path, meta) if return_meta else path

    searched = False
    key = radarr_id
    if allow_existing:
        cached = _BAZARR_JPN_MOVIE_CACHE.get(key)
        if cached:
            return _ret(cached, "cache")
    if key in _BAZARR_JPN_MOVIE_TRIED:
        return _ret(None, None)
    _BAZARR_JPN_MOVIE_TRIED.add(key)
    if not radarr_id:
        return _ret(None, None)
    try:
        base = cfg["BAZARR_URL"].rstrip("/")
        headers = {"X-API-KEY": cfg["BAZARR_API_KEY"]}
        if allow_existing:
            r = requests.get(
                base + "/movies",
                params={"radarrid": radarr_id},
                headers=headers,
                timeout=60,
            )
            if r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    data = {}
                items = (data.get("data") or []) if isinstance(data, dict) else []
                # also handle single-object response
                if isinstance(data, dict) and not items and data.get("subtitles"):
                    items = [data]
                for it in items:
                    for s in it.get("subtitles") or []:
                        if (s.get("code2") or "") not in ("ja", "jpn", "jp"):
                            continue
                        p = map_path(s.get("path") or "")
                        if os.path.isfile(p):
                            _BAZARR_JPN_MOVIE_CACHE[key] = p
                            return _ret(p, "existing")
        # STEP A: search candidates via providers/movies
        try:
            r = requests.get(
                base + "/providers/movies",
                params={"radarrid": radarr_id},
                headers=headers,
                timeout=60,
            )
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} failed: {exc}")
            return _ret(None, None)
        if r.status_code == 429:
            reset_after = r.headers.get("x-ratelimit-reset-after") or r.headers.get("x-ratelimit-reset") or r.headers.get("Retry-After") or ""
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} HTTP 429 rate limited" + (f" reset_after={reset_after}" if reset_after else ""))
            return _ret(None, "rate_limited")
        if r.status_code != 200:
            try:
                snippet = (r.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} HTTP {r.status_code}: {snippet}")
            return _ret(None, None)
        try:
            data = r.json()
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} bad json: {exc}")
            return _ret(None, None)
        items = (data.get("data") or []) if isinstance(data, dict) else []
        if not items:
            try:
                snippet = (r.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} no candidates (HTTP {r.status_code}): {snippet}")
            return _ret(None, None)
        try:
            items_sorted = sorted(
                items,
                key=lambda c: c.get("score", 0) if isinstance(c, dict) else 0,
                reverse=True,
            )
        except Exception:
            items_sorted = items
        cand = items_sorted[0]
        provider = cand.get("provider") if isinstance(cand, dict) else None
        subtitle = cand.get("subtitle") if isinstance(cand, dict) else None
        if not provider or not subtitle:
            log(f"WARNING: ladder: bazarr jpn search movie {radarr_id} candidate missing provider/subtitle: {cand}")
            return _ret(None, None)
        # STEP B: download via providers/movies POST with provider/subtitle params
        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], "ja") if os.path.isfile(p)}
        params = {
            "radarrid": radarr_id,
            "hi": "true",
            "forced": "false",
            "original_format": "False",
            "provider": provider,
            "subtitle": subtitle,
        }
        try:
            r2 = requests.post(
                base + "/providers/movies",
                params=params,
                headers=headers,
                timeout=120,
            )
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn download movie {radarr_id} failed: {exc}")
            return _ret(None, None)
        if r2.status_code == 429:
            reset_after = r2.headers.get("x-ratelimit-reset-after") or r2.headers.get("x-ratelimit-reset") or r2.headers.get("Retry-After") or ""
            log(f"WARNING: ladder: bazarr jpn download movie {radarr_id} HTTP 429 rate limited" + (f" reset_after={reset_after}" if reset_after else ""))
            return _ret(None, "rate_limited")
        if r2.status_code != 204:
            try:
                snippet = (r2.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn download movie {radarr_id} HTTP {r2.status_code}: {snippet}")
            return _ret(None, None)
        searched = True
        stem = os.path.splitext(media_path)[0]
        cand_path = canonicalize_new_provider_sidecar(stem, "ja", before_paths)
        if cand_path:
            _BAZARR_JPN_MOVIE_CACHE[key] = cand_path
            return _ret(cand_path, "download")
        for cand_path in replaceable_target_sidecar_paths(stem, "ja"):
            if os.path.isfile(cand_path):
                _BAZARR_JPN_MOVIE_CACHE[key] = cand_path
                return _ret(cand_path, "existing")
    except Exception as exc:
        log(f"ladder: bazarr jpn query failed for movie {radarr_id}: {exc}")
    return _ret(None, "searched" if searched else None)


def bazarr_jpn_candidate(cfg, ep_id, series_id, media_path, tmp_dir, return_meta=False, allow_existing=True):
    """Pull-based Japanese subtitle for (episode, series) via Bazarr (two-step providers flow):

    1. check Bazarr's existing episode records for a jpn/ja sub whose local
        file already exists (allow_existing=True only); 2. otherwise search+download
        via the verified per-episode providers flow (Bazarr 1.6.0, hand-verified live):
        STEP A: GET {base}/providers/episodes?episodeid=<ep_id> with X-API-KEY
        -> 200 {data: [candidate...]} (candidate: provider, subtitle (opaque key),
        url, language code2 like ja, score percent int, ...); candidates are
        sorted by score desc (stable) and the top one is taken.
        STEP B: POST {base}/providers/episodes?seriesid=<sid>&episodeid=<eid>
        &hi=false&forced=false&original_format=False&provider=<cand.provider>
        &subtitle=<cand.subtitle> with X-API-KEY -> 204 on success; subliminal
        writes the sidecar next to the video ({stem}.<lang>.srt).
        original_format MUST be present as False or Bazarr returns 400.
        The old json-body POST to /episodes/subtitles with json={seriesid,
        episodeid, language, forced, hi, options} ALWAYS returned 400 - swagger
        says POST /episodes/subtitles requires multipart formData file - so that
        dead code path is replaced by the two-step flow above.
    Returns the local SRT path or None. Defensive: failures are logged and fall
    through to the next ladder rung; each (episode, series) is only attempted
    once per daemon lifetime so a broken request cannot poll on every pass.
    A FOUND path is cached positively (_BAZARR_JPN_CACHE): every target
    language of the episode reuses the same source on its own ladder pass
    without re-querying Bazarr — a one-shot dedup let the first lang consume
    the lookup and every later lang fall through to ASR.
    With return_meta=True returns (path, meta) instead, where meta tells HOW
    path was obtained — 'cache' (positive cache hit), 'existing' (a jpn sub
    Bazarr already had on disk), 'download' (the search+download POST landed
    a NEW sidecar next to the video), 'searched' (POST accepted but no
    sidecar on disk yet) — or (None, None). The jimaku hunt needs this to
    tell fresh searches apart from cached/existing results.
    When allow_existing is False (used by run_jimaku_hunt) step 1 is skipped
    entirely — both the _BAZARR_JPN_CACHE lookup and the existing-subtitle
    scan — going straight to the providers search+download so the pipeline's
    own AI-uploaded .ja.srt (registered by Bazarr as a subtitle row) does not
    short-circuit the hunt. Never raises."""
    def _ret(path, meta):
        return (path, meta) if return_meta else path

    searched = False
    key = (ep_id, series_id)
    if allow_existing:
        cached = _BAZARR_JPN_CACHE.get(key)
        if cached:
            return _ret(cached, "cache")
    if key in _BAZARR_JPN_TRIED:
        return _ret(None, None)
    _BAZARR_JPN_TRIED.add(key)
    if not ep_id or not series_id:
        return _ret(None, None)
    try:
        base = cfg["BAZARR_URL"].rstrip("/")
        headers = {"X-API-KEY": cfg["BAZARR_API_KEY"]}
        if allow_existing:
            r = requests.get(
                base + "/episodes",
                params={"episodeid[]": ep_id},
                headers=headers,
                timeout=60,
            )
            if r.status_code == 200:
                data = r.json()
                items = (data.get("data") or []) if isinstance(data, dict) else []
                for it in items:
                    for s in it.get("subtitles") or []:
                        if (s.get("code2") or "") not in ("ja", "jpn", "jp"):
                            continue
                        p = map_path(s.get("path") or "")
                        if os.path.isfile(p):
                            _BAZARR_JPN_CACHE[key] = p
                            return _ret(p, "existing")
        # STEP A: search candidates via providers/episodes
        try:
            r = requests.get(
                base + "/providers/episodes",
                params={"episodeid": ep_id},
                headers=headers,
                timeout=60,
            )
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} failed: {exc}")
            return _ret(None, None)
        if r.status_code == 429:
            reset_after = r.headers.get("x-ratelimit-reset-after") or r.headers.get("x-ratelimit-reset") or r.headers.get("Retry-After") or ""
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} HTTP 429 rate limited" + (f" reset_after={reset_after}" if reset_after else ""))
            return _ret(None, "rate_limited")
        if r.status_code != 200:
            try:
                snippet = (r.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} HTTP {r.status_code}: {snippet}")
            return _ret(None, None)
        try:
            data = r.json()
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} bad json: {exc}")
            return _ret(None, None)
        items = (data.get("data") or []) if isinstance(data, dict) else []
        if not items:
            try:
                snippet = (r.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} no candidates (HTTP {r.status_code}): {snippet}")
            return _ret(None, None)
        try:
            items_sorted = sorted(
                items,
                key=lambda c: c.get("score", 0) if isinstance(c, dict) else 0,
                reverse=True,
            )
        except Exception:
            items_sorted = items
        cand = items_sorted[0]
        provider = cand.get("provider") if isinstance(cand, dict) else None
        subtitle = cand.get("subtitle") if isinstance(cand, dict) else None
        if not provider or not subtitle:
            log(f"WARNING: ladder: bazarr jpn search ep {ep_id} candidate missing provider/subtitle: {cand}")
            return _ret(None, None)
        # STEP B: download via providers/episodes POST with provider/subtitle params
        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], "ja") if os.path.isfile(p)}
        params = {
            "seriesid": series_id,
            "episodeid": ep_id,
            "hi": "true",
            "forced": "false",
            "original_format": "False",
            "provider": provider,
            "subtitle": subtitle,
        }
        try:
            r2 = requests.post(
                base + "/providers/episodes",
                params=params,
                headers=headers,
                timeout=120,
            )
        except Exception as exc:
            log(f"WARNING: ladder: bazarr jpn download ep {ep_id} failed: {exc}")
            return _ret(None, None)
        if r2.status_code == 429:
            reset_after = r2.headers.get("x-ratelimit-reset-after") or r2.headers.get("x-ratelimit-reset") or r2.headers.get("Retry-After") or ""
            log(f"WARNING: ladder: bazarr jpn download ep {ep_id} HTTP 429 rate limited" + (f" reset_after={reset_after}" if reset_after else ""))
            return _ret(None, "rate_limited")
        if r2.status_code != 204:
            try:
                snippet = (r2.text or "")[:200]
            except Exception:
                snippet = ""
            log(f"WARNING: ladder: bazarr jpn download ep {ep_id} HTTP {r2.status_code}: {snippet}")
            return _ret(None, None)
        searched = True
        stem = os.path.splitext(media_path)[0]
        cand_path = canonicalize_new_provider_sidecar(stem, "ja", before_paths)
        if cand_path:
            _BAZARR_JPN_CACHE[key] = cand_path
            return _ret(cand_path, "download")
        for cand_path in replaceable_target_sidecar_paths(stem, "ja"):
            if os.path.isfile(cand_path):
                _BAZARR_JPN_CACHE[key] = cand_path
                return _ret(cand_path, "existing")
    except Exception as exc:
        log(f"ladder: bazarr jpn query failed for ep {ep_id}: {exc}")
    return _ret(None, "searched" if searched else None)


def extract_embedded_srt_sidecar(media_path, lang, out_path):
    """Extract the best embedded {lang} subtitle stream for media_path into
    an SRT sidecar at out_path (client compatibility: several Jellyfin
    clients cannot render ASS/SSA — everything is delivered as .srt).

    Reuses extract_embedded_subtitle's battle-tested picker (mkvmerge
    stats ranking, commentary/description skipped, ASS/SSA/subrip all
    accepted and ffmpeg-converted to plain SRT). The output is aligned by
    construction (same container timeline), so callers register it with
    source_kind 'embedded' via _adopt_embedded-style rows and the retime
    gate never touches it.

    Returns True when a sidecar was written; never raises. Callers own
    cleanup on failure."""
    try:
        return extract_embedded_subtitle(media_path, lang, out_path)
    except Exception as exc:
        log(
            f"WARNING: embedded srt extraction failed for "
            f"{os.path.basename(media_path)} [{lang}]: {exc}"
        )
        return False


def _convert_ass_to_srt(sub_path, tmp_dir):
    """ffmpeg .ass/.ssa -> srt conversion for Jimaku fansub downloads: the
    adequacy gate parses SRT only, so an .ass candidate must be converted
    BEFORE gating (same ffmpeg recipe as retime_external_subtitle's internal
    conversion; kept separate so the battle-tested retime path stays
    untouched). Returns the converted path or None (logged); the caller owns
    cleanup of both input and output."""
    token = f"{os.getpid()}_{int(time.time() * 1000)}"
    conv = os.path.join(tmp_dir or "/tmp", f"jimaku_{token}_in.srt")
    try:
        pp = subprocess.run(
            [
                "ffmpeg",
                "-nostdin",
                "-v",
                "error",
                "-y",
                "-i",
                sub_path,
                "-c:s",
                "srt",
                "-f",
                "srt",
                conv,
            ],
            capture_output=True,
            text=True,
            timeout=1800,
        )
        ok = (
            pp.returncode == 0
            and os.path.isfile(conv)
            and os.path.getsize(conv) > 0
        )
    except Exception as exc:
        ok = False
        log(f"WARNING: ladder: jimaku direct: ffmpeg .ass/.ssa -> srt failed for {sub_path}: {exc}")
    if not ok:
        _silent_remove(conv)
        return None
    return conv


# Ladder-side dedup: stems whose direct Jimaku rung was already attempted in
# this daemon lifetime (mirrors _BAZARR_JPN_TRIED / _ADOPT_TRIED). The hunt
# bypasses it via force=True — its own per-item backoff governs retry cadence.
_JIMAKU_DIRECT_TRIED = set()
_JIMAKU_KEY_WARNED = False


def jimaku_direct_candidate(
    cfg, media_path, series_title, season, episode, tmp_dir,
    ep_id=None, return_meta=False, force=False,
):
    """Direct Jimaku REST candidate for one series episode (jimaku_api.py;
    skips Bazarr's provider search entirely — verified live: raw-key
    Authorization header, anilist_id entry search, per-episode file listing,
    authenticated downloads).

    Flow: resolve the series' AniList id (anilist_cache.json-first, shared
    with fetch_glossary.py) -> entries/search?anilist_id= -> pick entry
    (exact anilist match first, else first) -> entries/{id}/files?episode=N
    -> rank candidates (release-tag/plain-S01E01 .srt preferred, fansub
    .ass/.srt next, CHS/CHT bilinguals demoted when a JPN-only file exists)
    -> download the best one into tmp_dir -> adequacy gate (.ass/.ssa
    pre-converted via ffmpeg) -> ASR-anchored re-timing gate. Only a strong
    retime is used as the effective translation timeline; uncertain retimes
    land and use the raw Jimaku source. The raw source is kept in
    {stem}.ja.hi.srt source and the effective timeline is recorded in the registry for
    idempotent future translations.

    Max ~3 Jimaku calls per attempt (search + files + download) with a tiny
    client pacing sleep between them, far below the 25 req/min limit. Jimaku
    429 propagates as fall-through-with-log (meta 'rate_limited'), never
    crashes the pass. Series episodes only: needs series_title and an int
    episode (movies stay on the Bazarr-only path).

    Returns the ladder hit dict (same shape as _external_hit: kind/
    source_path/source_hash/cues/duration_s/tmp[/align_stats]) or None.
    With return_meta=True returns (hit_or_None, meta) where meta explains a
    miss: None (not applicable/dedup), 'disabled', 'missing_key',
    'invalid_args', 'no_anilist', 'no_entry', 'no_files', 'convert_failed',
    'gate_rejected', 'retime_rejected', 'download_failed', 'rate_limited',
    'error', or 'hit'. The ladder dedups attempts per stem per daemon
    lifetime (_JIMAKU_DIRECT_TRIED); the hunt passes force=True to retry
    every hunt pass (its own backoff governs cadence). Never raises."""
    lc = _ladder_cfg(cfg)

    def _ret(hit, meta):
        return (hit, meta) if return_meta else hit

    global _JIMAKU_KEY_WARNED
    if not lc.get("jimaku_direct_enabled"):
        return _ret(None, "disabled")
    stem = os.path.splitext(media_path)[0]
    if not force:
        if stem in _JIMAKU_DIRECT_TRIED:
            return _ret(None, None)
        _JIMAKU_DIRECT_TRIED.add(stem)
    if not series_title or not isinstance(episode, int) or episode <= 0:
        return _ret(None, "invalid_args")
    api_key = str(
        cfg.get("JIMAKU_API_KEY") or os.environ.get("JIMAKU_API_KEY") or ""
    ).strip()
    if not api_key:
        if not _JIMAKU_KEY_WARNED:
            _JIMAKU_KEY_WARNED = True
            log(
                "WARNING: ladder: jimaku direct: JIMAKU_API_KEY not configured "
                "(pipeline.env); direct Jimaku access disabled"
            )
        return _ret(None, "missing_key")

    temps = []

    def _cleanup():
        for p in temps:
            _silent_remove(p)

    tag = f"S{season:02d}E{episode:02d}" if isinstance(season, int) else f"E{episode}"
    try:
        anilist_id = jimaku_api.resolve_anilist_id(cfg, series_title, log=log)
        if not anilist_id:
            log(
                f"ladder: jimaku direct: no AniList id for '{series_title}' "
                f"{tag} (ep {ep_id})"
            )
            return _ret(None, "no_anilist")
        client = jimaku_api.JimakuClient(api_key=api_key)
        try:
            entries = client.search_by_anilist(anilist_id)
        except jimaku_api.JimakuRateLimited as exc:
            log(
                f"WARNING: ladder: jimaku direct: entry search rate limited "
                f"{tag} (ep {ep_id}): {exc}"
            )
            return _ret(None, "rate_limited")
        except jimaku_api.JimakuError as exc:
            log(
                f"WARNING: ladder: jimaku direct: entry search failed for "
                f"anilist {anilist_id} {tag} (ep {ep_id}): {exc}"
            )
            return _ret(None, "error")
        entry = jimaku_api.pick_entry(entries, anilist_id)
        if entry is None:
            log(
                f"ladder: jimaku direct: no Jimaku entry for anilist "
                f"{anilist_id} '{series_title}' {tag} (ep {ep_id})"
            )
            return _ret(None, "no_entry")
        try:
            entry_id = int(entry.get("id"))
        except (TypeError, ValueError):
            log(
                f"WARNING: ladder: jimaku direct: entry without usable id for "
                f"anilist {anilist_id}: {entry}"
            )
            return _ret(None, "error")
        try:
            files = client.list_files(entry_id, episode=episode)
        except jimaku_api.JimakuRateLimited as exc:
            log(
                f"WARNING: ladder: jimaku direct: file list rate limited "
                f"{tag} (entry {entry_id}, ep {ep_id}): {exc}"
            )
            return _ret(None, "rate_limited")
        except jimaku_api.JimakuError as exc:
            log(
                f"WARNING: ladder: jimaku direct: file list failed for entry "
                f"{entry_id} {tag} (ep {ep_id}): {exc}"
            )
            return _ret(None, "error")
        ranked = jimaku_api.rank_files(files)
        if not ranked:
            log(
                f"ladder: jimaku direct: no usable subtitle files for entry "
                f"{entry_id} {tag} (ep {ep_id})"
            )
            return _ret(None, "no_files")
        best = ranked[0]
        url = best.get("url")
        name = os.path.basename(str(best.get("name") or url or "sub"))
        # keep tmp filenames filesystem-safe without touching the original
        safe_name = re.sub(r"[^A-Za-z0-9._\-\[\]() ]+", "_", name)[:150] or "sub.srt"
        dest = os.path.join(tmp_dir or "/tmp", f"jimaku_{entry_id}_{safe_name}")
        try:
            client.download(url, dest)
        except jimaku_api.JimakuRateLimited as exc:
            log(
                f"WARNING: ladder: jimaku direct: download rate limited "
                f"{tag} (ep {ep_id}): {exc}"
            )
            return _ret(None, "rate_limited")
        except (jimaku_api.JimakuError, OSError) as exc:
            log(
                f"WARNING: ladder: jimaku direct: download failed for "
                f"{os.path.basename(str(name))} (ep {ep_id}): {exc}"
            )
            return _ret(None, "download_failed")
        temps.append(dest)
        work = dest
        if os.path.splitext(work)[1].lower() in (".ass", ".ssa"):
            conv = _convert_ass_to_srt(work, tmp_dir)
            if conv is None:
                _cleanup()
                return _ret(None, "convert_failed")
            temps.append(conv)
            work = conv
        duration = media_duration_s(media_path)
        verdict = assess_source_file(cfg, work, "jpn", duration)
        if not verdict["ok"]:
            log(
                f"WARNING: ladder: jimaku direct: {os.path.basename(work)} "
                f"rejected by adequacy gate ({verdict['reason']}) {tag} (ep {ep_id})"
            )
            _cleanup()
            return _ret(None, "gate_rejected")
        raw_tl_ok, raw_tl_why = validate_srt_timeline(work, duration)
        if not raw_tl_ok:
            log(
                f"WARNING: ladder: jimaku direct: raw source failed timeline gate "
                f"({raw_tl_why}) {tag} (ep {ep_id})"
            )
            _cleanup()
            return _ret(None, "gate_rejected")
        trusted = _sidecar_trusted(stem, "jpn", media_path, dest)
        stats = None
        effective_cues = verdict["cues"]
        timeline_kind = "raw"
        if trusted:
            row = registry_get(stem, "jpn")
            stored = _effective_cues_from_row(row, verdict["cues"])
            if stored is not None:
                effective_cues = stored
                timeline_kind = row.get("timeline_kind") or "raw"
        final = work
        if lc["retime_enabled"] and not trusted:
            retimed, stats = retime_external_subtitle(
                work, media_path, cfg, tmp_dir, sub_lang="jpn"
            )
            stats = stats or {}
            if (
                retimed is not None
                and stats.get("method")
                and stats.get("method") != "order"
                and stats.get("anchors", 0) > 0
                and stats.get("retime_status") != "rejected"
                and stats.get("retime_status") != "unavailable"
            ):
                temps.append(retimed)
                verdict_a = assess_source_file(cfg, retimed, "jpn", duration)
                tl_ok, tl_why = validate_srt_timeline(retimed, duration)
                if verdict_a["ok"] and tl_ok:
                    stats["retime_status"] = "accepted"
                    effective_cues = verdict_a["cues"]
                    timeline_kind = "retimed"
                else:
                    stats["retime_status"] = "rejected"
                    stats["retime_reason"] = (
                        verdict_a.get("reason") if not verdict_a["ok"] else tl_why
                    )
                    log(
                        f"WARNING: ladder: jimaku direct: retime rejected; "
                        f"preserving raw source ({stats['retime_reason']}) "
                        f"{tag} (ep {ep_id})"
                    )
            else:
                if retimed is not None:
                    _silent_remove(retimed)
                stats.setdefault("retime_status", "rejected")
                stats.setdefault("retime_reason", "no reliable text anchors")
                log(
                    f"WARNING: ladder: jimaku direct: retime uncertain; "
                    f"preserving raw source ({stats['retime_reason']}) "
                    f"{tag} (ep {ep_id})"
                )
        final = work
        sidecar = canonical_target_sidecar_path(stem, "ja")
        try:
            shutil.copyfile(final, sidecar)
        except OSError as exc:
            log(
                f"WARNING: ladder: jimaku direct: cannot land {sidecar}: {exc}"
            )
            _cleanup()
            return _ret(None, "error")
        _register_external_sidecar(
            stem,
            "jpn",
            media_path,
            sidecar,
            verdict["source_hash"],
            ep_id,
            stats,
            effective_cues=effective_cues,
            timeline_kind=timeline_kind,
            retime_status=(stats or {}).get("retime_status"),
            retime_reason=(stats or {}).get("retime_reason"),
        )
        _cleanup()
        hit = {
            "kind": "jpn",
            "source_path": sidecar,
            "source_hash": verdict["source_hash"],
            "cues": effective_cues,
            "effective_timeline": _timeline_snapshot(effective_cues),
            "timeline_kind": timeline_kind,
            "duration_s": duration,
            "tmp": False,
        }
        if stats:
            hit["align_stats"] = stats
        log(
            f"ladder: jimaku direct: landed {os.path.basename(sidecar)} from "
            f"jimaku entry {entry_id} {tag} (ep {ep_id})"
        )
        return _ret(hit, "hit")
    except Exception as exc:
        _cleanup()
        log(f"WARNING: ladder: jimaku direct: unexpected failure {tag} (ep {ep_id}): {exc}")
        return _ret(None, "error")


def _silent_remove(path):
    if not path:
        return
    try:
        os.remove(path)
    except OSError:
        pass


# Timeline validation gate: tunables (env-overridable like the rest of the
# ladder config). MAX_PILEUP: more than this many cues sharing one identical
# start = collapsed retime. MIN_COVERAGE: [first_start,last_end] must cover
# this fraction of the video runtime. MAX_INTERNAL_GAP_FRAC: no single
# dialogue-sized hole may exceed this fraction of runtime.
TIMELINE_MAX_PILEUP = int(os.environ.get("TIMELINE_MAX_PILEUP", "2"))
TIMELINE_MIN_COVERAGE = float(os.environ.get("TIMELINE_MIN_COVERAGE", "0.80"))
TIMELINE_MAX_GAP_FRAC = float(
    os.environ.get("TIMELINE_MAX_GAP_FRAC", "0.30")
)


def validate_srt_timeline(path, duration_s=None):
    """Structural timeline gate for retimed/aligned subtitle OUTPUT.

    A retime can produce a broken timeline even when its own stats look
    plausible (Dungeon People S01E09: matched_frac=0.46 yet 4+ cues
    collapsed onto one timestamp after a 326s hole, and the file was
    written anyway). This checks the FILE ITSELF:

      - starts strictly non-decreasing
      - pileup: at most TIMELINE_MAX_PILEUP cues share one identical start
      - coverage: [first_start, last_end] spans >= TIMELINE_MIN_COVERAGE
        of the video duration (skipped when duration unknown)
      - internal gaps: no single inter-cue gap > TIMELINE_MAX_GAP_FRAC of
        the runtime (OP/eyecatch silence passes; a vanished dialogue
        block does not)

    Returns (ok, reason). Never raises.
    """
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError as exc:
        return False, f"unreadable: {exc}"
    cues = [c for c in parse_srt(text) if not _is_ai_marker_cue(c)]
    if not cues:
        return False, "no cues"
    prev_start = None
    prev_end = None
    pileup = 1
    worst_pileup = 1
    worst_gap = 0.0
    worst_gap_at = 0.0
    first_start = None
    last_end = None
    for c in cues:
        s_ms = srt_ts_ms(c["start"])
        e_ms = srt_ts_ms(c["end"])
        if s_ms is None or e_ms is None:
            return False, "unparseable timestamp"
        s, e = s_ms / 1000.0, e_ms / 1000.0
        if first_start is None:
            first_start = s
        if e > (last_end or 0.0):
            last_end = e
        if prev_start is not None and s == prev_start:
            pileup += 1
            if pileup > worst_pileup:
                worst_pileup = pileup
        else:
            pileup = 1
        if prev_start is not None and s < prev_start:
            return False, f"starts not monotonic at {s:.2f}s"
        if prev_end is not None and s - prev_end > worst_gap:
            worst_gap = s - prev_end
            worst_gap_at = prev_end
        prev_start = s
        if e > (prev_end or 0.0):
            prev_end = e
    if worst_pileup > TIMELINE_MAX_PILEUP:
        return (
            False,
            f"cue pileup: {worst_pileup} cues share one start "
            f"(max {TIMELINE_MAX_PILEUP})",
        )
    if duration_s and duration_s > 0:
        cov = ((last_end or 0.0) - (first_start or 0.0)) / duration_s
        if cov < TIMELINE_MIN_COVERAGE:
            return (
                False,
                f"coverage {cov:.2f} < {TIMELINE_MIN_COVERAGE:.2f} "
                f"(span {(last_end or 0) - (first_start or 0):.0f}s vs "
                f"video {duration_s:.0f}s)",
            )
        if worst_gap / duration_s > TIMELINE_MAX_GAP_FRAC:
            return (
                False,
                f"internal gap {worst_gap:.0f}s at {worst_gap_at:.0f}s > "
                f"{TIMELINE_MAX_GAP_FRAC:.0%} of runtime",
            )
    return True, "ok"


def _sidecar_trusted(stem, lang, media_path, sidecar_path):
    """Trust verification for the on-disk sidecar sidecar_path: TRUSTED
    (skip the re-timing gate) iff the registry row exists with a trusted
    source_kind, the row's audio_id matches the CURRENT video's audio
    signature (not a stale sidecar left behind by a Sonarr file upgrade),
    and the on-disk content hash still matches the row's source_hash (not
    clobbered by Bazarr or another writer). Trusted source_kinds:
    'embedded' — the tdarr webhook extracted it from this video's own
    subtitle stream (aligned by construction); 'external' — a Jimaku/
    Bazarr-sourced sidecar whose raw/effective timeline provenance was
    accepted by the current retime policy. Anything else is NOT TRUSTED:
    legacy retimed rows are re-evaluated, and raw fallback rows are reused
    only when their complete effective timeline is recorded."""
    raw_row = registry_get(stem, lang)
    row = _registry_current_row(stem, lang, media_path=media_path, row=raw_row)
    if not row:
        if raw_row:
            clobbered = False
            for path_key, hash_key in (("source_path", "source_hash"), ("target_path", "target_hash")):
                path = raw_row.get(path_key)
                digest = raw_row.get(hash_key)
                if path and digest:
                    try:
                        if not os.path.isfile(path) or file_sha256(path) != digest:
                            clobbered = True
                            break
                    except OSError:
                        clobbered = True
                        break
            if clobbered:
                log(f"ladder: {os.path.basename(sidecar_path)} not trusted: clobbered (hash mismatch)")
            else:
                log(f"ladder: {os.path.basename(sidecar_path)} not trusted: stale (path/audio mismatch)")
        else:
            log(f"ladder: {os.path.basename(sidecar_path)} not trusted: no current row")
        return False
    if row.get("source_kind") not in ("embedded", "external"):
        log(
            f"ladder: {os.path.basename(sidecar_path)} not trusted: "
            f"source_kind={row.get('source_kind')!r}"
        )
        return False
    try:
        cur_audio = audio_stream_signature(probe_audio(media_path))
    except Exception as exc:
        log(f"ladder: {os.path.basename(sidecar_path)} not trusted: audio probe failed: {exc}")
        return False
    if not row.get("audio_id") or row["audio_id"] != cur_audio:
        log(f"ladder: {os.path.basename(sidecar_path)} not trusted: stale (audio mismatch)")
        return False
    try:
        on_disk_hash = file_sha256(sidecar_path)
    except OSError as exc:
        log(f"ladder: {os.path.basename(sidecar_path)} not trusted: unreadable: {exc}")
        return False
    if on_disk_hash != row.get("source_hash"):
        log(f"ladder: {os.path.basename(sidecar_path)} not trusted: clobbered (hash mismatch)")
        return False
    if row.get("source_path") != sidecar_path:
        registry_upsert(
            stem, normalize_language(lang), row.get("source") or normalize_language(lang),
            source_path=sidecar_path, source_hash=on_disk_hash,
            source_kind=row.get("source_kind"), ep_id=row.get("episode_id"),
            audio_id=row.get("audio_id"), retimed=row.get("retimed"),
            matched_frac=row.get("matched_frac"), kind=row.get("kind"),
            effective_timeline=row.get("effective_timeline"),
            timeline_kind=row.get("timeline_kind"), retime_status=row.get("retime_status"),
            retime_reason=row.get("retime_reason"),
            retime_policy_version=row.get("retime_policy_version"),
            target_path=row.get("target_path"), target_hash=row.get("target_hash"),
        )
        row = registry_get(stem, normalize_language(lang)) or row
    if row.get("source_kind") == "external":
        if str(row.get("retime_policy_version")) != RETIME_POLICY_VERSION and row.get("retimed"):
            log(
                f"ladder: {os.path.basename(sidecar_path)} not trusted: "
                "legacy external retime provenance"
            )
            return False
        if row.get("retime_status") == "unavailable":
            log(
                f"ladder: {os.path.basename(sidecar_path)} not trusted: "
                "ASR retime was unavailable"
            )
            return False
        try:
            with open(sidecar_path, "r", encoding="utf-8", errors="replace") as fh:
                raw_cues = [
                    c
                    for c in parse_srt(fh.read())
                    if not _is_ai_marker_cue(c) and clean_ass_text(c["text"])
                ]
        except OSError:
            return False
        if _effective_cues_from_row(row, raw_cues) is None:
            log(
                f"ladder: {os.path.basename(sidecar_path)} not trusted: "
                "missing or invalid effective timeline"
            )
            return False
        tl_ok, tl_why = validate_srt_timeline(sidecar_path, None)
        if not tl_ok:
            log(
                f"ladder: {os.path.basename(sidecar_path)} not trusted: "
                f"raw timeline failed validation ({tl_why})"
            )
            return False
    return True


def _register_external_sidecar(
    stem,
    kind,
    media_path,
    cand,
    source_hash,
    ep_id=None,
    stats=None,
    effective_cues=None,
    timeline_kind=None,
    retime_status=None,
    retime_reason=None,
):
    """Register the raw external sidecar and its effective timeline.

    source_hash always identifies the on-disk/raw sidecar. When an accepted
    retime was used for translation, effective_cues records the complete
    temporary timeline so later passes can reproduce it without re-running a
    nondeterministic decision. Rejected retimes record a raw effective
    timeline, which makes the safe fallback idempotent.
    """
    if not source_hash:
        return
    try:
        row = registry_get(stem, kind)
        effective_timeline = _timeline_snapshot(effective_cues) if effective_cues is not None else None
        if (
            row
            and row.get("source_kind") == "external"
            and row.get("source_hash") == source_hash
            and str(row.get("retime_policy_version")) == RETIME_POLICY_VERSION
            and (
                effective_timeline is None
                or row.get("effective_timeline_hash") == _timeline_hash(effective_timeline)
            )
        ):
            return
        try:
            cur_audio = audio_stream_signature(probe_audio(media_path))
        except Exception:
            cur_audio = ""
        registry_upsert(
            stem,
            kind,
            kind,
            source_path=cand,
            source_hash=source_hash,
            source_kind="external",
            ep_id=ep_id if isinstance(ep_id, int) else None,
            audio_id=cur_audio,
            retimed=(stats or {}).get("method"),
            matched_frac=(stats or {}).get("matched_frac"),
            effective_timeline=effective_timeline,
            timeline_kind=timeline_kind or "raw",
            retime_status=retime_status,
            retime_reason=retime_reason,
            retime_policy_version=RETIME_POLICY_VERSION,
        )
        log(
            f"ladder: registered external {kind} sidecar "
            f"{os.path.basename(cand)} (timeline={timeline_kind or 'raw'}, "
            f"retime={retime_status or 'not-applied'})"
        )
    except Exception as exc:
        log(f"WARNING: ladder: external sidecar registration failed for {cand}: {exc}")


_ADOPT_TRIED = set()


def _adopt_embedded(stem, kind, media_path, cand, tmp_dir=None):
    """Adoption for untrusted webhook extracts: a sidecar whose basename is
    exactly {stem}.{kind}.srt (webhook product; NEVER .ja* Jimaku files) with
    NO registry row may still BE the current embedded stream — the row was
    lost (pre-ledger extract) or the file survived Bazarr cleanup. Verify by
    re-extracting the current embedded track and comparing content hashes; on
    a match, register source_kind 'embedded' so the sidecar is trusted as
    aligned-by-construction and the re-timing gate is skipped. One attempt
    per (stem, kind) per daemon lifetime. Never raises; returns True only
    when the sidecar is now registry-trusted."""
    key = (stem, kind)
    if key in _ADOPT_TRIED:
        return False
    _ADOPT_TRIED.add(key)
    try:
        base_name = os.path.splitext(os.path.basename(media_path))[0]
        alias_names = {"jpn": ("ja", "jpn", "jp"), "eng": ("en", "eng", "enm")}.get(kind, (normalize_language(kind),))
        allowed = {base_name + "." + alias + ".srt" for alias in alias_names}
        if os.path.basename(cand) not in allowed:
            return False
        normalized = normalize_language(kind)
        existing = registry_get(stem, normalized)
        if existing and _registry_current_row(stem, normalized, media_path=media_path, row=existing):
            return False
        if not os.path.isfile(cand):
            return False
        tmp = os.path.join(
            tmp_dir or "/tmp", f"ladder_adopt_{os.getpid()}_{kind}.srt"
        )
        try:
            if not extract_embedded_subtitle(media_path, kind, tmp):
                return False
            if (
                not os.path.isfile(tmp)
                or file_sha256(tmp) != file_sha256(cand)
            ):
                return False
        finally:
            _silent_remove(tmp)
        try:
            cur_audio = audio_stream_signature(probe_audio(media_path))
        except Exception:
            cur_audio = ""
        registry_upsert(
            stem, normalized, "embedded",
            source_path=cand, source_hash=file_sha256(cand),
            source_kind="embedded", audio_id=cur_audio,
            ep_id=existing.get("episode_id") if existing else None,
            kind=existing.get("kind") if existing else None,
        )
        log(
            f"ladder: adopted embedded {kind} sidecar "
            f"{os.path.basename(cand)} (hash match with current stream)"
        )
        return _sidecar_trusted(stem, kind, media_path, cand)
    except Exception as exc:
        log(f"ladder: adoption failed for {cand}: {exc}")
        return False


def retime_external_cues(
    sub_cues,
    asr_cues,
    sub_lang,
    video_duration_s,
    asr_lang=None,
    text_threshold=None,
    max_ratio=None,
    min_anchor_frac=None,
    min_anchors=None,
    max_anchor_p75_ms=None,
    max_anchor_p90_ms=None,
):
    """Re-time external subtitle cues against ASR speech anchors.

    sub_cues: list of {"start": ms (float), "end": ms (float), "text": str}.
    asr_cues: list of {"start", "end", "text"} from the ASR cache (already ms).
    sub_lang: "jpn"|"eng" — text anchoring applies when the ASR reference
      speaks the sub's language: sub_lang == "jpn" (ja ASR) or sub_lang ==
      "eng" AND asr_lang == "en" (eng ASR, e.g. movies with eng audio).
      Otherwise the order-preserving mapping is used (their text cannot
      match the ASR reference).
    asr_lang: the language code the anchor cues were transcribed with
      ("ja"/"en", from the choose_source decision in _retime_anchor_asr).
    video_duration_s: container duration in seconds (or None) — the last cue's
      end is clamped to it.

    Strategy 1 (text anchors, jpn/en): normalize both texts (strip speaker tags
    （…） and music notes, drop punctuation and the long-vowel mark, fold
    katakana<->hiragana), score by character-bigram Jaccard; the best ASR cue
    anchors when the score >= text_threshold (0.55). 1 sub cue -> best ASR
    cue; 1 ASR cue may anchor multiple sub cues. Texts shorter than 2
    normalized chars are never anchor candidates (junk on 1-char SDH cues).
    Anchor regressions (later sub cue -> earlier asr cue) are dropped. ASR
    segments shorter than 100ms (whisper zero-length/20ms artifacts) are
    filtered before any mapping.
    When the anchored fraction is below the acceptance threshold, or the
    anchors are otherwise inconsistent, the retime is rejected and the caller
    preserves the raw external timeline. Positional/order mapping is never
    used.

    Strategy 2 (no reliable-anchor fallback): if the ASR reference cannot
    produce enough monotonic text anchors, the retime is REJECTED. The caller
    must preserve the raw external timeline. Positional/order mapping is never
    used because it can map unrelated release cues to the wrong speech.

    Re-timing: an anchored cue starts at its ASR cue start, end = start +
    original duration; an unanchored cue interpolates the start shift between
    its neighbor anchors (nearest-anchor shift before the first / after the
    last anchor).
    SDH/music cues (♬, （音）, speaker-only) interpolate like any unanchored
    cue — never dropped. Ends are clamped to next_start - 0.05s (last cue:
    video duration), starts never negative.

    The acceptance gate requires a strong anchor fraction and a consistent
    release offset/drift: anchors must span the source, and their residuals
    from a robust linear timing fit must stay below configured p75/p90 limits.
    A monotonic, structurally valid but semantically unreliable retime is still
    rejected.

    Degenerate-output guard: the retimed cues must have non-decreasing starts,
    every start >= 0 and every duration >= 0.05s. No order retry is performed.

    Returns (retimed_cues, stats) or (None, stats) on reject. Marker cues are
    returned unchanged ahead of the retimed dialogue cues. stats =
    {"method": "text"|"mixed", "anchors": n, "total": m,
    "matched_frac": n/m, "anchor_p75_residual_ms": n,
    "anchor_p90_residual_ms": n, "reason": str?}. Deterministic pure logic —
    no I/O."""
    marker_cues = [c for c in sub_cues if _is_ai_marker_cue(c)]
    sub_cues = [c for c in sub_cues if not _is_ai_marker_cue(c)]
    total = len(sub_cues)
    if text_threshold is None:
        text_threshold = RETIME_TEXT_THRESHOLD
    if min_anchor_frac is None:
        min_anchor_frac = RETIME_ACCEPT_MIN_ANCHOR_FRAC
    if min_anchors is None:
        min_anchors = RETIME_MIN_ANCHORS
    if max_anchor_p75_ms is None:
        max_anchor_p75_ms = RETIME_MAX_ANCHOR_P75_MS
    if max_anchor_p90_ms is None:
        max_anchor_p90_ms = RETIME_MAX_ANCHOR_P90_MS
    if not sub_cues or not asr_cues:
        return None, {
            "method": None,
            "anchors": 0,
            "total": total,
            "matched_frac": 0.0,
            "reason": "no subtitle or ASR cues",
        }
    # whisper-artifact segments poison text matching and output validation.
    asr_cues = [c for c in asr_cues if c["end"] - c["start"] >= 100.0]
    if not asr_cues:
        return None, {
            "method": None,
            "anchors": 0,
            "total": total,
            "matched_frac": 0.0,
            "reason": "no usable ASR segments",
        }
    anchors = (
        _retime_text_anchors(sub_cues, asr_cues, text_threshold)
        if sub_lang == "jpn" or (sub_lang == "eng" and asr_lang == "en")
        else []
    )
    matched_frac = len(anchors) / float(total) if total else 0.0
    stats = {
        "method": "text" if len(anchors) == total and anchors else "mixed" if anchors else None,
        "anchors": len(anchors),
        "total": total,
        "matched_frac": matched_frac,
    }
    if not anchors:
        stats["reason"] = "no reliable text anchors"
        return None, stats
    if matched_frac < min_anchor_frac:
        stats["reason"] = (
            f"anchor coverage {matched_frac:.2f} < {min_anchor_frac:.2f}"
        )
        return None, stats
    if len(anchors) < min_anchors:
        stats["reason"] = f"anchors {len(anchors)} < {min_anchors}"
        return None, stats
    # A release can have a constant offset or gentle speed drift. Fit that
    # affine relationship and reject anchors with large nonlinear residuals.
    xs = [sub_cues[i]["start"] / 1000.0 for i, _ in anchors]
    ys = [asr_cues[j]["start"] / 1000.0 for _, j in anchors]
    mean_x = sum(xs) / len(xs)
    mean_y = sum(ys) / len(ys)
    denom = sum((x - mean_x) ** 2 for x in xs)
    slope = (
        sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys)) / denom
        if denom
        else 1.0
    )
    intercept = mean_y - slope * mean_x
    residuals = sorted(
        abs(y - (slope * x + intercept)) * 1000.0 for x, y in zip(xs, ys)
    )
    q75 = residuals[max(0, min(len(residuals) - 1, int(len(residuals) * 0.75) - 1))]
    q90 = residuals[max(0, min(len(residuals) - 1, int(len(residuals) * 0.90) - 1))]
    first_anchor = sub_cues[anchors[0][0]]["start"]
    last_anchor = sub_cues[anchors[-1][0]]["start"]
    source_span = max(1.0, sub_cues[-1]["start"] - sub_cues[0]["start"])
    anchor_span_frac = (last_anchor - first_anchor) / source_span
    stats.update(
        {
            "anchor_p75_residual_ms": round(q75, 3),
            "anchor_p90_residual_ms": round(q90, 3),
            "anchor_span_frac": round(anchor_span_frac, 4),
            "anchor_slope": round(slope, 8),
            "anchor_offset_median_ms": round(
                statistics.median([y - x for x, y in zip(xs, ys)]) * 1000.0,
                3,
            ),
        }
    )
    if anchor_span_frac < 0.50:
        stats["reason"] = f"anchor span {anchor_span_frac:.2f} < 0.50"
        return None, stats
    if q75 > max_anchor_p75_ms or q90 > max_anchor_p90_ms:
        stats["reason"] = (
            f"anchor residuals p75={q75:.0f}ms p90={q90:.0f}ms "
            f"> {max_anchor_p75_ms:.0f}/{max_anchor_p90_ms:.0f}ms"
        )
        return None, stats
    method = stats["method"]
    duration_ms = video_duration_s * 1000.0 if video_duration_s else None

    def _build(use_anchors):
        """Build a retimed dialogue timeline from validated anchors."""
        anchored_idx = {i for i, _ in use_anchors}
        starts = [0.0] * total
        for i, j in use_anchors:
            starts[i] = asr_cues[j]["start"]
        if len(use_anchors) < total:
            pts = sorted(use_anchors)
            for i in range(total):
                if i in anchored_idx:
                    continue
                t_i = sub_cues[i]["start"]
                prev = next((pt for pt in reversed(pts) if pt[0] < i), None)
                nxt = next((pt for pt in pts if pt[0] > i), None)
                if prev is not None and nxt is not None:
                    t_p, j_p = prev
                    t_n, j_n = nxt
                    s_p = asr_cues[j_p]["start"] - sub_cues[t_p]["start"]
                    s_n = asr_cues[j_n]["start"] - sub_cues[t_n]["start"]
                    denom = sub_cues[t_n]["start"] - sub_cues[t_p]["start"]
                    frac = (t_i - sub_cues[t_p]["start"]) / denom if denom else 0.0
                    starts[i] = t_i + s_p + frac * (s_n - s_p)
                elif prev is not None:
                    j_p = prev[1]
                    starts[i] = t_i + asr_cues[j_p]["start"] - sub_cues[prev[0]]["start"]
                elif nxt is not None:
                    j_n = nxt[1]
                    starts[i] = t_i + asr_cues[j_n]["start"] - sub_cues[nxt[0]]["start"]
                else:
                    return None
        out = []
        for i in range(total):
            start = max(0.0, starts[i])
            dur = max(0.0, sub_cues[i]["end"] - sub_cues[i]["start"])
            floor = start + min(50.0, dur)
            end = start + dur
            if i < total - 1:
                nxt = max(0.0, starts[i + 1])
                end = max(floor, min(end, nxt - 50.0))
            elif duration_ms:
                end = max(floor, min(end, duration_ms))
            if end < start:
                end = start
            out.append({"start": start, "end": end, "text": sub_cues[i]["text"]})
        return out

    def _valid(cues):
        prev = None
        for i, c in enumerate(cues):
            if c["start"] < 0.0:
                return False, f"cue {i} start<0"
            dur = (c["end"] - c["start"]) / 1000.0
            if dur < 0.05:
                return False, f"cue {i} dur={dur:.2f}s"
            if prev is not None and c["start"] < prev:
                return False, f"cue {i} start {c['start']} < prev {prev}"
            prev = c["start"]
        return True, None

    out = _build(anchors)
    if out is None:
        stats["reason"] = "unable to interpolate between anchors"
        return None, stats
    ok, detail = _valid(out)
    if not ok:
        stats["reason"] = detail
        return None, stats
    return marker_cues + out, stats


def _retime_norm_text(text):
    """Normalize a cue text for anchor matching: strip ASS/SSA styling and
    speaker tags （…） (SDH), drop music notes and the long-vowel mark, fold
    katakana -> hiragana, drop punctuation/whitespace, lowercase latin."""
    text = clean_ass_text(text)
    text = re.sub(r"[（(][^（）()]*[）)]", "", text)
    for ch in ("♪", "♬", "♫", "♩", "ー"):
        text = text.replace(ch, "")
    text = "".join(
        chr(ord(ch) - 0x60) if 0x30A1 <= ord(ch) <= 0x30FA else ch for ch in text
    )
    return re.sub(r"[\W_]+", "", text, flags=re.UNICODE).lower()


def _bigram_jaccard(a, b):
    """Character-bigram Jaccard similarity of two normalized texts."""
    if not a or not b:
        return 0.0
    if len(a) == 1 or len(b) == 1:
        return 1.0 if a == b else 0.0
    ga = {a[i : i + 2] for i in range(len(a) - 1)}
    gb = {b[i : i + 2] for i in range(len(b) - 1)}
    if not ga or not gb:
        return 1.0 if a == b else 0.0
    inter = len(ga & gb)
    if inter == 0:
        return 0.0
    return inter / float(len(ga | gb))


def _retime_text_anchors(sub_cues, asr_cues, threshold):
    """Best-match text anchors: [(sub_idx, asr_idx)] — every sub cue whose
    best ASR character-bigram Jaccard score >= threshold anchors to that ASR
    cue. One ASR cue may anchor many sub cues; cues whose normalized text is
    empty (SDH/music/speaker-only) or shorter than 2 chars never anchor.
    Returns the MONOTONIC subset: regressions (a later sub cue anchoring to
    an earlier asr cue) are dropped so the retimed starts stay ordered."""
    norm_sub = [_retime_norm_text(c["text"]) for c in sub_cues]
    norm_asr = [_retime_norm_text(c["text"]) for c in asr_cues]
    anchors = []
    for i, ns in enumerate(norm_sub):
        if len(ns) < 2:  # 1-char junk (e.g. "あっ！" -> "あっ") never anchors
            continue
        best_j, best_s = None, 0.0
        for j, na in enumerate(norm_asr):
            if len(na) < 2:
                continue
            s = _bigram_jaccard(ns, na)
            if s > best_s:
                best_j, best_s = j, s
        if best_j is not None and best_s >= threshold:
            anchors.append((i, best_j))
    # False matches can anchor a later sub cue to an EARLIER asr cue
    # (Jaadugar S01E04: sub#77 -> asr#88 while the previous anchor was
    # asr#177; sub#272 -> asr#159). A regression inverts the retimed starts
    # and the degenerate guard would then discard EVERY anchor. Keep only
    # the monotonic subset: drop any anchor whose asr index goes BACKWARD
    # relative to the best (max) asr index seen so far.
    kept, max_j = [], -1
    for i, j in anchors:
        if j < max_j:
            continue
        max_j = j
        kept.append((i, j))
    return kept


def _infer_sub_lang(cues):
    """Infer a sidecar's language kind ("jpn"/"eng") from its cue text: CJK
    ratio >= 0.3 -> jpn, else eng (mirrors assess_source_file's ratio)."""
    non_space = re.sub(r"\s", "", "".join(c["text"] for c in cues))
    if not non_space:
        return "jpn"
    cjk = len(re.findall(r"[\u3040-\u30ff\u3400-\u9fff]", non_space))
    return "jpn" if cjk / float(len(non_space)) >= 0.3 else "eng"


def _retime_anchor_asr(cfg, media_path, sub_lang):
    """ASR speech anchors for a media file: probe the audio, look up the ASR
    cache ((audio_id, asr_lang) — the choose_source decision derives ja for
    jpn subs and en when sub_lang is "eng" and the audio is an eng stream,
    e.g. movies); on a miss, extract the wav exactly like the ASR rung
    (extract_wav on the choose_source stream) and transcribe with
    asr_cues(cfg, wav, asr_lang), caching the cues. NEVER raises: returns
    (None, None) on any failure (the caller then uses the sidecar as-is,
    logged)."""
    try:
        streams = probe_audio(media_path)
        audio_id = audio_stream_signature(streams)
        decision = choose_source(
            streams, "en" if sub_lang == "eng" else "ja"
        )
        if decision is None:
            log(f"ladder: retime: no audio streams in {media_path}")
            return None, None
        asr_lang = decision["asr_lang"]
        cached = asr_cache_get(audio_id, asr_lang, media_path)
        if cached:
            return cached, asr_lang
        tmp_dir = cfg.get("TMP_DIR") or os.environ.get("TMP_DIR") or "/tmp"
        try:
            os.makedirs(tmp_dir, exist_ok=True)
        except OSError:
            pass
        wav = os.path.join(tmp_dir, f"retime_anchor_{os.getpid()}_{sub_lang}.wav")
        try:
            extract_wav(media_path, decision["stream_index"], wav)
            cues = asr_cues(cfg, wav, asr_lang) or []
        finally:
            _silent_remove(wav)
        asr_cache_put(audio_id, asr_lang, media_path, cues)
        return cues, asr_lang
    except Exception as exc:
        log(f"ladder: retime: ASR anchors unavailable for {media_path}: {exc}")
        return None, None


def retime_external_subtitle(sub_path, media_path, cfg, tmp_dir=None, sub_lang=None):
    """ASR-anchored re-timing for external (Jimaku/Bazarr-sourced) jpn/eng
    subtitle sidecars: converts .ass/.ssa inputs to a temp SRT with ffmpeg
    (never modifies the input), parses the cues, pulls the episode's ASR
    speech anchors (_retime_anchor_asr), re-times every cue
    (retime_external_cues) and writes the retimed SRT as another temp file
    under tmp_dir (TMP_DIR env / '/tmp' fallback). The caller owns cleanup of
    the retimed output; the conversion temp is removed here.

    Returns (retimed_srt_path, stats) when the sidecar is usable — an accepted
    retime, or the raw sidecar AS-IS when ASR anchors are unavailable
    (stats['retime_status'] == 'unavailable'). Returns (None, stats) when ASR
    exists but the semantic retime gate rejects it; callers must preserve the
    raw source in that case. Positional/order mapping is never accepted.
    A sidecar with an accepted effective timeline is registered by the caller
    (_register_external_sidecar) with both the raw source hash and the
    effective timeline, so subsequent passes are idempotent. sub_lang
    ("jpn"/"eng") enables text anchoring (eng only when the anchor ASR speaks
    en — movies with eng audio); when None it is inferred from the cue text
    after removing the marker cue."""
    tmp_dir = tmp_dir or os.environ.get("TMP_DIR") or "/tmp"
    try:
        os.makedirs(tmp_dir, exist_ok=True)
    except OSError as exc:
        log(f"WARNING: ladder: retime: cannot create {tmp_dir}: {exc}")
        return None, {"method": None, "anchors": 0, "total": 0, "matched_frac": 0.0}
    token = f"{os.getpid()}_{int(time.time() * 1000)}"
    work = sub_path
    conv = None
    if os.path.splitext(sub_path)[1].lower() in (".ass", ".ssa"):
        conv = os.path.join(tmp_dir, f"retime_{token}_in.srt")
        try:
            pp = subprocess.run(
                [
                    "ffmpeg",
                    "-nostdin",
                    "-v",
                    "error",
                    "-y",
                    "-i",
                    sub_path,
                    "-c:s",
                    "srt",
                    "-f",
                    "srt",
                    conv,
                ],
                capture_output=True,
                text=True,
                timeout=1800,
            )
            ok = (
                pp.returncode == 0
                and os.path.isfile(conv)
                and os.path.getsize(conv) > 0
            )
        except Exception as exc:
            ok = False
            log(
                f"WARNING: ladder: retime: ffmpeg .ass/.ssa -> srt failed for {sub_path}: {exc}"
            )
        if not ok:
            _silent_remove(conv)
            log(f"WARNING: ladder: retime: ffmpeg .ass/.ssa -> srt failed for {sub_path}")
            return None, {"method": None, "anchors": 0, "total": 0, "matched_frac": 0.0}
        work = conv
    try:
        with open(work, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError as exc:
        log(f"WARNING: ladder: retime: unreadable {work}: {exc}")
        _silent_remove(conv)
        return None, {"method": None, "anchors": 0, "total": 0, "matched_frac": 0.0}
    parsed = parse_srt(text)
    if not parsed:
        _silent_remove(conv)
        return None, {"method": None, "anchors": 0, "total": 0, "matched_frac": 0.0}
    sub_ms = []
    for c in parsed:
        s, e = srt_ts_ms(c["start"]), srt_ts_ms(c["end"])
        if s is None or e is None:
            sub_ms = None
            break
        sub_ms.append({"start": s, "end": e, "text": c["text"]})
    if sub_ms is None:
        log(f"WARNING: ladder: retime: unparseable timestamps in {sub_path}")
        _silent_remove(conv)
        return None, {"method": None, "anchors": 0, "total": 0, "matched_frac": 0.0}
    if sub_lang is None:
        sub_lang = _infer_sub_lang(
            [c for c in sub_ms if not _is_ai_marker_cue(c)]
        )
    lc = _ladder_cfg(cfg)
    anchors, asr_lang = _retime_anchor_asr(cfg, media_path, sub_lang)
    if anchors is None:
        log(
            f"ladder: retime: no ASR anchors for {os.path.basename(media_path)}; "
            f"using {os.path.basename(sub_path)} as-is"
        )
        retimed, stats = sub_ms, {
            "method": None,
            "anchors": 0,
            "total": len([c for c in sub_ms if not _is_ai_marker_cue(c)]),
            "matched_frac": 0.0,
            "retime_status": "unavailable",
            "reason": "ASR anchors unavailable",
        }
    else:
        duration = media_duration_s(media_path)
        retimed, stats = retime_external_cues(
            sub_ms,
            anchors,
            sub_lang,
            duration,
            asr_lang=asr_lang,
            text_threshold=lc["retime_text_threshold"],
            max_ratio=lc["retime_max_ratio"],
            min_anchor_frac=lc["retime_accept_min_anchor_frac"],
            min_anchors=lc["retime_min_anchors"],
            max_anchor_p75_ms=lc["retime_max_anchor_p75_ms"],
            max_anchor_p90_ms=lc["retime_max_anchor_p90_ms"],
        )
        if retimed is None:
            ratio = (stats.get("anchors", 0) / stats.get("total", 1)) if stats.get("total") else 0.0
            reason = stats.get("reason") or "retime acceptance gate"
            stats["retime_status"] = "rejected"
            log(
                f"WARNING: ladder: retime: rejected {sub_path} "
                f"(method={stats.get('method')}, anchors={stats.get('anchors')}/{stats.get('total')}, "
                f"ratio={ratio:.2f}, reason={reason})"
            )
            _silent_remove(conv)
            return None, stats
        stats["retime_status"] = "accepted"
    out = os.path.join(tmp_dir, f"retime_{token}_out.srt")
    write_srt(retimed, [c["text"] for c in retimed], out)
    _silent_remove(conv)
    return out, stats


def detect_ladder_source(
    cfg, media_path, target_lang, tmp_dir, ep_id=None, series_id=None,
    series_title=None, season=None, episode=None,
):
    """Pull-based source ladder for one wanted (episode, target_lang) row.
    Order: jpn (external sidecar regular/HI provider sources/ their
    .jpn.hi/.ja.hi HI variants -> embedded
    jpn stream -> Bazarr jpn -> DIRECT Jimaku REST) -> eng (external
    {stem}.eng.srt -> embedded eng stream) -> asr. The direct Jimaku rung
    (JIMAKU_DIRECT_ENABLED, series episodes only: needs series_title +
    episode; see jimaku_direct_candidate) lands {stem}.jpn.srt like a Bazarr
    download when everything else missed. Every jpn/eng candidate must pass
    the adequacy gates. External sidecars additionally use the ASR-anchored
    retiming gate only when the sidecar is not already trusted; an uncertain
    retime preserves the validated raw sidecar. Never raises; returns
    {"kind": "jpn"|"eng"|"asr", "source_path", "source_hash", "cues",
    "effective_timeline", "timeline_kind", "duration_s", "tmp", "align_tmp",
    "align_stats"}. kind 'asr' = caller falls back to the existing ASR path."""
    stem = os.path.splitext(media_path)[0]
    duration = None
    lc = _ladder_cfg(cfg)

    def _gate(cand, kind):
        nonlocal duration
        if duration is None:
            duration = media_duration_s(media_path)
        return assess_source_file(cfg, cand, kind, duration)

    def _hit(kind, path, verdict, tmp=False):
        cues = verdict["cues"]
        return {
            "kind": kind,
            "source_path": path,
            "source_hash": verdict["source_hash"],
            "cues": cues,
            "effective_timeline": _timeline_snapshot(cues),
            "timeline_kind": "raw",
            "duration_s": duration,
            "tmp": tmp,
        }

    def _external_hit(cand, kind):
        """Use an external sidecar without unsafe positional retiming.

        A failed/uncertain retime keeps the validated raw external source as
        the hit. This is safer than silently translating from a temporary
        nonlinear timeline, and the raw fallback is recorded so it is stable
        on later passes.
        """
        verdict = _gate(cand, kind)
        if not verdict["ok"]:
            return None
        hit = _hit(kind, cand, verdict)
        row = registry_get(stem, kind)
        trusted = _sidecar_trusted(stem, kind, media_path, cand)
        if not trusted:
            trusted = _adopt_embedded(stem, kind, media_path, cand, tmp_dir)
        if not trusted:
            raw_tl_ok, raw_tl_why = validate_srt_timeline(cand, duration)
            if not raw_tl_ok:
                log(
                    f"WARNING: ladder: {kind} sidecar {os.path.basename(cand)} "
                    f"raw source failed timeline gate ({raw_tl_why}); skipping"
                )
                return None
        # The jpn sidecar is itself the Japanese target. Keep its raw release
        # timeline on disk; retiming is only for translated targets. This also
        # prevents process_ladder from overwriting canonical HI target with a
        # temporary effective timeline when the source candidate has that
        # exact path.
        if target_lang == "ja" and kind == "jpn":
            hit["timeline_kind"] = "raw"
            hit["effective_timeline"] = _timeline_snapshot(verdict["cues"])
            return hit
        if trusted:
            if row and row.get("source_kind") == "external":
                effective = _effective_cues_from_row(row, verdict["cues"])
                if effective is None:
                    trusted = False
                else:
                    hit["cues"] = effective
                    hit["effective_timeline"] = _timeline_snapshot(effective)
                    hit["timeline_kind"] = row.get("timeline_kind") or "raw"
            if trusted:
                return hit
        if not (lc["retime_enabled"] and not trusted):
            return hit
        retimed, stats = retime_external_subtitle(
            cand, media_path, cfg, tmp_dir, sub_lang=kind
        )
        stats = stats or {}
        if retimed is None:
            reason = stats.get("reason") or "retime acceptance gate"
            log(
                f"WARNING: ladder: {kind} sidecar {os.path.basename(cand)} "
                f"retime uncertain; preserving raw source ({reason})"
            )
            if stats.get("retime_status") != "unavailable":
                _register_external_sidecar(
                    stem,
                    kind,
                    media_path,
                    cand,
                    hit["source_hash"],
                    ep_id,
                    stats,
                    effective_cues=hit["cues"],
                    timeline_kind="raw",
                    retime_status="rejected",
                    retime_reason=reason,
                )
            hit["align_stats"] = stats
            return hit
        if (
            not stats.get("method")
            or stats.get("method") == "order"
            or not stats.get("anchors")
            or stats.get("retime_status") == "rejected"
        ):
            _silent_remove(retimed)
            reason = stats.get("reason") or "no reliable text anchors"
            if stats.get("retime_status") != "unavailable":
                _register_external_sidecar(
                    stem,
                    kind,
                    media_path,
                    cand,
                    hit["source_hash"],
                    ep_id,
                    stats,
                    effective_cues=hit["cues"],
                    timeline_kind="raw",
                    retime_status="rejected",
                    retime_reason=reason,
                )
            hit["align_stats"] = stats
            return hit
        log(
            f"ladder: retimed external {kind} sidecar {os.path.basename(cand)} "
            f"method={stats['method']} anchors={stats['anchors']}/{stats['total']} "
            f"matched_frac={stats['matched_frac']:.2f}"
        )
        verdict_a = _gate(retimed, kind)
        if not verdict_a["ok"]:
            reason = verdict_a.get("reason") or "retimed source adequacy gate"
            _silent_remove(retimed)
            _register_external_sidecar(
                stem,
                kind,
                media_path,
                cand,
                hit["source_hash"],
                ep_id,
                stats,
                effective_cues=hit["cues"],
                timeline_kind="raw",
                retime_status="rejected",
                retime_reason=reason,
            )
            hit["align_stats"] = stats
            return hit
        # timeline gate: a bad retime must never reach translation
        tl_ok, tl_why = validate_srt_timeline(
            retimed,
            media_duration_s(media_path),
        )
        if not tl_ok:
            log(
                f"WARNING: ladder: {kind} sidecar {os.path.basename(cand)} "
                f"retimed output failed timeline gate; preserving raw ({tl_why})"
            )
            _silent_remove(retimed)
            _register_external_sidecar(
                stem,
                kind,
                media_path,
                cand,
                hit["source_hash"],
                ep_id,
                stats,
                effective_cues=hit["cues"],
                timeline_kind="raw",
                retime_status="rejected",
                retime_reason=tl_why,
            )
            hit["align_stats"] = stats
            return hit
        stats["retime_status"] = "accepted"
        _register_external_sidecar(
            stem,
            kind,
            media_path,
            cand,
            hit["source_hash"],
            ep_id,
            stats,
            effective_cues=verdict_a["cues"],
            timeline_kind="retimed",
            retime_status="accepted",
        )
        hit["cues"] = verdict_a["cues"]
        hit["effective_timeline"] = _timeline_snapshot(verdict_a["cues"])
        hit["timeline_kind"] = "retimed"
        hit["align_tmp"] = retimed
        hit["align_stats"] = stats
        return hit

    # (a) jpn — Bazarr/Jimaku manage HI-only files (.ja.hi.srt etc.), so
    # the HI variants are first-class rung (a) candidates
    for cand in sidecar_paths(stem, "ja"):
        if os.path.isfile(cand) and not srt_has_ai_marker(cand):
            hit = _external_hit(cand, "jpn")
            if hit:
                return hit
    if tmp_dir:
        tmp_path = os.path.join(tmp_dir, f"ladder_{ep_id or 'x'}_jpn.srt")
        hit = None
        if extract_embedded_subtitle(media_path, "jpn", tmp_path):
            verdict = _gate(tmp_path, "jpn")
            if verdict["ok"]:
                hit = _hit("jpn", tmp_path, verdict, tmp=True)
        if hit is None and os.path.isfile(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass
        if hit is not None:
            return hit
    cand = bazarr_jpn_candidate(cfg, ep_id, series_id, media_path, tmp_dir)
    if cand:
        hit = _external_hit(cand, "jpn")
        if hit:
            return hit
    if lc.get("jimaku_direct_enabled"):
        hit = jimaku_direct_candidate(
            cfg, media_path, series_title, season, episode, tmp_dir, ep_id=ep_id
        )
        if hit:
            return hit

    # audio-language guard: Japanese audio must never be eng->ja translated;
    # fall through to ASR (SenseVoice transcribes Japanese natively)
    try:
        ja_audio = any(
            (s.get("tags") or {}).get("language") in ("jpn", "ja", "jp")
            for s in probe_audio(media_path)
        )
    except Exception as exc:
        log(f"ladder: audio probe failed ({exc}); falling through to eng rungs")
        ja_audio = False
    if ja_audio:
        return {
            "kind": "asr",
            "source_path": None,
            "source_hash": None,
            "cues": None,
            "duration_s": duration,
            "tmp": False,
        }

    # (b) eng
    for cand in sidecar_paths(stem, "en"):
        if os.path.isfile(cand):
            hit = _external_hit(cand, "eng")
            if hit:
                return hit
    if tmp_dir:
        tmp_path = os.path.join(tmp_dir, f"ladder_{ep_id or 'x'}_eng.srt")
        hit = None
        if extract_embedded_subtitle(media_path, "eng", tmp_path):
            verdict = _gate(tmp_path, "eng")
            if verdict["ok"]:
                hit = _hit("eng", tmp_path, verdict, tmp=True)
        if hit is None and os.path.isfile(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass
        if hit is not None:
            return hit

    # (c) ASR — current behavior
    return {
        "kind": "asr",
        "source_path": None,
        "source_hash": None,
        "cues": None,
        "duration_s": duration,
        "tmp": False,
    }


def _asr_cache_dims():
    """ASR config dimensions that change segmentation; cache entries written
    under other dims are treated as a miss so stale cues are never served
    (e.g. sensevoice production vs faster-whisper refine sharing one key)."""
    dims = {"backend": ASR_BACKEND}
    if ASR_BACKEND == "sensevoice":
        for k in (
            "SV_MAX_SEG_MS",
            "SV_MAX_END_SILENCE_MS",
            "SV_SPEECH_PAD_MS",
            "SV_MIN_SPEECH_MS",
        ):
            dims[k] = os.environ.get(k, "")
    else:
        for k in (
            "WHISPER_MODEL",
            "WHISPER_BEAM",
            "VAD_THRESHOLD",
            "VAD_MIN_SILENCE_MS",
            "VAD_MAX_SPEECH_S",
            "VAD_MIN_SILENCE_AT_MAX",
            "VAD_SPEECH_PAD_MS",
            "SPLIT_MIN_SILENCE_MS",
            "MAX_CUE_MS",
            "HARD_GAP_MS",
        ):
            dims[k] = os.environ.get(k, "")
    return dims


def asr_cache_get(audio_id, asr_lang, media_path):
    key = f"{audio_id}_{asr_lang}"
    cues_path = os.path.join(ASR_CACHE_DIR, key + ".cues.json")
    meta_path = os.path.join(ASR_CACHE_DIR, key + ".json")
    try:
        with open(meta_path) as fh:
            meta = json.load(fh)
        if meta.get("fingerprint") == _media_fingerprint(media_path) and meta.get(
            "asr_dims"
        ) == _asr_cache_dims():
            with open(cues_path) as fh:
                cues = json.load(fh)
            if cues and isinstance(cues, list):
                return cues
    except Exception:
        pass
    return None


def asr_cache_put(audio_id, asr_lang, media_path, cues):
    os.makedirs(ASR_CACHE_DIR, exist_ok=True)
    key = f"{audio_id}_{asr_lang}"
    with open(os.path.join(ASR_CACHE_DIR, key + ".cues.json"), "w") as fh:
        json.dump(cues, fh, ensure_ascii=False)
    with open(os.path.join(ASR_CACHE_DIR, key + ".json"), "w") as fh:
        json.dump(
            {"fingerprint": _media_fingerprint(media_path), "asr_dims": _asr_cache_dims()},
            fh,
        )


def asr_cues(cfg, wav_path, lang, return_windows=False):
    """ASR dispatch. Default: faster-whisper + VadOptions (<=8s cues).
    ASR_BACKEND=sensevoice: SenseVoice + fsmn-vad 5s cap + min-1s post-pass
    (validated recipe 2026-08-10); SenseVoice language codes ja/zh/en/ko/yue.
    return_windows=True (sensevoice only) returns (cues, windows) with the
    per-VAD-window metadata for the emotion pass; whisper returns (cues, [])."""
    if ASR_BACKEND == "sensevoice":
        from pipeline import sensevoice as pipeline_sensevoice

        return pipeline_sensevoice.transcribe_cues(
            wav_path, language=lang, return_windows=return_windows
        )
    cues = pipeline_asr.transcribe_cues(wav_path, language=lang)
    if return_windows:
        return cues, []
    return cues


def maybe_attach_emotion(cues, wav_path, windows_meta):
    """Emotion pass (EMO_ENABLED + ASR_BACKEND=sensevoice): attach per-cue
    emotion labels from emotion2vec+ window classification (see
    pipeline/emotion.py). Never raises: any failure logs a warning and
    returns cues unchanged, so the pipeline runs identically with the pass
    off (EMO_ENABLED=0, the default)."""
    if not EMO_ENABLED or ASR_BACKEND != "sensevoice":
        return cues
    try:
        from pipeline.emotion import attach_emotion

        return attach_emotion(cues, wav_path, windows_meta)
    except Exception as e:
        log(f"emotion pass failed: {e}")
        return cues


def cps_merge(cues, max_cps=CPS_MERGE_MAX, max_chars=CPS_MERGE_MAX_CHARS,
              max_dur_ms=CPS_MERGE_MAX_DUR_MS, max_gap_ms=CPS_MERGE_MAX_GAP_MS):
    """Merge ASR-translated cues whose reading speed exceeds max_cps
    chars/sec (Netflix TTSG ~20cps). Verbose translations (e.g. id) turn
    short ja cues into 35-char walls on 1.5s of audio; merging with the
    FOLLOWING cue gives the text real reading time while staying within
    subtitle size limits.

    Greedy single forward pass over translated cue dicts
    {start_ms, end_ms, text}: a cue above max_cps chains through following
    cues while EVERY condition holds:
      - gap to the next cue <= max_gap_ms (text never spans real silence);
      - combined chars <= max_chars (never exceeded);
      - joined with " " when combined chars <= max_chars/2, else "\\n"
        (2-line cue);
      - combined cps (chars / (next.end - cur.start) secs) <= max_cps;
      - combined duration <= max_dur_ms;
      - hard cap: a cue never holds more than 2 lines; a 2-line cue stops
        the chain (no further merges).
    On merge the next cue is dropped and the chain continues. Cues already
    within limits are never disturbed. Applied ONLY to ASR-translated output
    (process_after_asr, one_shot_test) — never to embedded-subtitle ladder
    output, which carries proper original timings/text."""
    out = [dict(c) for c in cues]
    i = 0
    while i < len(out):
        cur = out[i]
        dur_s = (cur["end"] - cur["start"]) / 1000.0
        if dur_s <= 0 or len(cur["text"]) / dur_s <= max_cps:
            i += 1
            continue
        while i + 1 < len(out):
            nxt = out[i + 1]
            if nxt["start"] - cur["end"] > max_gap_ms:
                break
            # hard 2-line cap: once the accumulated text holds 2 lines (or
            # the candidate would add a second line), no further merge.
            cur_lines = cur["text"].count("\n") + 1
            nxt_lines = nxt["text"].count("\n") + 1
            if cur_lines + nxt_lines > 2:
                break
            joined = cur["text"] + " " + nxt["text"]
            if len(joined) > max_chars:
                break
            sep = " " if len(joined) <= max_chars / 2 else "\n"
            combined_text = cur["text"] + sep + nxt["text"]
            combined_dur_s = (nxt["end"] - cur["start"]) / 1000.0
            if (
                combined_dur_s <= 0
                or len(combined_text) / combined_dur_s > max_cps
                or combined_dur_s * 1000 > max_dur_ms
            ):
                break
            cur["end"] = nxt["end"]
            cur["text"] = combined_text
            del out[i + 1]
        i += 1
    return out


# ---------- SRT ----------


def parse_srt(text):
    cues = []
    for block in re.split(r"\n\s*\n", text.strip()):
        lines = [l.strip() for l in block.splitlines() if l.strip()]
        if not lines:
            continue
        ts_idx = next((i for i, l in enumerate(lines) if "-->" in l), None)
        if ts_idx is None:
            continue
        m = re.match(
            r"(\d{2}:\d{2}:\d{2},\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2},\d{3})",
            lines[ts_idx],
        )
        if not m:
            continue
        body = " ".join(lines[ts_idx + 1 :]).strip()
        if not body:
            continue
        cues.append({"start": m.group(1), "end": m.group(2), "text": body})
    return cues


_ASS_OVERRIDE_RE = re.compile(r"\{[^}]*\}")
_ASS_HTML_RE = re.compile(r"<[^>]+>")


def clean_ass_text(text):
    """Strip ASS/SSA styling from a subtitle cue's body: {\\an8} override
    blocks and <font ...> HTML tags (sidecars extracted by the tdarr webhook
    carry both). \\N / \\n become real line breaks; blank lines collapse."""
    text = text.replace("\\N", "\n").replace("\\n", "\n")
    text = _ASS_OVERRIDE_RE.sub("", text)
    text = _ASS_HTML_RE.sub("", text)
    return "\n".join(l.strip() for l in text.splitlines() if l.strip())


def srt_ts_ms(v):
    """SRT timestamp (string or number-of-ms) -> float ms, or None."""
    if isinstance(v, (int, float)):
        return float(v)
    m = re.match(r"(\d+):(\d+):(\d+)[,.](\d+)", str(v))
    if m:
        h, mi, s, ms = m.groups()
        return int(h) * 3600000 + int(mi) * 60000 + int(s) * 1000 + int(ms)
    return None


def media_duration_s(path):
    """Container duration in seconds via ffprobe, or None on failure."""
    p = subprocess.run(
        [
            "ffprobe",
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "json",
            path,
        ],
        capture_output=True,
        text=True,
        timeout=120,
    )
    if p.returncode != 0:
        return None
    try:
        return float(json.loads(p.stdout)["format"]["duration"])
    except (ValueError, KeyError, TypeError):
        return None


def file_sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def _fmt_ms(ms):
    ms = int(round(ms))
    h, rem = divmod(ms, 3600000)
    m, rem = divmod(rem, 60000)
    s, msr = divmod(rem, 1000)
    return f"{h:02d}:{m:02d}:{s:02d},{msr:03d}"


def _fmt_ts(v):
    if isinstance(v, (int, float)):
        return _fmt_ms(v)
    return v


def write_srt(cues, texts, out_path, header=None):
    """Write SRT. header (AI marker) becomes a REAL first cue at 00:00:00,000
    -> 00:00:01,500 (config AI_MARKER_CUE, default on) — bare text lines are
    dropped by players until a timestamped cue is seen. If the first dialogue
    cue starts before 2s, the marker cue ends just before it."""
    with open(out_path, "w", encoding="utf-8") as fh:
        idx = 1
        if header and AI_MARKER_CUE:
            first_start = None
            for cue in cues:
                if cue.get("text", "").strip():
                    first_start = cue.get("start")
                    break
            marker_end = AI_MARKER_CUE_MS
            if first_start is not None:
                first_ms = srt_ts_ms(first_start)
                if first_ms is not None and first_ms < 2000:
                    marker_end = max(0, int(first_ms) - 1)
            fh.write(
                f"{idx}\n00:00:00,000 --> {_fmt_ms(marker_end)}\n{header}\n\n"
            )
            idx = 2
        elif header:
            fh.write(header + "\n\n")
        for cue, text in zip(cues, texts):
            fh.write(
                f"{idx}\n{_fmt_ts(cue['start'])} --> {_fmt_ts(cue['end'])}\n{text}\n\n"
            )
            idx += 1


# ---------- translation (Zen Go, OpenAI-compatible) ----------


def extract_json_array(raw):
    if not raw:
        return None
    s = raw.strip()
    i, j = s.find("["), s.rfind("]")
    if i < 0 or j <= i:
        return None
    for cand in (s[i : j + 1], raw[i : j + 1]):
        try:
            arr = json.loads(cand)
            if isinstance(arr, list):
                return [str(x) for x in arr]
        except Exception:
            continue
    return None


def post_chat(cfg, messages, model, key, local=False):
    url = (cfg.get("TRANSLATE_BASE") or TRANSLATE_BASE).rstrip(
        "/"
    ) + "/chat/completions"
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    if local:
        payload = {
            "model": model,
            "messages": messages,
            "temperature": 0.1,
            "top_k": 40,
            "top_p": 0.9,
            "repeat_penalty": 1.10,
            "max_tokens": 8192,
        }
    else:
        payload = {
            "model": model,
            "messages": messages,
            "temperature": 0.3,
            "thinking": {"type": "enabled", "effort": "max"},
        }
    for attempt in range(3):
        try:
            r = requests.post(url, headers=headers, json=payload, timeout=TIMEOUT)
        except requests.RequestException as exc:
            log(f"    [translate] network error (attempt {attempt + 1}): {exc}")
            if attempt < 2:
                time.sleep(5 * (attempt + 1))
            continue
        if r.status_code == 200:
            try:
                return r.json()["choices"][0]["message"]["content"]
            except Exception:
                return None
        if r.status_code == 404:
            return None  # signal model fallback
        if (
            local
            and r.status_code == 400
            and "exceeds the available context size" in r.text
        ):
            # deterministic context overflow: retrying the same size always fails.
            # Signal the caller to split the chunk instead of deferring.
            log(
                f"    [translate] HTTP 400 context overflow (attempt {attempt + 1}): {r.text[:200]} - splitting chunk"
            )
            return CTX_OVERFLOW
        # 5xx/429: server overload or rate limit - do not hammer; defer to next pass
        log(
            f"    [translate] HTTP {r.status_code} (attempt {attempt + 1}): {r.text[:200]} - deferring to next pass"
        )
        return None
    return None


def get_prior_context(cfg, series_id, episode_id):
    try:
        r = requests.get(
            cfg["SONARR_URL"].rstrip("/") + "/episode",
            params={"seriesId": series_id},
            headers={"X-Api-Key": cfg["SONARR_API_KEY"]},
            timeout=60,
        )
        r.raise_for_status()
        current = get_episode(cfg, episode_id)
        season = current.get("seasonNumber")
        episode_num = current.get("episodeNumber")
        if not isinstance(season, int) or not isinstance(episode_num, int):
            return []
        prev_nums = {episode_num - 1, episode_num - 2}
        prev_eps = [
            e
            for e in r.json()
            if e.get("seasonNumber") == season and e.get("episodeNumber") in prev_nums
        ]
        lines = []
        seen = set()
        for prev in sorted(prev_eps, key=lambda e: -e["episodeNumber"]):
            if len(lines) >= 20:
                break
            try:
                sr = requests.get(
                    cfg["BAZARR_URL"].rstrip("/") + "/episodes",
                    params={"episodeid[]": prev["id"]},
                    headers={"X-API-KEY": cfg["BAZARR_API_KEY"]},
                    timeout=60,
                )
                if sr.status_code != 200:
                    continue
                data = sr.json()
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            items = data.get("data") or []
            if not items:
                continue
            subs = items[0].get("subtitles") or []
            subs.sort(key=lambda s: 0 if (s.get("code2") or "") == "id" else 1)
            chosen = None
            for s in subs:
                p = s.get("path")
                if not p:
                    continue
                local = map_path(p)
                if os.path.isfile(local):
                    chosen = local
                    break
            if not chosen:
                continue
            try:
                with open(chosen, "r", encoding="utf-8", errors="replace") as fh:
                    srt_text = fh.read()
                for cue in parse_srt(srt_text):
                    t = cue["text"]
                    if t and t not in seen:
                        seen.add(t)
                        lines.append(t)
                        if len(lines) >= 40:
                            break
            except Exception:
                continue
        return lines[:20]
    except Exception:
        return []


def is_local_translate(cfg):
    base = cfg.get("TRANSLATE_BASE") or TRANSLATE_BASE
    return "127.0.0.1" in base or "localhost" in base


def _parse_numbered_response(raw):
    if not raw:
        return None
    parsed = {}
    for line in raw.splitlines():
        m = re.match(r"^(\d+)[.．…]?\s*(.+)$", line.strip())
        if m:
            parsed[int(m.group(1))] = m.group(2).strip()
    return parsed


def _parse_local_response(raw, max_count=None):
    """Parse a JSON array into a contiguous 1-based response mapping.

    Partial arrays are valid for merge-aware tail completion; arrays longer than
    the requested input are rejected before they can overrun cue assembly.
    """
    parsed = extract_json_array(raw)
    if not parsed or (max_count is not None and max_count < 1):
        return None
    if max_count is not None:
        parsed = parsed[:max_count]
    return {i + 1: text.strip() for i, text in enumerate(parsed)}


_NON_LATIN_LETTER_RE = re.compile(
    "[\u0370-\u03FF\u0400-\u04FF\u0500-\u052F\u0590-\u05FF\u0600-\u06FF"
    "\u0900-\u097F\u0E00-\u0E7F\u3040-\u309F\u30A0-\u30FF\u3400-\u4DBF"
    "\u4E00-\u9FFF\uAC00-\uD7AF]"
)
_CJK_KANA_RE = re.compile(r"[\u3040-\u30FF\u3400-\u4DBF\u4E00-\u9FFF]")


def _wrong_script(line, target_lang):
    """True when a translated line contains characters of a script the
    target language must not contain. Latin targets (Indonesian, English)
    reject any non-Latin letter (Cyrillic/Greek/Arabic/CJK/Kana/Hangul/
    Thai/...). Japanese rejects only lines that are entirely alien — no CJK
    and no Latin letters (e.g. Cyrillic-only); mixed CJK+Latin is normal
    Japanese output."""
    if not line:
        return False
    if target_lang == "Japanese":
        has_cjk = bool(_CJK_KANA_RE.search(line))
        has_latin = bool(re.search(r"[A-Za-z]", line))
        return not has_cjk and not has_latin and bool(_NON_LATIN_LETTER_RE.search(line))
    return bool(_NON_LATIN_LETTER_RE.search(line))


def sanitize_lines(lines, max_repeat=10):
    """Collapse runs of >max_repeat identical chars to max_repeat + ellipsis
    (anime scream lines otherwise trigger repetition collapse in small models)."""
    out = []
    for s in lines:
        if not s:
            out.append(s)
            continue
        parts = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            run = j - i
            if run > max_repeat:
                parts.append(s[i] * max_repeat + "…")
            else:
                parts.append(s[i:j])
            i = j
        out.append("".join(parts))
    return out


def guard_foreign_lines(lines, sdh_placeholders=None):
    """Replace foreign-script lines (Chinese w/o kana, mostly-latin English) with an
    SDH placeholder (default （歌詞）) so the model does not echo the whole chunk.
    Returns (guarded_lines, [(original_index, original_text), ...]) for swap-back."""
    sdh = list(sdh_placeholders) if sdh_placeholders else list(DEFAULT_SDH_PLACEHOLDERS)
    out, foreign = [], []
    for i, l in enumerate(lines):
        latin_chars = LATIN_RE.findall(l)
        latin_ratio = len(latin_chars) / max(len(l), 1)
        if (HANZI_RE.search(l) and not KANA_RE.search(l)) or (
            latin_ratio > 0.5 and not KANA_RE.search(l)
        ):
            foreign.append((i, l))
            out.append(sdh[i % len(sdh)])
        else:
            out.append(l)
    return out, foreign


def _gemma_prompt(chunk, lang_name, refs=None, context_lines=None, emotions=None, source_lang="Japanese"):
    """Build the generic Gemma system prompt and JSON user payload.

    refs is the stable KNOWLEDGE block for the episode (already rendered by
    pipeline.glossary.knowledge_block / knowledge_block_for_cues). It is
    injected verbatim as background knowledge and reused identically across
    all chunks/batches of the episode for llama-server KV/prefix-cache reuse.
    """
    parts = [
        "You are a professional subtitle translator.",
        f"Target language: {lang_name}.",
        "Translate every input line naturally and preserve the input order.",
        "Return ONLY a JSON array of translated strings; no prose or markdown.",
        "Keep names, honorifics, meaning, and subtitle brevity; each line <=42 characters.",
    ]
    if refs:
        parts.append(refs)
    if context_lines:
        capped = context_lines[:TRANSLATE_CONTEXT_LINES]
        parts.append("Prior translated context:\n" + "\n".join(capped))
    if emotions and any(emotions):
        hints = ", ".join(f"{i + 1}: {emotion}" for i, emotion in enumerate(emotions) if emotion)
        if hints:
            parts.append("Optional emotion hints by source-line number: " + hints)
    system = "\n\n".join(parts)
    user = json.dumps(
        {"source_language": source_lang, "target_language": lang_name, "lines": chunk},
        ensure_ascii=False,
    )
    return system, user


def _local_chunk(cfg, chunk, lang_name, key, refs=None, context_lines=None,
                 emotions=None, source_lang="Japanese"):
    """One local-model chat call using the Gemma JSON contract."""
    n = len(chunk)
    system, user = _gemma_prompt(chunk, lang_name, refs=refs,
                                  context_lines=context_lines, emotions=emotions, source_lang=source_lang)
    messages = [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]
    raw = post_chat(cfg, messages, cfg.get("TRANSLATE_MODEL") or TRANSLATE_MODEL, key, local=True)
    if raw is None:
        return None
    return _parse_local_response(raw, n)


def _attempt_chunk(cfg, chunk, lang_name, key, echo_probe=11, refs=None,
                   context_lines=None, emotions=None, source_lang="Japanese"):
    """Up to 3 attempts per chunk; corrective retry on echo OR wrong-script
    output (target-script guard). Echo probe is skipped for Japanese targets
    (correct output always contains kana/kanji). Returns clean parsed dict or
    None (all attempts empty/echo/wrong-script/network-fail)."""
    n = len(chunk)
    for _ in range(3):
        parsed = _local_chunk(cfg, chunk, lang_name, key, refs=refs,
                              context_lines=context_lines, emotions=emotions, source_lang=source_lang)
        if not parsed:
            continue
        if any(_wrong_script(t, lang_name) for t in parsed.values()):
            continue
        if lang_name == "Japanese":
            return parsed
        echo = False
        for k in range(1, min(echo_probe, n) + 1):
            t = parsed.get(k)
            if t and re.search(r"[\u3040-\u30ff\u3400-\u9fff]", t):
                echo = True
                break
        if not echo:
            return parsed
    return None


def _complete_tail(cfg, tail_lines, m, lang_name, key, refs=None,
                   context_lines=None, emotions=None, source_lang="Japanese"):
    """Complete a chunk's missing tail: translate source lines m..n-1
    (numbered m+1..n in the prompt), remap keys to absolute m+i. Returns
    merged dict for the full chunk (keys 1..n) or None after 3 attempts."""
    n = m + len(tail_lines)
    for _ in range(3):
        system, user = _gemma_prompt(
            tail_lines, lang_name, refs=refs, context_lines=context_lines,
            emotions=(emotions[m:] if emotions else None), source_lang=source_lang,
        )
        messages = [
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ]
        raw = post_chat(cfg, messages, cfg.get("TRANSLATE_MODEL") or TRANSLATE_MODEL, key, local=True)
        if raw is None:
            continue
        parsed = _parse_local_response(raw, len(tail_lines))
        if not parsed:
            continue
        if any(_wrong_script(t, lang_name) for t in parsed.values()):
            continue
        echo = False
        for rel in range(1, min(5, n - m) + 1):
            t = parsed.get(rel)
            if t and re.search(r"[\u3040-\u30ff\u3400-\u9fff]", t):
                echo = True
                break
        if echo:
            continue
        return {m + i: text for i, text in parsed.items()}
    return None


def _translate_merge_aware(cfg, lines, lang_name, key, refs=None,
                           context_lines=None, emotions=None, source_lang="Japanese"):
    """Translate, tolerating Gemma merging consecutive short lines. Returns
    list of (cue_start_idx, cue_end_idx_exclusive, text)."""
    groups = []
    cs = TRANSLATE_CHUNK
    for start in range(0, len(lines), cs):
        chunk = lines[start : start + cs]
        n = len(chunk)
        parsed = _attempt_chunk(cfg, chunk, lang_name, key, refs=refs,
                                context_lines=context_lines,
                                emotions=(emotions[start:start + cs] if emotions else None), source_lang=source_lang)
        if parsed is None:
            for j in range(n):
                gi = start + j
                p = _attempt_chunk(cfg, [chunk[j]], lang_name, key, echo_probe=1,
                                   refs=refs, context_lines=context_lines,
                                   emotions=([emotions[gi]] if emotions and emotions[gi] else None), source_lang=source_lang)
                text = re.sub(r"^>\s*", "", (p or {}).get(1, ""))
                groups.append((gi, gi + 1, text))
            continue
        entries = sorted(parsed.items())
        m = len(entries)
        if m == n:
            for k, t in entries:
                if k < 1 or k > n:
                    continue
                groups.append((start + k - 1, start + k, re.sub(r"^>\s*", "", t)))
            continue
        entries_dict = dict(entries)
        tail_lines = chunk[m:n]
        merged = None
        if tail_lines:
            completion = _complete_tail(cfg, tail_lines, m, lang_name, key,
                                        refs=refs, context_lines=context_lines,
                                        emotions=emotions, source_lang=source_lang)
            if completion:
                merged = {**entries_dict, **completion}
        if merged:
            for k, t in sorted(merged.items()):
                if k > n:
                    continue
                groups.append((start + k - 1, start + k, re.sub(r"^>\s*", "", t)))
        else:
            for k, t in entries:
                if k > n:
                    continue
                gi = start + k - 1
                groups.append((gi, gi + 1, re.sub(r"^>\s*", "", t)))
            for k in range(m + 1, n + 1):
                gi = start + k - 1
                p = _attempt_chunk(cfg, [chunk[k - 1]], lang_name, key, echo_probe=1,
                                   refs=refs, context_lines=context_lines,
                                   emotions=([emotions[gi]] if emotions and emotions[gi] else None), source_lang=source_lang)
                text = re.sub(r"^>\s*", "", (p or {}).get(1, ""))
                groups.append((gi, gi + 1, text))
    return groups


def chat_translate_batch(cfg, lines, target_lang, key, context_lines=None, series_title=None, skip_guard=False, emotions=None, source_lang="Japanese"):
    lines = sanitize_lines(lines)
    target_lang = normalize_language(target_lang)
    if is_local_translate(cfg):
        # local Gemma path: generic JSON contract with KNOWLEDGE injection and
        # optional tone hints (emotions, one per line). Foreign lines become
        # SDH placeholders (kept in output, not swapped back) — skipped when
        # the SOURCE is already eng/latin (skip_guard) so it can be translated.
        # KNOWLEDGE block: built ONCE per episode pass (stable prefix for
        # llama-server KV/prefix-cache reuse across all chunks) via cast
        # resolution — scan full cue text case-insensitively for any entry
        # surface form (ja, en, aliases); inject only matched entries, fallback
        # to full list when <3 match (ASR-garbling fallback). Cached in the
        # local variable `knowledge` for this episode pass.
        sdh = cfg.get("SDH_PLACEHOLDERS") or DEFAULT_SDH_PLACEHOLDERS
        # scan original sanitized lines before foreign-guard for cast resolution
        knowledge = ""
        if series_title:
            knowledge = pipeline_glossary.knowledge_block_for_cues(series_title, lines)
            if knowledge:
                log(f"    [translate] knowledge block for series: {len(knowledge)} chars")
        if not skip_guard:
            lines, _foreign = guard_foreign_lines(lines, sdh)
        target_lang = normalize_language(target_lang)
        lang_name = LANG_NAMES.get(target_lang, target_lang)
        return _translate_merge_aware(cfg, lines, lang_name, key, refs=knowledge,
                                      context_lines=context_lines, emotions=emotions, source_lang=source_lang)
    models = [cfg.get("TRANSLATE_MODEL") or TRANSLATE_MODEL] + [
        m for m in MODEL_FALLBACKS if m != cfg.get("TRANSLATE_MODEL")
    ]
    system = TRANSLATE_PROMPT.format(target_language=target_lang, source_language=source_lang)
    if context_lines:
        system += (
            "\n\nUse these previously translated lines from earlier episodes for "
            "consistent names, terms, and style:\n"
            + "\n".join(f"REF: {l}" for l in context_lines)
        )
    user = json.dumps(
        {"source_language": source_lang, "target_language": target_lang, "lines": lines}, ensure_ascii=False
    )
    messages = [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]
    for _ in range(2):  # one corrective retry on parse failure
        raw = None
        for model in models:
            content = post_chat(cfg, messages, model, key)
            if content is None:
                continue  # 404 -> next model, or network dead -> try next model too
            raw = content
            break
        if raw is None:
            log("    [translate] all models/attempts failed (network or 404)")
            return None
        parsed = extract_json_array(raw)
        if parsed is not None and len(parsed) == len(lines):
            return parsed
        messages.append({"role": "assistant", "content": raw})
        messages.append(
            {
                "role": "user",
                "content": (
                    f"Your previous output was not a JSON array with exactly {len(lines)} "
                    'strings. Output ONLY the JSON array, e.g. ["...", "..."], same count '
                    "and order as the input."
                ),
            }
        )
    log("    [translate] unparseable / count mismatch after retry")
    return None


def translate_texts(
    cfg,
    cues,
    target_lang,
    key,
    series_id=None,
    episode_id=None,
    prior_cache=None,
    series_title=None,
    skip_guard=False,
    source_lang="Japanese",
):
    lines = [c["text"] for c in cues]
    if is_local_translate(cfg):
        context_lines = []
    elif series_id and episode_id and prior_cache is not None:
        if series_id not in prior_cache:
            prior_cache[series_id] = get_prior_context(cfg, series_id, episode_id)
        context_lines = prior_cache[series_id]
    else:
        context_lines = (
            get_prior_context(cfg, series_id, episode_id)
            if series_id and episode_id
            else []
        )
    out = chat_translate_batch(
        cfg, lines, target_lang, key, context_lines, series_title=series_title,
        skip_guard=skip_guard,
        emotions=[c.get("emotion") for c in cues], source_lang=source_lang,
    )
    if out is None:
        return None
    if is_local_translate(cfg):
        # merge-aware groups (start_idx, end_idx_excl, text); caller assembles cues
        return out
    if len(out) != len(lines):
        return None
    return [(i, i + 1, t) for i, t in enumerate(out)]


# ---------- upload ----------


_JF_SCAN_INTERVAL = 300  # min seconds between full /Library/Refresh scans
_jf_last_scan = 0.0


def _jf_series_dir(path):
    """Series name guess from a media path: the dir two levels above the file
    (…/Series Name/Season 01/X.mkv -> "Series Name")."""
    parts = (path or "").split("/")
    return parts[-3] if len(parts) >= 3 else None


def _jf_season_dir(path):
    """Season number from the season dir name (…/Season 01/…) or None."""
    parts = (path or "").split("/")
    if len(parts) < 2:
        return None
    m = re.search(r"Season\s*(\d+)", parts[-2], re.IGNORECASE)
    return int(m.group(1)) if m else None


def _jf_find_episode(base, headers, media_path, jelly_path, filename):
    """Path-based episode lookup: resolve the series via SearchTerm on the
    media path's series dir, then fetch /Shows/{id}/Episodes and match the
    item whose Path endswith the filename (or equals jelly_path)."""
    series_name = _jf_series_dir(media_path)
    if not series_name:
        return None
    try:
        r = requests.get(
            base + "/Items",
            params={
                "Recursive": "true",
                "IncludeItemTypes": "Series",
                "SearchTerm": series_name,
                "Fields": "Path",
            },
            headers=headers,
            timeout=5,
        )
        r.raise_for_status()
        items = r.json().get("Items", [])
        series = next(
            (s for s in items if (s.get("Path") or "").endswith("/" + series_name)),
            None,
        )
        if series is None and items:
            series = items[0]
        if series is None:
            return None
        params = {"Fields": "Path"}
        season = _jf_season_dir(media_path)
        if season is not None:
            params["Season"] = season
        r2 = requests.get(
            base + f"/Shows/{series['Id']}/Episodes",
            params=params,
            headers=headers,
            timeout=5,
        )
        r2.raise_for_status()
        for ep in r2.json().get("Items", []):
            p = ep.get("Path") or ""
            if p == jelly_path or p.endswith("/" + filename):
                return ep
    except Exception as exc:
        log(f"jellyfin: series lookup failed: {exc}")
    return None


def _jf_find_movie(base, headers, filename, jelly_path):
    """Path-based movie lookup: SearchTerm on the filename stem, match Path
    endswith filename (or equals jelly_path)."""
    stem = os.path.splitext(filename)[0]
    if not stem:
        return None
    try:
        r = requests.get(
            base + "/Items",
            params={
                "Recursive": "true",
                "IncludeItemTypes": "Movie",
                "Fields": "Path",
                "SearchTerm": stem,
            },
            headers=headers,
            timeout=5,
        )
        r.raise_for_status()
        for it in r.json().get("Items", []):
            p = it.get("Path") or ""
            if p == jelly_path or p.endswith("/" + filename):
                return it
    except Exception as exc:
        log(f"jellyfin: movie lookup failed: {exc}")
    return None


def _jf_find_by_title(base, headers, filename, jelly_path, title, item_type):
    """Legacy SearchTerm-by-title loop (fallback). Jellyfin metadata names can
    differ from the Sonarr title, so this is only used when the path-based
    lookup found nothing."""
    terms = [title or filename]
    if title:
        prefix = re.split(r"[:;!?()]", title, maxsplit=1)[0].strip()
        if prefix and prefix != title:
            terms.append(prefix)
    stem_name = os.path.splitext(filename)[0]
    if stem_name and stem_name != terms[0]:
        terms.append(stem_name)
    for term in terms:
        try:
            r = requests.get(
                base + "/Items",
                params={
                    "Recursive": "true",
                    "IncludeItemTypes": item_type,
                    "SearchTerm": term,
                    "Fields": "Path,MediaStreams",
                },
                headers=headers,
                timeout=5,
            )
            r.raise_for_status()
            for it in r.json().get("Items", []):
                p = it.get("Path") or ""
                if p == jelly_path or p.endswith("/" + filename):
                    return it
        except Exception:
            continue
    return None


def _jf_maybe_scan(base, headers):
    """Throttled full-library scan: a manual /Library/Refresh is the ONLY
    reliable way to index new external sidecars when the realtime monitor
    misses them (NFS). At most one scan per _JF_SCAN_INTERVAL."""
    global _jf_last_scan
    now = time.time()
    if now - _jf_last_scan < _JF_SCAN_INTERVAL:
        log("jellyfin: library scan skipped (throttled)")
        return
    try:
        rr = requests.post(base + "/Library/Refresh", headers=headers, timeout=10)
        _jf_last_scan = time.time()
        log(f"jellyfin: library scan triggered HTTP {rr.status_code}")
    except Exception as exc:
        log(f"jellyfin: library scan failed: {exc}")


def jellyfin_refresh(cfg, media_path, title=None, item_type="Episode"):
    """Fire-and-forget Jellyfin library refresh for a subtitle event.

    Path-based item lookup (robust against Sonarr-vs-Jellyfin title drift):
    Episodes resolve the series from the media path's series dir and fetch
    /Shows/{id}/Episodes, matching the item whose Path endswith the filename;
    Movies search Movie items by filename stem. Falls back to the legacy
    SearchTerm-by-title loop. Path matching gates every attempt (mapped NAS
    path). On a successful item refresh, a throttled full POST /Library/Refresh
    (>= 300s apart) guarantees new external sidecars get indexed even when the
    realtime monitor misses them (NFS). Runs in a daemon thread, ~5s item
    timeouts, 10s scan timeout; failures are logged but never fail the
    episode. No-op without JELLYFIN_API_KEY. item_type: "Episode" (series) or
    "Movie" (radarr track)."""
    key = cfg.get("JELLYFIN_API_KEY", "")
    if not key or not media_path:
        return

    def _run():
        try:
            base = (cfg.get("JELLYFIN_URL") or JELLYFIN_URL).rstrip("/")
            root = cfg.get("JELLYFIN_MEDIA_ROOT") or JELLYFIN_MEDIA_ROOT
            jelly_path = (
                root + media_path[len("/mnt/nas/share/media"):]
                if media_path.startswith("/mnt/nas/share/media")
                else media_path
            )
            filename = os.path.basename(media_path)
            headers = {"X-Emby-Token": key}
            if item_type == "Episode":
                item = _jf_find_episode(base, headers, media_path, jelly_path, filename)
            else:
                item = _jf_find_movie(base, headers, filename, jelly_path)
            if item is None:
                item = _jf_find_by_title(base, headers, filename, jelly_path, title, item_type)
            if item is None:
                log(f"jellyfin: {item_type.lower()} item not found for {filename}")
                return
            body = {
                "MetadataRefreshMode": "FullRefresh",
                "ImageRefreshMode": "None",
                "ReplaceAllMetadata": False,
                "ReplaceAllImages": False,
            }
            rr = requests.post(
                base + f"/Items/{item['Id']}/Refresh",
                json=body,
                headers=headers,
                timeout=5,
            )
            log(f"jellyfin: refresh {filename} HTTP {rr.status_code}")
            _jf_maybe_scan(base, headers)
        except Exception as exc:
            log(f"jellyfin: refresh failed for {media_path}: {exc}")

    threading.Thread(target=_run, daemon=True).start()


_BAZARR_WANTED_JOBS = {
    "series": "wanted_search_missing_subtitles_series",
    "movie": "wanted_search_missing_subtitles_movies",
}


def _bazarr_wanted_refill(cfg, kind="series"):
    """Best-effort: nudge both Bazarr instances to run their "Search for
    Missing Subtitles" task right now (route verified against the live
    swagger: POST /system/tasks?taskid=<job_id>, 204 on success), so episodes
    whose subtitle files were just deleted re-enter wanted immediately
    instead of waiting for the next scheduled scan — Bazarr's DB keeps rows
    pointing at deleted files until a scan, which made retry/delete feel like
    dead buttons. Never raises: failures are logged as WARNING (Bazarr then
    self-heals at its next scheduled scan)."""
    job = _BAZARR_WANTED_JOBS.get(kind) or _BAZARR_WANTED_JOBS["series"]
    targets = [(cfg["BAZARR_URL"], cfg["BAZARR_API_KEY"])]
    if cfg.get("BAZARR_URL_2"):
        targets.append((cfg["BAZARR_URL_2"], cfg.get("BAZARR_API_KEY_2") or ""))
    for base, key in targets:
        try:
            r = requests.post(
                base.rstrip("/") + "/system/tasks",
                params={"taskid": job},
                headers={"X-API-KEY": key},
                timeout=30,
            )
            if r.status_code == 204:
                log(f"bazarr: triggered '{job}' on {base.rstrip('/')}")
            else:
                log(
                    f"WARNING: bazarr: '{job}' trigger on {base.rstrip('/')} "
                    f"HTTP {r.status_code}; self-heals at the next scheduled scan"
                )
        except Exception as exc:
            log(
                f"WARNING: bazarr: '{job}' trigger on {base.rstrip('/')} failed ({exc}); "
                "self-heals at the next scheduled scan"
            )


def _delete_episode_subtitles(cfg, ep_id, langs=None):
    """Remove every {video stem}.{lang}*.srt variant (NAS path) plus TMP_DIR
    copies the pipeline wrote for the episode. The glob covers Bazarr's
    asynchronous HI twins and forced variants ({stem}.ja.srt, {stem}.ja.hi.srt,
    {stem}.id.forced.srt, ...): deleting only the exact {stem}.{lang}.srt left
    those twins behind with stale Bazarr DB rows. langs=None deletes all
    TARGET_LANGS; otherwise only the listed languages. Afterwards both Bazarr
    instances are asked to run their wanted-search task so missing subtitles
    refill immediately (_bazarr_wanted_refill). Never raises."""
    deleted = []
    langs = configured_languages(langs or cfg.get("TARGET_LANGS", []))
    try:
        info = get_episode(cfg, ep_id)
        ef = info.get("episodeFile") or {}
        p = map_path(ef.get("path", "")) if ef.get("path") else ""
        if p and os.path.isfile(p):
            stem = os.path.splitext(p)[0]
            for lang in langs:
                for cand in replaceable_target_sidecar_paths(stem, lang):
                    try:
                        os.remove(cand)
                        deleted.append(cand)
                    except OSError:
                        pass
            for lang in langs:
                registry_delete(stem=stem, lang=lang)
                registry_delete(ep_id=ep_id, lang=lang)
    except Exception as exc:
        log(f"action: delete: locating episode {ep_id} failed: {exc}")
    for lang in langs:
        cand = os.path.join(cfg.get("TMP_DIR", "/tmp"), f"{ep_id}_{lang}.srt")
        if os.path.isfile(cand):
            try:
                os.remove(cand)
                deleted.append(cand)
            except OSError:
                pass
    _bazarr_wanted_refill(cfg, "series")
    return deleted


def _delete_movie_subtitles(cfg, movie_id, langs=None):
    """Remove every {video stem}.{lang}*.srt variant (NAS path) plus TMP_DIR
    copies the pipeline wrote for the movie (glob covers .hi./.forced twins;
    see _delete_episode_subtitles). The path is resolved from Bazarr/Radarr
    (movies are not in Sonarr). langs=None deletes all TARGET_LANGS;
    otherwise only the listed languages. Afterwards both Bazarr instances are
    asked to run their movies wanted-search task (_bazarr_wanted_refill).
    Never raises."""
    deleted = []
    langs = configured_languages(langs or cfg.get("TARGET_LANGS", []))
    try:
        movies = get_movies(cfg)
        m = next(
            (x for x in (movies.get("data") or []) if x.get("radarrId") == movie_id),
            None,
        )
        p = map_path(m.get("path") or "") if m and m.get("path") else ""
        if p and os.path.isfile(p):
            stem = os.path.splitext(p)[0]
            for lang in langs:
                for cand in replaceable_target_sidecar_paths(stem, lang):
                    try:
                        os.remove(cand)
                        deleted.append(cand)
                    except OSError:
                        pass
            for lang in langs:
                registry_delete(stem=stem, lang=lang)
                registry_delete(ep_id=movie_id, lang=lang)
    except Exception as exc:
        log(f"action: delete: locating movie {movie_id} failed: {exc}")
    for lang in langs:
        cand = os.path.join(cfg.get("TMP_DIR", "/tmp"), f"{movie_id}_{lang}.srt")
        if os.path.isfile(cand):
            try:
                os.remove(cand)
                deleted.append(cand)
            except OSError:
                pass
    _bazarr_wanted_refill(cfg, "movie")
    return deleted


def _clear_movie_state(movie_id, lang):
    """Remove state.jsonl rows for (kind "movie", sonarrEpisodeId ==
    movie_id, language == lang) via atomic rewrite (tmp + os.replace).
    Never raises."""
    try:
        kept = []
        changed = False
        for e in load_records_jsonl(STATE_FILE):
            if (
                (e.get("kind") or "") == "movie"
                and e.get("sonarrEpisodeId") == movie_id
                and normalize_language(e.get("language")) == normalize_language(lang)
            ):
                changed = True
                continue
            kept.append(e)
        if changed:
            rewrite_jsonl(STATE_FILE, kept)
    except Exception as exc:
        log(f"recovery: state clear failed for movie {movie_id} [{lang}]: {exc}")


def _clear_series_state(episode_id, lang):
    """Remove state rows for one series episode/language atomically."""
    try:
        kept = []
        changed = False
        normalized = normalize_language(lang)
        for entry in load_records_jsonl(STATE_FILE):
            if (
                (entry.get("kind") or "series") == "series"
                and entry.get("sonarrEpisodeId") == episode_id
                and normalize_language(entry.get("language")) == normalized
            ):
                changed = True
                continue
            kept.append(entry)
        if changed:
            rewrite_jsonl(STATE_FILE, kept)
    except Exception as exc:
        log(f"recovery: state clear failed for episode {episode_id} [{lang}]: {exc}")


def _media_path_for_stem(stem):
    """Return a real supported video path for a registry stem, if present."""
    if not isinstance(stem, str) or not stem:
        return None
    for extension in (".mkv", ".mp4", ".avi", ".ts"):
        candidate = stem + extension
        if os.path.isfile(candidate):
            return candidate
    return None


def _registry_delete_recovery(stem, episode_id, lang):
    """Delete only current-stem and stemless legacy recovery rows."""
    normalized = normalize_language(lang)
    with _registry_lock(REGISTRY_FILE, exclusive=True):
        try:
            records = load_records_jsonl(REGISTRY_FILE)
            kept = []
            for record in records:
                record_stem = record.get("stem")
                same_language = normalize_language(record.get("lang")) == normalized
                same_current_stem = record_stem == stem
                same_legacy_episode = (
                    not record_stem and record.get("episode_id") == episode_id
                )
                if same_language and (same_current_stem or same_legacy_episode):
                    continue
                kept.append(record)
            if len(kept) < len(records):
                rewrite_jsonl(REGISTRY_FILE, kept)
        except Exception:
            pass


def recover_fileless_episodes(cfg=None, excluded=None):
    """Recover series done rows whose exact canonical HI target is absent."""
    if cfg is None:
        cfg = load_config()
    target_langs = set(configured_languages(cfg.get("TARGET_LANGS") or []))
    excluded = set(excluded or ())
    try:
        budget = int(cfg.get("FILELESS_EPISODE_RECOVERY_BUDGET", FILELESS_EPISODE_RECOVERY_BUDGET))
    except (TypeError, ValueError):
        budget = 0
    budget = max(0, budget)
    latest = {}
    try:
        entries = load_records_jsonl(STATE_FILE)
        registry_rows = load_records_jsonl(REGISTRY_FILE)
    except Exception as exc:
        log(f"recovery: episode state/registry read failed: {exc}")
        return []
    registry_by_episode = {}
    for record in registry_rows:
        episode_id = record.get("episode_id")
        lang = normalize_language(record.get("lang"))
        stem = record.get("stem")
        if isinstance(episode_id, int) and lang in target_langs and isinstance(stem, str) and stem:
            registry_by_episode[(episode_id, lang)] = record
    for entry in entries:
        episode_id = entry.get("sonarrEpisodeId")
        lang = normalize_language(entry.get("language"))
        if isinstance(episode_id, int) and lang in target_langs:
            latest[((entry.get("kind") or "series"), episode_id, lang)] = entry

    recovered = []
    deferred = 0
    for (kind, episode_id, lang), entry in latest.items():
        if kind != "series" or entry.get("status") != "done" or episode_id in excluded:
            continue
        registry = registry_by_episode.get((episode_id, lang))
        stem = registry.get("stem") if registry else None
        media_path = _media_path_for_stem(stem)
        info = {}
        if media_path is None:
            if budget <= 0:
                deferred += 1
                continue
            budget -= 1
            try:
                info = get_episode(cfg, episode_id)
                media = (info.get("episodeFile") or {}).get("path")
                media_path = map_path(media) if media else None
            except Exception:
                continue
            if not media_path or not os.path.isfile(media_path):
                continue
            stem = os.path.splitext(media_path)[0]
        canonical = canonical_target_sidecar_path(stem, lang)
        if os.path.isfile(canonical):
            continue
        recovered.append({
            "sonarrEpisodeId": episode_id,
            "seriesTitle": entry.get("seriesTitle") or info.get("seriesTitle") or "?",
            "missing_subtitles": [{"code2": lang}],
            "recovered": True,
        })
        log(
            f"recovery: queued episode {episode_id} "
            f"[{lang}] (canonical HI target missing)"
        )
    if deferred:
        log(f"recovery: deferred {deferred} episode lookup(s) at budget limit")
    return recovered


def recover_fileless_movies(cfg=None):
    """Recovery sweep for movies marked done without a target-lang sidecar
    on disk (Bazarr's async upload crashes on NULL profileId, so the file
    never lands but the pipeline trusted the 204). For each movie missing ANY
    target-lang {stem}.{lang}.srt: clear its registry rows and matching
    state rows so the sweep re-selects it. Movies whose target sidecars all
    exist are skipped; series rows and exclusions are untouched.

    Returns {"cleared": {movie_id: [langs]}, "skipped": n, "fileless": n}."""
    if cfg is None:
        cfg = load_config()
    target_langs = configured_languages(cfg.get("TARGET_LANGS") or [])
    try:
        movies = get_movies(cfg)
    except Exception as exc:
        log(f"recovery: movies fetch failed: {exc}")
        return {"cleared": {}, "skipped": 0, "fileless": 0}
    cleared = {}
    skipped = 0
    fileless = 0
    for m in movies.get("data") or []:
        rid = m.get("radarrId")
        if not isinstance(rid, int):
            continue
        p = m.get("path") or ""
        if not p:
            continue
        media_path = map_path(p)
        stem = os.path.splitext(media_path)[0]
        missing = [
            lang for lang in target_langs if not target_sidecar_exists(media_path, lang)
        ]
        if not missing:
            skipped += 1
            continue
        fileless += 1
        title = m.get("title") or "?"
        for lang in missing:
            registry_delete(ep_id=rid, lang=lang)
            registry_delete(stem=stem, lang=lang)
            _clear_movie_state(rid, lang)
            log(
                f"recovery: cleared registry+state for movie {rid} {title} "
                f"[{lang}] (file missing)"
            )
        cleared[rid] = missing
    log(f"recovery: {fileless} fileless movie(s) cleared, {skipped} skipped (have files)")
    return {"cleared": cleared, "skipped": skipped, "fileless": fileless}


def consume_actions(cfg):
    """Process pending actions.jsonl records once per pass; consumed records
    removed in place (tail-preserving: records appended mid-pass survive).

    schema (dashboard control_api_v2): {"ts", "type": "retry"|"skip"|"delete",
    "episode_id": int, "language": null|<code>, "source", "note"} —
    "action" is accepted as an alias for "type", and "language" limits retry
    to specific languages (null = the whole episode).

    - skip:   episode excluded from this pass's candidates
    - retry:  state entries cleared AND the episode's subtitle files removed
              (same _delete_episode_subtitles as delete): Bazarr wanted only
              lists episodes with MISSING subtitles, so clearing state alone
              would never reprocess an episode whose .srt is on disk
              (dashboard Retry would be dead); with the file gone the episode
              re-enters Bazarr wanted and is regenerated. "language" limits
              the state clearing AND the subtitle-file deletion to matching
              languages (null = whole episode).
    - delete: NAS + TMP SRT files removed, done state cleared -> regenerates,
              then Jellyfin refresh so the removed subtitle is dropped.
              "language" scopes the file deletion and state clearing to
              matching languages (null = whole episode), like retry.
    Returns the set of episode ids to exclude this pass (skips)."""
    records = consume_records_jsonl(ACTIONS_FILE)
    if not records:
        return set()
    skip_ids, retry_ids, delete_ids = set(), set(), set()
    retry_langs = {}
    delete_langs = {}
    retry_kinds = {}
    delete_kinds = {}
    for rec in records:
        eid = rec.get("episode_id")
        if not isinstance(eid, int):
            continue
        kind = rec.get("kind") or "series"
        action = rec.get("type") or rec.get("action") or ""
        if action == "skip":
            skip_ids.add(eid)
        elif action in ("retry", "delete"):
            ids = retry_ids if action == "retry" else delete_ids
            langs = retry_langs if action == "retry" else delete_langs
            kinds = retry_kinds if action == "retry" else delete_kinds
            ids.add(eid)
            kinds.setdefault(eid, set()).add(kind)
            lang = normalize_language(rec.get("language"))
            entry = langs.setdefault(eid, set())
            if isinstance(lang, str) and lang:
                entry.add(lang)
            else:
                entry.add(None)  # null language = whole episode
    if retry_ids or delete_ids:
        states = load_state()
        kept = []
        changed = False
        for e in states:
            eid = e.get("sonarrEpisodeId")
            lang = e.get("language")
            e_kind = e.get("kind") or "series"
            drop = False
            if isinstance(eid, int) and eid in retry_ids:
                if e_kind in (retry_kinds.get(eid) or {"series"}):
                    langs = retry_langs.get(eid)
                    drop = not langs or (None in langs) or (lang in langs)
            elif isinstance(eid, int) and eid in delete_ids:
                if e_kind in (delete_kinds.get(eid) or {"series"}):
                    langs = delete_langs.get(eid)
                    drop = not langs or (None in langs) or (lang in langs)
            if drop:
                changed = True
            else:
                kept.append(e)
        if changed:
            rewrite_jsonl(STATE_FILE, kept)
    for eid in sorted(delete_ids):
        kinds = delete_kinds.get(eid) or {"series"}
        langs = delete_langs.get(eid)
        all_langs = not langs or None in langs
        lang_list = None if all_langs else sorted(langs)
        if "series" in kinds:
            deleted = _delete_episode_subtitles(cfg, eid, langs=lang_list)
            log(f"action: delete episode {eid} (removed {len(deleted)} SRTs, state cleared)")
        if "movie" in kinds:
            deleted = _delete_movie_subtitles(cfg, eid, langs=lang_list)
            log(f"action: delete movie {eid} (removed {len(deleted)} SRTs, state cleared)")
        if "series" in kinds:
            media_path, title = "", None
            try:
                info = get_episode(cfg, eid)
                ef = info.get("episodeFile") or {}
                media_path = map_path(ef.get("path", "")) if ef.get("path") else ""
                title = info.get("title") or info.get("Name")
            except Exception:
                pass
            if media_path:
                jellyfin_refresh(cfg, media_path, title)
        if "movie" in kinds:
            try:
                movies = get_movies(cfg)
                m = next(
                    (x for x in (movies.get("data") or []) if x.get("radarrId") == eid),
                    None,
                )
                if m and m.get("path"):
                    jellyfin_refresh(
                        cfg, map_path(m["path"]), m.get("title"), item_type="Movie"
                    )
            except Exception:
                pass
    for eid in sorted(retry_ids):
        kinds = retry_kinds.get(eid) or {"series"}
        langs = retry_langs.get(eid)
        all_langs = not langs or None in langs
        lang_list = None if all_langs else sorted(langs)
        if "series" in kinds:
            deleted = _delete_episode_subtitles(cfg, eid, langs=lang_list)
            log(f"action: retry episode {eid} (state cleared, {len(deleted)} SRTs removed)")
        if "movie" in kinds:
            deleted = _delete_movie_subtitles(cfg, eid, langs=lang_list)
            log(f"action: retry movie {eid} (state cleared, {len(deleted)} SRTs removed)")
    for eid in sorted(skip_ids):
        log(f"action: skip episode {eid} (excluded this pass)")
    return skip_ids


def _bazarr_endpoint(cfg, lang):
    """Dual-Bazarr upload routing: ja -> primary BAZARR_URL (Japanese
    profile); any other lang -> BAZARR_URL_2 (id/en profile) when
    configured, else primary. Returns (base_url, api_key)."""
    if normalize_language(lang) == "ja":
        return cfg["BAZARR_URL"].rstrip("/"), cfg["BAZARR_API_KEY"]
    base2 = cfg.get("BAZARR_URL_2")
    if base2:
        return base2.rstrip("/"), cfg.get("BAZARR_API_KEY_2") or ""
    return cfg["BAZARR_URL"].rstrip("/"), cfg["BAZARR_API_KEY"]


def _valid_srt_bytes(value):
    """Return true for non-empty bytes containing at least one parsed SRT cue."""
    if not isinstance(value, (bytes, bytearray)) or not value.strip():
        return False
    try:
        return bool(parse_srt(bytes(value).decode("utf-8-sig", errors="replace")))
    except Exception:
        return False


def _install_srt_no_clobber(tmp_path, target_path, generated_bytes, before_paths):
    """Install generated SRT without replacing a newly appearing target."""
    try:
        try:
            os.link(tmp_path, target_path)
            return generated_bytes
        except FileExistsError:
            with open(target_path, "rb") as fh:
                existing_bytes = fh.read()
            if _valid_srt_bytes(existing_bytes):
                return existing_bytes
            if os.path.abspath(target_path) not in before_paths:
                raise RuntimeError(f"concurrent invalid target appeared ({target_path})")
            os.replace(tmp_path, target_path)
            return generated_bytes
    finally:
        try:
            os.remove(tmp_path)
        except OSError:
            pass


def _ensure_sidecar_on_disk(cfg, media_path, lang, srt_bytes, retries=3, delay=2.0, before=None):
    """After a Bazarr upload 204, confirm {stem}.{lang}.hi.srt exists on the
    NAS. Bazarr's upload endpoint returns 204 after QUEUEING the job async,
    and the async job can crash (movies: NULL profileId -> TypeError in
    Bazarr upload.py) so the file never lands. Poll for it, then write it
    directly (tmp + os.replace, exactly like the ladder path) if still
    missing. Returns (path, wrote) or (None, False) on persistent failure.
    media_path MUST be the already-mapped NAS path."""
    if not media_path:
        return None, False
    stem = os.path.splitext(media_path)[0]
    normalized = normalize_language(lang)
    target = canonical_target_sidecar_path(stem, normalized)
    if before is not None:
        landed = canonicalize_new_provider_sidecar(stem, normalized, before)
        if landed:
            return landed, False
    for i in range(retries):
        if os.path.isfile(target):
            return target, False
        if i < retries - 1:
            time.sleep(delay)
    if os.path.isfile(target):
        return target, False
    try:
        tmp = target + ".direct.tmp"
        with open(tmp, "wb") as fh:
            fh.write(srt_bytes)
        os.replace(tmp, target)
        return target, True
    except OSError as exc:
        log(f"upload: direct write failed for {target}: {exc}")
        return None, False


def upload_srt(cfg, series_id, ep_id, lang, srt_bytes, filename="sub.srt", media_path=None, before_paths=None):
    """Manual upload via POST /api/episodes/subtitles (verified against live
    Bazarr swagger.json 2026-08-07): query seriesid/episodeid/language/
    forced/hi + multipart file. Movies use POST /api/movies/subtitles
    (radarrid) via upload_srt_movie. Bazarr ignores the uploaded
    filename (subliminal writes {canonical HI sidecar}), and the
    endpoint has no comment/history field, so AI provenance lives only in the
    first SRT cue. After a 204 (Bazarr queues the job async), the on-disk
    sidecar is verified/direct-written via _ensure_sidecar_on_disk when
    media_path is provided; a missing file that cannot be written fails the
    upload (returns None) so the item is NOT marked done."""
    base, key = _bazarr_endpoint(cfg, lang)
    lang = normalize_language(lang)
    url = base + "/episodes/subtitles"
    params = {
        "seriesid": series_id,
        "episodeid": ep_id,
        "language": lang,
        "forced": "false",
        "hi": "true",
    }
    headers = {"X-API-KEY": key}
    files = {"file": (filename, srt_bytes, "application/x-subrip")}
    if before_paths is None:
        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)} if media_path else set()
    last_code = None
    for attempt in range(3):
        try:
            r = requests.post(
                url, params=params, headers=headers, files=files, timeout=120
            )
            last_code = r.status_code
            if r.status_code == 204:
                if media_path is None:
                    log("series upload 204 (no media path to verify; trusting Bazarr)")
                    return 204
                target, wrote = _ensure_sidecar_on_disk(cfg, media_path, lang, srt_bytes, before=before_paths)
                if target is None:
                    log(
                        f"series upload 204 + file MISSING -> direct write failed "
                        f"({media_path})"
                    )
                    return None
                try:
                    with open(target, "rb") as fh:
                        landed = fh.read()
                except OSError as exc:
                    log(f"series upload 204 + file unreadable ({target}): {exc}")
                    return None
                if landed != srt_bytes:
                    if (os.path.abspath(target) not in before_paths
                            and _valid_srt_bytes(landed)):
                        log(f"series upload 204 + concurrent winner preserved ({target})")
                        return 204
                    log(f"series upload 204 + existing sidecar differs ({target})")
                    return None
                log(
                    "series upload 204 + "
                    + ("file MISSING -> direct write" if wrote else "file confirmed")
                    + f" ({target})"
                )
                return 204
            log(
                f"    [upload] HTTP {r.status_code} (attempt {attempt + 1}): {r.text[:200]}"
            )
        except requests.RequestException as exc:
            last_code = None
            log(f"    [upload] network error (attempt {attempt + 1}): {exc}")
        if attempt < 2:
            time.sleep(5 * (attempt + 1))
    return last_code


def upload_srt_movie(cfg, movie_id, lang, srt_bytes, filename="sub.srt", media_path=None, before_paths=None):
    """Manual movie subtitle upload via POST /api/movies/subtitles (radarr):
    query radarrid/language/forced/hi + multipart file (Bazarr's swagger
    requires the param literally named radarrid; movieid -> HTTP 400).
    Identical semantics to upload_srt (3 attempts, 5s*attempt backoff, 204
    success, last_code returned otherwise); Bazarr ignores the uploaded
    filename and writes {canonical HI sidecar}. After a 204, the
    on-disk sidecar is verified/direct-written via _ensure_sidecar_on_disk
    (movie path resolved from Bazarr when media_path is not passed); a
    missing file that cannot be written fails the upload (returns None)."""
    lang = normalize_language(lang)
    if not media_path:
        try:
            movies = get_movies(cfg)
            m = next(
                (x for x in (movies.get("data") or []) if x.get("radarrId") == movie_id),
                None,
            )
            if m and m.get("path"):
                media_path = map_path(m["path"])
        except Exception:
            media_path = None
    base, key = _bazarr_endpoint(cfg, lang)
    url = base + "/movies/subtitles"
    params = {
        "radarrid": movie_id,
        "language": lang,
        "forced": "false",
        "hi": "true",
    }
    headers = {"X-API-KEY": key}
    files = {"file": (filename, srt_bytes, "application/x-subrip")}
    if before_paths is None:
        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)} if media_path else set()
    last_code = None
    for attempt in range(3):
        try:
            r = requests.post(
                url, params=params, headers=headers, files=files, timeout=120
            )
            last_code = r.status_code
            if r.status_code == 204:
                if media_path is None:
                    log("movie upload 204 (no media path to verify; trusting Bazarr)")
                    return 204
                target, wrote = _ensure_sidecar_on_disk(cfg, media_path, lang, srt_bytes, before=before_paths)
                if target is None:
                    log(
                        f"movie upload 204 + file MISSING -> direct write failed "
                        f"({media_path})"
                    )
                    return None
                try:
                    with open(target, "rb") as fh:
                        landed = fh.read()
                except OSError as exc:
                    log(f"movie upload 204 + file unreadable ({target}): {exc}")
                    return None
                if landed != srt_bytes:
                    if (os.path.abspath(target) not in before_paths
                            and _valid_srt_bytes(landed)):
                        log(f"movie upload 204 + concurrent winner preserved ({target})")
                        return 204
                    log(f"movie upload 204 + existing sidecar differs ({target})")
                    return None
                log(
                    "movie upload 204 + "
                    + ("file MISSING -> direct write" if wrote else "file confirmed")
                    + f" ({target})"
                )
                return 204
            log(
                f"    [upload] HTTP {r.status_code} (attempt {attempt + 1}): {r.text[:200]}"
            )
        except requests.RequestException as exc:
            last_code = None
            log(f"    [upload] network error (attempt {attempt + 1}): {exc}")
        if attempt < 2:
            time.sleep(5 * (attempt + 1))
    return last_code


_WEBHOOK_COOLDOWN = {}
_WEBHOOK_LOCK = threading.Lock()
_WEBHOOK_EVENT_COOLDOWN = {
    "pipeline_error": 1800,  # per ep_key; plus 600s global
    "subtitle_done": 60,     # per ep_key
    "pass_completed": 300,   # global
}


def _webhook_urls(cfg):
    """Configured outbound webhook URLs. WEBHOOK_URLS (comma list) wins;
    the legacy HERMES_WEBHOOK_URL is used when unset."""
    urls = [
        u.strip()
        for u in str(cfg.get("WEBHOOK_URLS") or "").split(",")
        if u.strip()
    ]
    if not urls:
        legacy = (cfg.get("HERMES_WEBHOOK_URL") or "").strip()
        if legacy:
            urls = [legacy]
    return urls


def _webhook_secret(cfg):
    return cfg.get("WEBHOOK_SECRET") or cfg.get("HERMES_WEBHOOK_SECRET") or ""


def _webhook_events(cfg):
    """Enabled event types; empty/unset = all."""
    raw = cfg.get("WEBHOOK_EVENTS")
    if raw is None or not str(raw).strip():
        return {"subtitle_done", "pipeline_error", "pass_completed"}
    return {e.strip() for e in str(raw).split(",") if e.strip()}


def notify_webhook(cfg, event_type, payload, ep_key=None):
    """Fire-and-forget HMAC-signed webhook POST to every configured URL.

    Signature (unchanged from notify_hermes):
      X-Webhook-Signature-V2 = hmac_sha256_hex(secret, "<ts>.<body>")
      X-Webhook-Timestamp = str(int(time.time()))
    Retries twice on network error / 5xx with 2s/5s backoff. Per-event
    cooldowns: pipeline_error 1800s per ep_key + 600s global; subtitle_done
    60s per ep_key; pass_completed 300s global. Never raises, never blocks
    (daemon thread)."""
    try:
        urls = _webhook_urls(cfg)
        secret = _webhook_secret(cfg)
        if not urls or not secret:
            return
        if event_type not in _webhook_events(cfg):
            return
    except Exception:
        return

    global _GLOBAL_HELP_LAST
    now = time.time()
    if event_type == "pipeline_error":
        with _WEBHOOK_LOCK:
            last = _HELP_COOLDOWN.get(ep_key, 0.0)
        if now - last < 1800:
            return
        with _WEBHOOK_LOCK:
            if now - _GLOBAL_HELP_LAST < 600:
                log("webhook: pipeline_error throttled (global)")
                return
    elif event_type == "subtitle_done":
        with _WEBHOOK_LOCK:
            last = _WEBHOOK_COOLDOWN.get(("subtitle_done",) + tuple(ep_key or ()), 0.0)
        if now - last < 60:
            return
    elif event_type == "pass_completed":
        with _WEBHOOK_LOCK:
            last = _WEBHOOK_COOLDOWN.get(("pass_completed",), 0.0)
        if now - last < 300:
            return

    def _run():
        global _GLOBAL_HELP_LAST
        for url in urls:
            try:
                body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
                ts = str(int(time.time()))
                sig = hmac.new(
                    secret.encode(), ts.encode() + b"." + body, hashlib.sha256
                ).hexdigest()
                headers = {
                    "X-Webhook-Signature-V2": sig,
                    "X-Webhook-Timestamp": ts,
                    "Content-Type": "application/json",
                }
                code = None
                for attempt in range(3):
                    try:
                        r = requests.post(url, data=body, headers=headers, timeout=10)
                        code = r.status_code
                        if code < 500:
                            break
                    except requests.RequestException:
                        code = None
                    if attempt < 2:
                        time.sleep(2 if attempt == 0 else 5)
                if code is None:
                    log(f"webhook: {event_type} -> {url} failed: network error")
                elif code in (200, 202, 204):
                    log(f"webhook: {event_type} -> {url} HTTP {code}")
                    if event_type == "pipeline_error":
                        with _WEBHOOK_LOCK:
                            if ep_key:
                                _HELP_COOLDOWN[ep_key] = time.time()
                            _GLOBAL_HELP_LAST = time.time()
                    elif event_type == "subtitle_done" and ep_key:
                        with _WEBHOOK_LOCK:
                            _WEBHOOK_COOLDOWN[
                                ("subtitle_done",) + tuple(ep_key)
                            ] = time.time()
                    elif event_type == "pass_completed":
                        with _WEBHOOK_LOCK:
                            _WEBHOOK_COOLDOWN[("pass_completed",)] = time.time()
                else:
                    log(f"webhook: {event_type} -> {url} failed: HTTP {code}")
            except Exception as exc:
                log(f"webhook: {event_type} -> {url} failed: {exc}")

    threading.Thread(target=_run, daemon=True).start()


def notify_hermes(cfg, ep_id, lang, series, tag, exc):
    """Legacy Hermes error notifier — thin wrapper over the generalized
    notify_webhook (pipeline_error event, same payload shape + cooldowns)."""
    notify_webhook(
        cfg,
        "pipeline_error",
        {
            "event_type": "pipeline_error",
            "episode": f"{tag} {series}",
            "lang": lang,
            "error": str(exc)[:500],
            "log_tail": list(_LOG_RING),
        },
        ep_key=(ep_id, lang),
    )


def process_after_asr(
    cfg,
    key,
    ep_id,
    lang,
    series,
    tag,
    src,
    t0,
    cues,
    decision,
    info,
    wav_path,
    srt_path,
    prior_cache=None,
    movie_id=None,
    before_paths=None,
):
    """Process an ASR result using the canonical target language."""
    global _paused
    lang = normalize_language(lang)
    try:
        if decision["needs_translate"]:
            t_tr = time.time()
            if not key and not is_local_translate(cfg):
                raise RuntimeError("translate needed but TRANSLATE_API_KEY empty")
            groups = translate_texts(
                cfg,
                cues,
                lang,
                key,
                info.get("seriesId") or info.get("sonarrSeriesId"),
                ep_id,
                prior_cache,
                series_title=series,
                source_lang=("English" if decision.get("asr_lang") == "en" else "Japanese"),
                skip_guard=(decision.get("asr_lang") == "en"),
            )
            if groups is None:
                raise RuntimeError("translation failed")
            cues_out = []
            texts_out = []
            for s, e, t in groups:
                cues_out.append({"start": cues[s]["start"], "end": cues[e - 1]["end"]})
                texts_out.append(t)
            tr_elapsed = time.time() - t_tr
            log(
                f"  {tag} [{src}->{lang}] translate {tr_elapsed:.0f}s, {len(texts_out)} lines"
            )
        else:
            cues_out = cues
            texts_out = [c["text"] for c in cues]

        # ASR-translated output only: merge too-fast translated cues with the
        # following cue so the reading speed stays within max_cps (ladder
        # output never passes through here — it writes at its own call site).
        merged = cps_merge(
            [
                {"start": c["start"], "end": c["end"], "text": t}
                for c, t in zip(cues_out, texts_out)
            ]
        )
        cues_out = [{"start": c["start"], "end": c["end"]} for c in merged]
        texts_out = [c["text"] for c in merged]

        media_path = map_path((info.get("episodeFile") or {}).get("path", "")) or None
        if before_paths is None:
            before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)} if media_path else set()
        write_srt(cues_out, texts_out, srt_path, header=AI_MARKER)
        with open(srt_path, "rb") as fh:
            srt_bytes = fh.read()
        if movie_id is not None:
            code = upload_srt_movie(
                cfg, movie_id, lang, srt_bytes, filename=os.path.basename(srt_path),
                media_path=media_path,
                before_paths=before_paths,
            )
        else:
            code = upload_srt(
                cfg,
                info.get("seriesId") or info.get("sonarrSeriesId"),
                ep_id,
                lang,
                srt_bytes,
                filename=os.path.basename(srt_path),
                media_path=media_path,
                before_paths=before_paths,
            )
        if code != 204:
            raise RuntimeError(f"upload HTTP {code} (expected 204)")
        ef = info.get("episodeFile") or {}
        if ef.get("path"):
            jellyfin_refresh(
                cfg,
                map_path(ef["path"]),
                info.get("title") or info.get("Name"),
                item_type="Movie" if movie_id is not None else "Episode",
            )
        elapsed = round(time.time() - t0, 1)
        stem = os.path.splitext(map_path((info.get("episodeFile") or {}).get("path", "")))[0] or None
        target = canonical_target_sidecar_path(stem, lang) if media_path else None
        if not target or not os.path.isfile(target):
            raise RuntimeError(f"upload 204 + target sidecar missing ({target})")
        try:
            with open(target, "rb") as fh:
                file_bytes = fh.read()
        except OSError as exc:
            raise RuntimeError(f"upload 204 + target sidecar unreadable ({target}): {exc}")
        if file_bytes != srt_bytes:
            if (os.path.abspath(target) not in before_paths
                    and _valid_srt_bytes(file_bytes)):
                log(f"{series} [{lang}] upload 204 + concurrent winner preserved ({target})")
            else:
                raise RuntimeError(f"upload 204 + target sidecar differs ({target})")
        target_hash = file_sha256(target)
        registry_upsert(
            stem, lang, "asr", source_path=target, source_hash=target_hash,
            target_path=target, target_hash=target_hash, ep_id=ep_id,
            kind=("movie" if movie_id is not None else None),
        )
        st_entry = {
            "sonarrEpisodeId": ep_id,
            "language": lang,
            "status": "done",
            "elapsed_s": elapsed,
            "source": "asr",
        }
        if movie_id is not None:
            st_entry["kind"] = "movie"
        append_state(st_entry)
        log(f"done: {tag} {series} [{src}->{lang}] in {elapsed}s (upload 204)")
        notify_webhook(
            cfg,
            "subtitle_done",
            {
                "event_type": "subtitle_done",
                "episode": f"{tag} {series}",
                "lang": lang,
                "source": "asr",
                "duration_s": int(elapsed),
                "status_code": code,
            },
            ep_key=(ep_id, lang),
        )
        return "done"
    except Exception as exc:
        st_entry = {
            "sonarrEpisodeId": ep_id,
            "language": lang,
            "status": "error",
            "elapsed_s": round(time.time() - t0, 1),
            "source": "asr",
        }
        if movie_id is not None:
            st_entry["kind"] = "movie"
        append_state(st_entry)
        log(f"fail: {series} [{lang}] {exc}")
        notify_hermes(cfg, ep_id, lang, series, tag, exc)
        halt_on_error(cfg, "process_episode", f"{series} [{lang}] {tag}", exc)
        return "failed"
    finally:
        for f in (wav_path, srt_path):
            try:
                os.remove(f)
            except OSError:
                pass


def process_ladder(
    cfg,
    key,
    ep_id,
    lang,
    series,
    tag,
    source,
    info,
    prior_cache=None,
    movie_id=None,
):
    """Ladder translation: translate from an existing jpn/eng subtitle source
    (SKIP ASR entirely), write {stem}.{lang}.hi.srt next to the video with the AI
    marker cue, register the source in the registry and wake Jellyfin. An eng
    source satisfying the en target is adopted verbatim (no marker: it is not
    AI-generated text, but ownership is still registry-tracked). Returns
    "done" or "failed". movie_id (radarr track): uploads via the movies
    endpoint, state rows carry kind "movie", and the Jellyfin refresh searches
    Movie items; None keeps series behavior."""
    lang = normalize_language(lang)
    t0 = time.time()
    kind = source["kind"]
    try:
        media_path = map_path((info.get("episodeFile") or {}).get("path", ""))
        if not media_path or not os.path.isfile(media_path):
            raise RuntimeError(f"media file missing: {media_path}")
        cues = source["cues"] or []
        if not cues:
            raise RuntimeError("ladder source produced no cues")
        srt_path = canonical_target_sidecar_path(os.path.splitext(media_path)[0], lang)
        needs_translate = not ((kind == "eng" and lang == "en") or (kind in ("jpn", "asr") and lang == "ja"))
        if needs_translate:
            if not key and not is_local_translate(cfg):
                raise RuntimeError("translate needed but TRANSLATE_API_KEY empty")
            t_tr = time.time()
            groups = translate_texts(
                cfg,
                cues,
                lang,
                key,
                info.get("seriesId") or info.get("sonarrSeriesId"),
                ep_id,
                prior_cache,
                series_title=series,
                skip_guard=(kind == "eng"),
                source_lang=("English" if kind == "eng" else "Japanese"),
            )
            if groups is None:
                raise RuntimeError("translation failed")
            cues_out = []
            texts_out = []
            for s, e, t in groups:
                cues_out.append({"start": cues[s]["start"], "end": cues[e - 1]["end"]})
                texts_out.append(t)
            log(
                f"  {tag} [{kind}->{lang}] translate {time.time() - t_tr:.0f}s, {len(texts_out)} lines"
            )
            header = AI_MARKER
        else:
            cues_out = cues
            texts_out = [c["text"] for c in cues]
            header = None
        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)}
        tmp = srt_path + ".ladder.tmp"
        write_srt(cues_out, texts_out, tmp, header=header)
        with open(tmp, "rb") as fh:
            generated_bytes = fh.read()
        srt_bytes = _install_srt_no_clobber(tmp, srt_path, generated_bytes, before_paths)
        if movie_id is not None:
            code = upload_srt_movie(
                cfg, movie_id, lang, srt_bytes, filename=os.path.basename(srt_path),
                media_path=media_path,
                before_paths=before_paths,
            )
        else:
            code = upload_srt(
                cfg,
                info.get("seriesId") or info.get("sonarrSeriesId"),
                ep_id,
                lang,
                srt_bytes,
                filename=os.path.basename(srt_path),
                media_path=media_path,
                before_paths=before_paths,
            )
        if code != 204:
            raise RuntimeError(f"upload HTTP {code} (expected 204)")
        stem = os.path.splitext(media_path)[0]
        # Registry the produced {stem}.{lang}.hi.srt with the SOURCE's
        # provenance: when the ladder used an on-disk sidecar that still
        # matches its own registry row (webhook embedded extraction, hash
        # untouched), PRESERVE the row's source_kind instead of flipping it
        # to "external" — a webhook-extracted sidecar is aligned by
        # construction even when consumed from disk. "external" only when
        # the sidecar was clobbered (hash mismatch) or never registered.
        # A tmp extraction is embedded by construction and never clobbers
        # the on-disk sidecar's own row.
        canonical_target = canonical_target_sidecar_path(stem, lang)
        target_path = canonical_target if os.path.isfile(canonical_target) else None
        target_hash = file_sha256(target_path) if target_path else None
        source_path = None if source.get("tmp") else source.get("source_path")
        source_hash = None if source.get("tmp") else source.get("source_hash")
        src_row = registry_get(stem, kind)
        if source.get("tmp"):
            source_kind = "embedded"
        elif (
            src_row
            and src_row.get("source_hash")
            and src_row["source_hash"] == source["source_hash"]
        ):
            source_kind = src_row.get("source_kind") or "external"
        else:
            source_kind = "external"
        registry_upsert(
            stem,
            lang,
            kind,
            source_path=source_path,
            source_hash=source_hash,
            source_kind=source_kind,
            ep_id=ep_id,
            retimed=source.get("align_stats", {}).get("method"),
            matched_frac=source.get("align_stats", {}).get("matched_frac"),
            effective_timeline=source.get("effective_timeline") or _timeline_snapshot(cues),
            timeline_kind=source.get("timeline_kind") or "raw",
            retime_status=source.get("align_stats", {}).get("retime_status"),
            retime_reason=source.get("align_stats", {}).get("retime_reason"),
            retime_policy_version=RETIME_POLICY_VERSION,
            kind=("movie" if movie_id is not None else None),
            target_path=target_path,
            target_hash=target_hash,
        )
        elapsed = round(time.time() - t0, 1)
        st_entry = {
            "sonarrEpisodeId": ep_id,
            "language": lang,
            "status": "done",
            "elapsed_s": elapsed,
            "source": kind,
        }
        if movie_id is not None:
            st_entry["kind"] = "movie"
        append_state(st_entry)
        jellyfin_refresh(
            cfg,
            media_path,
            info.get("title") or info.get("Name"),
            item_type="Movie" if movie_id is not None else "Episode",
        )
        log(f"done: {tag} {series} [{kind}->{lang}] in {elapsed}s (upload 204, ladder)")
        notify_webhook(
            cfg,
            "subtitle_done",
            {
                "event_type": "subtitle_done",
                "episode": f"{tag} {series}",
                "lang": lang,
                "source": kind,
                "duration_s": int(elapsed),
                "status_code": code,
            },
            ep_key=(ep_id, lang),
        )
        return "done"
    except Exception as exc:
        st_entry = {
            "sonarrEpisodeId": ep_id,
            "language": lang,
            "status": "error",
            "elapsed_s": round(time.time() - t0, 1),
            "source": kind,
        }
        if movie_id is not None:
            st_entry["kind"] = "movie"
        append_state(st_entry)
        log(f"fail: {series} [{lang}] {exc}")
        notify_hermes(cfg, ep_id, lang, series, tag, exc)
        halt_on_error(cfg, "process_ladder", f"{series} [{lang}] {tag}", exc)
        return "failed"
    finally:
        if source.get("tmp") and source.get("source_path"):
            try:
                os.remove(source["source_path"])
            except OSError:
                pass
        if source.get("align_tmp"):
            _silent_remove(source["align_tmp"])


def run_upgrades(cfg, key, prior_cache=None):
    """Auto-upgrade pass: AI-owned subs produced from ASR/eng/jpn get
    re-translated from a better jpn source when one appears — including rows
    whose current output came from a jpn source (source 'jpn': a Jimaku .ja
    sidecar that arrived after generation, adopted verbatim or translated,
    may itself be superseded by a NEWER sidecar; late-arriving better sources
    win automatically). Only OUTPUT languages are eligible (lang in
    TARGET_LANGS) so source-sidecar rows ({stem}.jpn.srt etc., written by the
    webhook/_register_external_sidecar) are never re-processed. Guards: only
    AI-owned subs (registry authoritative, marker fallback), refine-history
    skip (LADDER_SKIP_REFINED), source-hash dedup (re-translation only when
    the jpn source file actually changed/new), per-episode cooldown +
    per-pass upgrade budget (LADDER_UPGRADE_BUDGET). Rows oldest-first.
    Returns {"upgraded": n, "checked": n}."""
    lc = _ladder_cfg(cfg)
    if lc["upgrade_budget"] <= 0:
        return {"upgraded": 0, "checked": 0}
    registry = load_registry()
    refined = load_refined_set() if lc["skip_refined"] else set()
    now = datetime.now(timezone.utc)
    target_langs = set(configured_languages(cfg.get("TARGET_LANGS") or []))
    rows = sorted(
        (
            rec
            for rec in registry.values()
            if rec.get("source") in ("asr", "eng", "jpn")
            and normalize_language(rec.get("lang")) in target_langs and not (rec.get("source") == "jpn" and rec.get("lang") == "jpn")
        ),
        key=lambda r: r.get("updated_ts") or r.get("created_ts") or "",
    )
    upgraded = 0
    checked = 0
    for rec in rows:
        ep_id = rec.get("episode_id")
        lang = normalize_language(rec.get("lang"))
        if upgraded >= lc["upgrade_budget"]:
            break
        if (ep_id, lang) in refined:
            log(f"upgrade: skip {ep_id} [{lang}] refined (refine_history)")
            continue
        updated = rec.get("updated_ts") or rec.get("created_ts") or ""
        try:
            age_h = (
                now - datetime.fromisoformat(updated.replace("Z", "+00:00"))
            ).total_seconds() / 3600
        except Exception:
            age_h = None  # unknown age: eligible
        if age_h is not None and age_h < lc["cooldown_h"]:
            continue
        if _hunt_state_is_tombstoned(rec):
            continue  # orphaned sonarr id (404 tombstone): skip silently
        checked += 1
        try:
            info = get_episode(cfg, ep_id)
        except Exception as exc:
            status = getattr(getattr(exc, "response", None), "status_code", None)
            if status == 404:
                # same disease the hunt fixed: never re-probe a dead id
                _jimaku_hunt_tombstone(rec, now)
                log(f"upgrade: ep {ep_id}: sonarr episode gone (404), skipping")
            else:
                log(f"upgrade: get_episode {ep_id} failed: {exc}")
            continue
        ef = info.get("episodeFile") or {}
        if not info.get("hasFile") or not ef.get("path"):
            continue
        media_path = map_path(ef["path"])
        if not os.path.isfile(media_path):
            continue
        if not sub_is_ai_owned(registry, ep_id, lang, media_path):
            continue  # foreign sub on disk: never touched
        ladder = detect_ladder_source(
            cfg,
            media_path,
            lang,
            cfg.get("TMP_DIR", "/tmp"),
            ep_id,
            info.get("seriesId") or info.get("sonarrSeriesId"),
            series_title=info.get("seriesTitle") or info.get("title"),
            season=info.get("seasonNumber"),
            episode=info.get("episodeNumber"),
        )
        if ladder["kind"] != "jpn":
            continue
        if (
            rec.get("source_hash")
            and ladder["source_hash"]
            and rec["source_hash"] == ladder["source_hash"]
            and _timeline_matches_source(rec, ladder)
        ):
            continue  # same raw source and effective timeline already translated
        season = info.get("seasonNumber", "?")
        ep_num = info.get("episodeNumber", "?")
        tag = (
            f"S{season:02d}E{ep_num:02d}"
            if isinstance(season, int) and isinstance(ep_num, int)
            else f"S{season}E{ep_num}"
        )
        series = info.get("seriesTitle") or info.get("title") or "?"
        status = process_ladder(
            cfg, key, ep_id, lang, series, tag, ladder, info, prior_cache=prior_cache
        )
        if status == "done":
            upgraded += 1
    if checked or upgraded:
        log(
            f"upgrade pass: checked={checked} upgraded={upgraded} "
            f"(budget={lc['upgrade_budget']}, cooldown_h={lc['cooldown_h']})"
        )
    return {"upgraded": upgraded, "checked": checked}


def run_timeline_recalc(cfg):
    """One-shot library-wide timeline recalculation (Dungeon People S01E09
    class repair): for every registry-tracked jpn sidecar whose on-disk file
    FAILS validate_srt_timeline, rebuild {stem}.ja.hi.srt from the pristine ASR
    cache cues when a matching cache entry exists; translations (en/id) are
    NOT regenerated here — the normal upgrade pass picks them up because the
    ja source_hash changes.

    Guards: AI-owned/registry rows only (never touches foreign subs),
    per-pass budget TIMELINE_RECALC_BUDGET, and current provenance plus the
    healthy timeline gate provide idempotency; no persistent recalculation
    marker is written. Returns {"repaired": n, "checked": n,
    "failed": [(stem, reason)]}.
    "failed": [(stem, reason)]}."""
    budget = int(cfg.get("TIMELINE_RECALC_BUDGET", 50))
    if budget <= 0:
        return {"repaired": 0, "checked": 0, "failed": []}
    registry = load_registry()
    # unique stems from jpn-source rows only (the ja timeline is the
    # translation base; en/id siblings inherit its timing). Legacy rows may
    # key on (episode_id, lang) without a stem — skip those (no file path).
    stems = {}
    for (key_stem, lang), rec in registry.items():
        if (
            lang == "ja"
            and isinstance(key_stem, str)
            and key_stem.startswith("/")
            and rec.get("source") in ("jpn", "eng", "asr")
        ):
            stems[key_stem] = rec
    repaired = 0
    checked = 0
    failed = []
    for stem, rec in sorted(stems.items()):
        if repaired >= budget:
            break
        media_path = None
        for ext in (".mkv", ".mp4", ".avi", ".ts"):
            cand = stem + ext
            if os.path.isfile(cand):
                media_path = cand
                break
        ja_path = canonical_target_sidecar_path(stem, "ja")
        legacy_ja_paths = [p for p in replaceable_target_sidecar_paths(stem, "ja") if p != ja_path]
        legacy_ja_path = next((p for p in legacy_ja_paths if os.path.isfile(p)), None)
        if not media_path or (not os.path.isfile(ja_path) and not legacy_ja_path):
            continue
        checked += 1
        if rec.get("source") != "asr":
            continue
        current_row = _registry_current_row(stem, "ja", media_path=media_path, row=rec)
        if not current_row:
            continue
        source_ja_path = ja_path if os.path.isfile(ja_path) else legacy_ja_path
        ownership_path = current_row.get("source_path") or source_ja_path
        if not srt_has_ai_marker(ownership_path):
            continue
        ok, why = validate_srt_timeline(source_ja_path, media_duration_s(media_path))
        if ok:
            continue  # healthy: nothing to do
        # broken: try rebuilding from the pristine ASR cache
        try:
            audio_id = audio_stream_signature(probe_audio(media_path))
        except Exception as exc:
            failed.append((os.path.basename(stem), f"probe: {exc}"))
            continue
        cached = asr_cache_get(audio_id, "ja", media_path)
        if not cached:
            failed.append((os.path.basename(stem), f"broken ({why}); no ASR cache"))
            continue
        lines = []
        n = 0
        for c in cached:
            text = (c.get("text") or "").strip()
            st = max(0, int(c.get("start") or 0))
            en = max(st + 500, int(c.get("end") or 0))
            if not text:
                continue
            n += 1
            ts = lambda ms: "%02d:%02d:%02d,%03d" % (
                ms // 3600000,
                ms % 3600000 // 60000,
                ms % 60000 // 1000,
                ms % 1000,
            )
            lines.append(f"{n}\n{ts(st)} --> {ts(en)}\nAI-generated by ASRSub\n{text}\n")
        if not lines:
            failed.append((os.path.basename(stem), f"broken ({why}); empty cache rebuild"))
            continue
        tmp = ja_path + ".recalc.tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as fh:
                fh.write("\n".join(lines) + "\n")
            ok2, why2 = validate_srt_timeline(tmp, media_duration_s(media_path))
            if not ok2:
                _silent_remove(tmp)
                failed.append((os.path.basename(stem), f"rebuild also fails gate ({why2})"))
                continue
            os.replace(tmp, ja_path)
            if legacy_ja_path and legacy_ja_path != ja_path and srt_has_ai_marker(legacy_ja_path):
                _silent_remove(legacy_ja_path)
        except OSError as exc:
            _silent_remove(tmp)
            failed.append((os.path.basename(stem), f"write failed: {exc}"))
            continue
        h = file_sha256(ja_path)
        registry_upsert(
            stem, "ja", "asr", source_path=ja_path, source_hash=h,
            source_kind=rec.get("source_kind") if rec.get("source_kind") in ("embedded", "external") else None,
            ep_id=rec.get("episode_id"), audio_id=audio_id,
            effective_timeline=[
                {"start": c.get("start"), "end": c.get("end"), "text": c.get("text")}
                for c in cached if (c.get("text") or "").strip()
            ],
            timeline_kind="raw", retime_policy_version=RETIME_POLICY_VERSION,
        )
        repaired += 1
        log(f"timeline-recalc: rebuilt {os.path.basename(ja_path)} from ASR cache ({why})")
    log(
        f"timeline-recalc pass: checked={checked} repaired={repaired} "
        f"unrepairable={len(failed)} (budget={budget})"
    )
    for name, reason in failed:
        log(f"timeline-recalc: UNREPAIRED {name}: {reason}")
    return {"repaired": repaired, "checked": checked, "failed": failed}


def _jimaku_hunt_backoff_minutes(attempts):
    """Exponential backoff: 30*2^(N-1) capped at 1440 min (24h).
    attempts >=1 -> minutes, attempts <=0 -> 0 (fresh row immediate)."""
    try:
        n = int(attempts)
    except Exception:
        n = 0
    if n <= 0:
        return 0
    return min(30 * (2 ** (n - 1)), 1440)


def _jimaku_hunt_parse_ts(ts_str):
    if not ts_str:
        return None
    try:
        return datetime.fromisoformat(str(ts_str).replace("Z", "+00:00"))
    except Exception:
        return None


def _hunt_state_key(rec):
    """Backoff state key for one hunt item: "<stem>|<lang>|<ep_id or ''>"."""
    ep_id = rec.get("episode_id")
    return f"{rec.get('stem') or ''}|{rec.get('lang') or ''}|{ep_id if isinstance(ep_id, int) else ''}"


def _hunt_state_load():
    """Tolerant read of HUNT_STATE_FILE: missing/corrupt -> {} (all items
    fresh); never raises."""
    try:
        with open(HUNT_STATE_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            return data
    except (OSError, ValueError):
        pass
    return {}


def _hunt_state_save(state):
    """Atomic write (tmp + os.replace); failures logged, never raised."""
    try:
        d = os.path.dirname(HUNT_STATE_FILE)
        if d:
            os.makedirs(d, exist_ok=True)
        tmp = HUNT_STATE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(state, fh, ensure_ascii=False, indent=2)
            fh.write("\n")
        os.replace(tmp, HUNT_STATE_FILE)
    except OSError as exc:
        log(f"WARNING: jimaku hunt: cannot write {HUNT_STATE_FILE}: {exc}")


def _hunt_state_get(rec):
    """Effective (last_ts, attempts) for one hunt item: the dedicated hunt
    state file FIRST, legacy registry-row fields (jimaku_hunt_last_ts /
    jimaku_hunt_attempts) when no state-file entry exists — so backoffs
    recorded before the migration keep their ladder positions."""
    entry = _hunt_state_load().get(_hunt_state_key(rec))
    if isinstance(entry, dict):
        return entry.get("last_ts"), entry.get("attempts")
    return rec.get("jimaku_hunt_last_ts"), rec.get("jimaku_hunt_attempts")


def _hunt_state_attempts(rec):
    """Effective attempts count for log lines (post-record reads give the
    just-persisted number)."""
    _, attempts = _hunt_state_get(rec)
    try:
        return int(attempts) if attempts is not None else 0
    except Exception:
        return 0


def _jimaku_hunt_eligible(rec, now):
    """True when backoff window has elapsed. Fresh items (no hunt state)
    are immediately eligible. Backoff = min(30*2^(N-1),1440) minutes."""
    last_ts, attempts = _hunt_state_get(rec)
    try:
        n = int(attempts) if attempts is not None else 0
    except Exception:
        n = 0
    if not last_ts:
        return True
    dt = _jimaku_hunt_parse_ts(last_ts)
    if dt is None:
        return True
    backoff = _jimaku_hunt_backoff_minutes(n if n > 0 else 1)
    # fresh row with no attempts but with last_ts shouldn't happen; treat as needing 30min
    if n == 0:
        backoff = 30
    elapsed_min = (now - dt).total_seconds() / 60.0
    return elapsed_min >= backoff


def _jimaku_hunt_record_attempt(rec, now):
    """Persist hunt miss tracking OUTSIDE the provenance ledger: writes
    {"last_ts", "attempts", "updated"} under "<stem>|<lang>|<ep>" in
    HUNT_STATE_FILE. (registry_upsert here used to append bookkeeping rows
    indistinguishable from real extractions — one pass flooded the ledger
    and the dashboard Recent feed.) Legacy jimaku_hunt_* row fields are only
    READ (fallback in _hunt_state_get), never written. Signature and
    never-raises semantics unchanged."""
    try:
        key = _hunt_state_key(rec)
        state = _hunt_state_load()
        entry = state.get(key)
        prev_attempts = entry.get("attempts") if isinstance(entry, dict) else rec.get("jimaku_hunt_attempts")
        try:
            n = int(prev_attempts) if prev_attempts is not None else 0
        except Exception:
            n = 0
        now_iso = now.strftime("%Y-%m-%dT%H:%M:%SZ")
        state[key] = {"last_ts": now_iso, "attempts": n + 1, "updated": now_iso}
        _hunt_state_save(state)
    except Exception as exc:
        log(f"WARNING: jimaku hunt: failed to record attempt for ep {rec.get('episode_id')}: {exc}")


# Orphaned-episode tombstone pin: attempts >= this value in HUNT_STATE_FILE
# means "Sonarr returns 404 for this id" (organic hunt misses can never
# reach it: backoff caps at one probe/24h). Existing readers need no change:
# _jimaku_hunt_eligible treats it as a maximal (24h-capped) backoff.
_TOMBSTONE_ATTEMPTS = 99


def _hunt_state_is_tombstoned(rec):
    """True when the item is tombstoned as orphaned in HUNT_STATE_FILE
    (attempts pinned >= _TOMBSTONE_ATTEMPTS); legacy registry-row fallback
    honored via _hunt_state_get."""
    _, attempts = _hunt_state_get(rec)
    try:
        return int(attempts) >= _TOMBSTONE_ATTEMPTS
    except Exception:
        return False


def _jimaku_hunt_tombstone(rec, now):
    """Persist an orphaned-episode tombstone (Sonarr 404, e.g. from the
    upgrade pass) into HUNT_STATE_FILE under the same "<stem>|<lang>|<ep>"
    key: attempts pinned at _TOMBSTONE_ATTEMPTS so existing backoff readers
    treat the item as backed off while the upgrade pass skips it outright.
    Never raises."""
    try:
        key = _hunt_state_key(rec)
        now_iso = now.strftime("%Y-%m-%dT%H:%M:%SZ")
        state = _hunt_state_load()
        entry = state.get(key)
        prev = entry.get("attempts") if isinstance(entry, dict) else rec.get("jimaku_hunt_attempts")
        try:
            n = int(prev) if prev is not None else 0
        except Exception:
            n = 0
        state[key] = {
            "last_ts": now_iso,
            "attempts": max(n, _TOMBSTONE_ATTEMPTS),
            "updated": now_iso,
        }
        _hunt_state_save(state)
    except Exception as exc:
        log(f"WARNING: upgrade: failed to tombstone ep {rec.get('episode_id')}: {exc}")


def run_jimaku_hunt(cfg, prior_cache=None):
    """Per-pass Jimaku sweep: an episode or movie whose on-disk ja came from ASR
    (registry source 'asr') can never receive real Japanese subs on its own —
    Bazarr recorded the AI upload as a perfect-score manual row its upgrade
    task never revisits, and bazarr-jp only searches Jimaku while ja counts
    as missing. For each eligible episode/movie ask Bazarr to search+download
    jpn again (bazarr_jpn_candidate / bazarr_jpn_movie_candidate with
    return_meta=True); a fresh download lands as a plain {stem}.jpn.srt
    sidecar — no re-timing/registration here, the normal ladder + upgrade pass
    adopts it on subsequent passes.
    Series items try the DIRECT Jimaku path first (jimaku_direct_candidate,
    JIMAKU_DIRECT_ENABLED): resolve + list_files for that episode without
    Bazarr; a fresh canonical HI landing counts as landed and SKIPS the
    Bazarr search for that item. Only when the direct path cannot run or
    finds nothing does the flow fall through to bazarr_jpn_candidate below.
    Movies stay on the Bazarr-only path. A Jimaku 429 on the direct path
    aborts the rest of the pass exactly like a Bazarr 429 (no attempt
    counted).
    Guards: per-item exponential backoff tracked in HUNT_STATE_FILE
    (<stem>|<lang>|<ep> -> last_ts/attempts; legacy registry-row
    jimaku_hunt_* fields honored when no state entry exists)
    (30m, 1h, 2h, 4h, 8h, 16h, 24h cap), per-pass budget
    (LADDER_JIMAKU_HUNT_BUDGET, shared with movies; LADDER_JIMAKU_HUNT_BUDGET_MOVIES
    may override for movies, default separate), rows oldest hunt_last_ts first
    (None sorts oldest). The positive _BAZARR_JPN_CACHE / _BAZARR_JPN_MOVIE_CACHE
    entry is dropped for every freshly searched item so later ladder reads
    re-scan disk instead of trusting stale cache. 429 rate limit aborts the rest
    of the pass (WARNING with reset_after, no attempt counted). Tiny sleep (2.5s)
    between searches avoids bursting >24 req/min. prior_cache mirrors run_upgrades
    (unused). Returns {"checked": n, "searched": m, "landed": k}; never raises."""
    lc = _ladder_cfg(cfg)
    if lc["jimaku_hunt_budget"] <= 0:
        return {"checked": 0, "searched": 0, "landed": 0}
    registry = load_registry()
    now = datetime.now(timezone.utc)
    # One hunt per episode/movie: dedup registry rows by (kind, episode_id),
    # the OLDEST updated_ts wins for dedup identity; ordering later uses hunt ts.
    by_series = {}
    by_movie = {}
    for rec in registry.values():
        if rec.get("source") != "asr" or normalize_language(rec.get("lang")) != "ja":
            continue
        ep_id = rec.get("episode_id")
        if not isinstance(ep_id, int):
            continue
        is_movie = rec.get("kind") == "movie"
        target = by_movie if is_movie else by_series
        cur = target.get(ep_id)
        if cur is None or (rec.get("updated_ts") or "") < (
            cur.get("updated_ts") or ""
        ):
            target[ep_id] = rec
    # Pre-fetch movie path map once (needed for movie rows and for
    # legacy rows without kind where episode_id is a radarrId)
    movie_path_map = {}
    if by_series or by_movie:
        try:
            movies = get_movies(cfg)
            for m in movies.get("data") or []:
                rid = m.get("radarrId")
                if isinstance(rid, int) and m.get("path"):
                    movie_path_map[rid] = map_path(m["path"])
        except Exception as exc:
            log(f"jimaku hunt: get_movies failed: {exc}")
            movie_path_map = {}
    # Legacy fallback: rows without kind whose episode_id matches a known
    # radarrId are movie rows stored before kind-aware registry_upsert
    if movie_path_map:
        for ep_id in list(by_series.keys()):
            if ep_id in movie_path_map and ep_id not in by_movie:
                rec = by_series.pop(ep_id)
                by_movie[ep_id] = rec
    # Build combined oldest-hunt-first list with type flag; budget is shared.
    def _hunt_sort_key(item):
        # item is (rec, kind, ep_id) tuple; sort by hunt last_ts (None = oldest)
        _, rec = item
        ts = _jimaku_hunt_parse_ts(_hunt_state_get(rec)[0])
        if ts is None:
            return (0, "")  # None sorts oldest
        return (1, ts.isoformat())
    series_items = [(ep_id, rec) for ep_id, rec in by_series.items()]
    movie_items = [(ep_id, rec) for ep_id, rec in by_movie.items()]
    # combine for shared ordering
    combined = []
    for ep_id, rec in series_items:
        combined.append(("series", ep_id, rec))
    for ep_id, rec in movie_items:
        combined.append(("movie", ep_id, rec))
    # sort by hunt last_ts oldest first (None first), then by string fallback for determinism
    def _key(entry):
        kind, ep_id, rec = entry
        ts = _jimaku_hunt_parse_ts(_hunt_state_get(rec)[0])
        if ts is None:
            return (0, "", ep_id)
        return (1, ts.isoformat(), ep_id)
    combined.sort(key=_key)
    checked = searched = landed = 0
    movie_searched = 0
    movie_budget = lc.get("jimaku_hunt_budget_movies", lc["jimaku_hunt_budget"])
    abort_429 = False
    for kind, ep_id, rec in combined:
        if abort_429:
            break
        # Shared budget guard; also respect separate movie budget when set
        if searched >= lc["jimaku_hunt_budget"]:
            break
        if kind == "movie" and movie_searched >= movie_budget:
            continue
        if not _jimaku_hunt_eligible(rec, now):
            continue
        checked += 1
        if kind == "movie":
            media_path = movie_path_map.get(ep_id)
            if not media_path or not os.path.isfile(media_path):
                continue
            key = ep_id
            _BAZARR_JPN_MOVIE_TRIED.discard(key)
            try:
                cand, how = bazarr_jpn_movie_candidate(
                    cfg,
                    ep_id,
                    media_path,
                    cfg.get("TMP_DIR", "/tmp"),
                    return_meta=True,
                    allow_existing=False,
                )
            except Exception as exc:
                log(f"jimaku hunt: movie {ep_id} search failed: {exc}")
                continue
            if how == "rate_limited":
                log(f"WARNING: jimaku hunt: aborting remaining hunt due to 429 (movie {ep_id})")
                abort_429 = True
                # do not count attempt
                break
            if how in ("download", "searched"):
                searched += 1
                movie_searched += 1
                _BAZARR_JPN_MOVIE_CACHE.pop(key, None)
                if how == "download":
                    landed += 1
                    log(f"jimaku hunt: movie {ep_id}: new jpn sidecar {cand} (ladder picks it up)")
                else:
                    _jimaku_hunt_record_attempt(rec, now)
                    log(f"jimaku hunt: movie {ep_id}: no jpn found (attempt {_hunt_state_attempts(rec)})")
            elif how in ("existing", "cache"):
                # found but not downloaded: back off as miss
                _jimaku_hunt_record_attempt(rec, now)
                log(f"jimaku hunt: movie {ep_id}: jpn already present ({how})")
            elif cand:
                log(f"jimaku hunt: movie {ep_id}: jpn already present ({how})")
            # tiny sleep between searches to avoid 429 bursts
            if searched < lc["jimaku_hunt_budget"] and movie_searched < movie_budget:
                time.sleep(2.5)
        else:
            try:
                info = get_episode(cfg, ep_id)
            except Exception as exc:
                if getattr(getattr(exc, "response", None), "status_code", None) == 404:
                    # Orphaned Sonarr id (episode re-imported under a new id):
                    # without a recorded attempt the row stays immediately
                    # eligible EVERY pass and 404-spams forever. Run the
                    # standard backoff ladder instead (rows are never pruned;
                    # the ghost is already marked by get_episode).
                    _jimaku_hunt_record_attempt(rec, now)
                    log(
                        f"jimaku hunt: ep {ep_id}: sonarr episode gone (404), "
                        "backing off"
                    )
                else:
                    log(f"jimaku hunt: get_episode {ep_id} failed: {exc}")
                continue
            ef = info.get("episodeFile") or {}
            if not info.get("hasFile") or not ef.get("path"):
                continue
            media_path = map_path(ef["path"])
            if not os.path.isfile(media_path):
                continue
            series_id = info.get("seriesId") or info.get("sonarrSeriesId")
            key = (ep_id, series_id)
            # DIRECT Jimaku fast path: resolve + list_files for THIS episode
            # without Bazarr's provider lag. A fresh {stem}.jpn.srt landing
            # counts as landed and skips the Bazarr search entirely; any miss
            # falls through to the providers flow below.
            if lc.get("jimaku_direct_enabled"):
                try:
                    dhit, dmeta = jimaku_direct_candidate(
                        cfg,
                        media_path,
                        info.get("seriesTitle") or info.get("title"),
                        info.get("seasonNumber"),
                        info.get("episodeNumber"),
                        cfg.get("TMP_DIR", "/tmp"),
                        ep_id=ep_id,
                        return_meta=True,
                        force=True,
                    )
                except Exception as exc:
                    log(f"WARNING: jimaku hunt: direct path failed for ep {ep_id}: {exc}")
                    dhit, dmeta = None, None
                if dmeta == "hit":
                    searched += 1
                    _BAZARR_JPN_CACHE.pop(key, None)
                    landed += 1
                    log(
                        f"jimaku hunt: ep {ep_id}: direct Jimaku landing "
                        f"{dhit['source_path']} (Bazarr skipped)"
                    )
                    if searched < lc["jimaku_hunt_budget"]:
                        time.sleep(2.5)
                    continue
                if dmeta == "rate_limited":
                    log(
                        f"WARNING: jimaku hunt: aborting remaining hunt due to 429 "
                        f"(direct, ep {ep_id})"
                    )
                    abort_429 = True
                    break
            # Force a fresh attempt even when this episode's one-shot lookup was
            # already consumed earlier in the daemon lifetime (_BAZARR_JPN_TRIED):
            # searching again is exactly what this sweep is for.
            _BAZARR_JPN_TRIED.discard(key)
            try:
                cand, how = bazarr_jpn_candidate(
                    cfg,
                    ep_id,
                    series_id,
                    media_path,
                    cfg.get("TMP_DIR", "/tmp"),
                    return_meta=True,
                    allow_existing=False,
                )
            except Exception as exc:
                log(f"jimaku hunt: ep {ep_id} search failed: {exc}")
                continue
            if how == "rate_limited":
                log(f"WARNING: jimaku hunt: aborting remaining hunt due to 429 (ep {ep_id})")
                abort_429 = True
                break
            if how in ("download", "searched"):
                # Fresh search: drop any stale positive cache so later ladder
                # reads re-scan disk instead of trusting the old path.
                searched += 1
                _BAZARR_JPN_CACHE.pop(key, None)
                if how == "download":
                    landed += 1
                    log(f"jimaku hunt: ep {ep_id}: new jpn sidecar {cand} (ladder picks it up)")
                else:
                    _jimaku_hunt_record_attempt(rec, now)
                    log(f"jimaku hunt: ep {ep_id}: no jpn found (attempt {_hunt_state_attempts(rec)})")
            elif how in ("existing", "cache"):
                _jimaku_hunt_record_attempt(rec, now)
                log(f"jimaku hunt: ep {ep_id}: jpn already present ({how})")
            elif cand:
                log(f"jimaku hunt: ep {ep_id}: jpn already present ({how})")
            if searched < lc["jimaku_hunt_budget"]:
                time.sleep(2.5)
    log(
        f"jimaku hunt: checked={checked} searched={searched} landed={landed} "
        f"(budget={lc['jimaku_hunt_budget']})"
    )
    return {"checked": checked, "searched": searched, "landed": landed}


# ---------- main ----------


def halt_on_error(cfg, stage, ep_desc, exc, extra=None):
    global _paused
    _paused = True
    rep = {
        "ts": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"),
        "stage": stage,
        "episode": ep_desc,
        "error": str(exc)[:500] or type(exc).__name__,
        "extra": extra or {},
    }
    report_dir = os.path.join(os.path.expanduser("~"), ".config", "asr-pipeline")
    os.makedirs(report_dir, exist_ok=True)
    dst = os.path.join(report_dir, "last_error.json")
    tmp = dst + ".tmp"
    with open(tmp, "w") as fh:
        json.dump(rep, fh, indent=2)
    os.replace(tmp, dst)
    try:
        hist = os.path.join(report_dir, "error_history")
        os.makedirs(hist, exist_ok=True)
        import shutil

        shutil.copy2(
            dst,
            os.path.join(
                hist,
                f"error_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')}.json",
            ),
        )
    except Exception:
        pass
    log(
        f"[pipeline] PAUSED on error - fix first, resume via pctl resume (report: {dst})"
    )


_MTIME_SENTINEL = float("inf")


def _ts_epoch(ts):
    """ISO timestamp (Z or offset) -> epoch seconds, or None."""
    try:
        return datetime.fromisoformat(str(ts).replace("Z", "+00:00")).timestamp()
    except Exception:
        return None


def _order_pass_candidates(cfg, wanted_items, movie_items, regen_items, max_eps):
    """Single merged pass queue, oldest video-file mtime first, with upgraded
    episodes (video file replaced after we generated their subtitles) jumping
    to the front — oldest upgrade first. Replaces the fixed
    series->movie->regen priority. Stat failures (missing/moved file or
    unresolvable path) sort LAST and never crash the pass.

    Returns (ordered_candidates, movies_remaining) where movies_remaining is
    the FULL movie candidate count (pre-cap), used for the pass log."""
    movies_remaining = len(movie_items)
    merged = list(wanted_items) + list(movie_items) + list(regen_items)
    # Latest state row per (kind, ep, lang): prior-row fallback for upgrades.
    state_latest = {}
    for e in load_state():
        k = (e.get("kind") or "series", e.get("sonarrEpisodeId"), normalize_language(e.get("language")))
        cur = state_latest.get(k)
        if cur is None or (e.get("ts") or "") >= (cur.get("ts") or ""):
            state_latest[k] = e
    # Registry rows indexed by (episode_id, lang) for cheap prior lookups.
    ep_registry = {}
    for rec in load_registry().values():
        eid = rec.get("episode_id")
        if isinstance(eid, int) and rec.get("lang"):
            ep_registry[(eid, normalize_language(rec["lang"]))] = rec

    def _prior_ts(kind, ep_id, lang):
        rec = ep_registry.get((ep_id, normalize_language(lang)))
        if rec and rec.get("updated_ts"):
            t = _ts_epoch(rec["updated_ts"])
            if t is not None:
                return t
        st = state_latest.get((kind, ep_id, normalize_language(lang)))
        if st and st.get("ts"):
            return _ts_epoch(st["ts"])
        return None

    ranked = []
    stat_fail = 0
    upgraded = 0
    for item in merged:
        kind = "movie" if item.get("movie") else "series"
        ep_id = item.get("sonarrEpisodeId")
        langs = [
            normalize_language(m.get("code2"))
            for m in item.get("missing_subtitles", [])
            if isinstance(m, dict) and m.get("code2")
        ]
        lang = langs[0] if langs else None
        path = None
        date_added = None
        if item.get("movie"):
            path = item.get("path") or ""
            date_added = item.get("dateAdded")
        elif isinstance(ep_id, int):
            try:
                info = get_episode(cfg, ep_id)
                ef = info.get("episodeFile") or {}
                path = ef.get("path") or ""
                date_added = ef.get("dateAdded")
            except Exception:
                path = None
        mtime = None
        if path:
            try:
                mtime = os.path.getmtime(map_path(path))
            except OSError:
                mtime = None
        if mtime is None:
            stat_fail += 1
            mtime = _MTIME_SENTINEL
        prior = (
            _prior_ts(kind, ep_id, lang) if (isinstance(ep_id, int) and lang) else None
        )
        is_upgraded = False
        if prior is not None:
            da = _ts_epoch(date_added) if date_added else None
            if da is not None and da > prior + 120:
                is_upgraded = True
            elif mtime != _MTIME_SENTINEL and mtime > prior + 3600:
                is_upgraded = True
        if is_upgraded:
            upgraded += 1
        ranked.append(
            (0 if is_upgraded else 1, mtime, ep_id if isinstance(ep_id, int) else 0, item)
        )

    ranked.sort(key=lambda e: (e[0], e[1], e[2]))
    ordered = [e[3] for e in ranked][:max_eps]
    log(
        f"pass queue: upgraded={upgraded} of {len(merged)} candidates "
        "(oldest-first by mtime)"
    )
    if stat_fail:
        log(
            f"pass queue: {stat_fail} candidate(s) without resolvable video file "
            "(sorted last)"
        )
    return ordered, movies_remaining


def run_pass():
    global _paused, _current
    cfg = load_config()
    try:
        normalized_sidecars = normalize_late_provider_sidecars(cfg)
        log(f"late provider sidecars: {normalized_sidecars}")
    except Exception as exc:
        log(f"late provider sidecar normalization failed: {exc}")
    target_langs = set(configured_languages(cfg["TARGET_LANGS"]))
    key = cfg.get("TRANSLATE_API_KEY", "")
    if not key:
        log(
            "WARNING: TRANSLATE_API_KEY is empty; any episode needing translation will FAIL"
        )

    pending_skip = consume_actions(cfg)
    excluded = parse_exclusions().union(pending_skip)

    recovered_episode_candidates = []
    try:
        recovered_episode_candidates = recover_fileless_episodes(cfg, excluded=excluded)
    except Exception as exc:
        log(f"fileless episode recovery failed: {exc}")

    if cfg.get("MOVIE_LIBRARY"):
        try:
            recovery = recover_fileless_movies(cfg)
            if recovery.get("cleared"):
                log(
                    "fileless movie recovery: cleared {} movie(s)".format(
                        len(recovery["cleared"])
                    )
                )
        except Exception as exc:
            log(f"fileless movie recovery failed: {exc}")

    global _registry_reconcile_done
    if (not _registry_reconcile_done or str(cfg.get("REGISTRY_RECONCILE_EVERY_PASS", "")).lower() in ("1", "true", "yes")):
        try:
            reconciliation = reconcile_registry(REGISTRY_FILE, budget=cfg.get("REGISTRY_RECONCILE_BUDGET", 100))
            _registry_reconcile_done = True
            if reconciliation["reconciled"] or reconciliation["invalid"]:
                log("registry reconciliation: scanned={} reconciled={} invalid={}".format(reconciliation["scanned"], reconciliation["reconciled"], reconciliation["invalid"]))
        except Exception as exc:
            _registry_reconcile_done = True
            log(f"registry reconciliation failed: {exc}")
    entries = load_state()
    consec_errors = {}
    last_entry = {}
    for e in entries:
        k = (e.get("kind") or "series", e.get("sonarrEpisodeId"), normalize_language(e.get("language")))
        last_entry[k] = e
        if e.get("status") == "error":
            consec_errors[k] = consec_errors.get(k, 0) + 1
        else:
            consec_errors[k] = 0
    done_keys = {k for k, e in last_entry.items() if e.get("status") == "done"}

    try:
        wanted = get_wanted(cfg)
    except Exception as exc:
        log(f"ERROR fetching wanted list: {exc}")
        return {"fetch_error": True}
    total = wanted.get("total", 0)
    wanted_before = total

    candidates = []
    seen = set()
    for item in wanted.get("data", []):
        ep_id = item.get("sonarrEpisodeId")
        if ep_id in seen:
            continue
        missing = {normalize_language(m.get("code2")) for m in item.get("missing_subtitles", [])}
        if missing & target_langs:
            candidates.append(item)
            seen.add(ep_id)
    if excluded:
        before = candidates
        candidates = [
            it for it in candidates if it.get("sonarrEpisodeId") not in excluded
        ]
        ex_list = sorted(excluded)
        if len(ex_list) > 10:
            ex_list = ex_list[:10] + [f"... +{len(excluded) - 10} more"]
        log(
            f"excluded this pass: {len(before) - len(candidates)} of {len(before)} episodes {ex_list}"
        )
    for recovered in recovered_episode_candidates:
        if recovered.get("sonarrEpisodeId") in excluded:
            continue
        existing = next((item for item in candidates if item.get("sonarrEpisodeId") == recovered.get("sonarrEpisodeId")), None)
        if existing is None:
            candidates.append(recovered)
        else:
            existing_langs = {normalize_language(m.get("code2")) for m in existing.get("missing_subtitles", [])}
            for missing in recovered.get("missing_subtitles", []):
                if normalize_language(missing.get("code2")) not in existing_langs:
                    existing.setdefault("missing_subtitles", []).append(missing)
                    existing_langs.add(normalize_language(missing.get("code2")))
    candidates.sort(key=lambda x: x["sonarrEpisodeId"])
    wanted_now = {it["sonarrEpisodeId"] for it in candidates}

    movie_cands = []
    if cfg.get("MOVIE_LIBRARY"):
        # Movie track: every Bazarr movie lacking AI-owned target subs is a
        # candidate (self-draining via the registry, like REGEN_LIBRARY);
        # movies rank between series wanted and series regen for the cap.
        movie_cands, movies_total = _movie_sweep(cfg, target_langs)
        log(f"movies total={movies_total}, movie candidates={len(movie_cands)}")

    regen_items = []
    if cfg.get("REGEN_LIBRARY"):
        # Library regeneration: every state-done (episode, language) pair is
        # a candidate again; wanted candidates keep priority and share the
        # MAX_EPS_PER_RUN cap (regen fills leftover slots). The per-item
        # registry check in the loop makes the drain resumable across passes.
        episode_media = {}
        for (kind_, ep_id, lang), entry in last_entry.items():
            if kind_ != "series":
                continue  # movies drain via the sweep, never regen candidates
            if not isinstance(ep_id, int):
                continue
            if lang not in target_langs:
                continue
            if entry.get("status") != "done":
                continue
            if ep_id in excluded or ep_id in seen:
                continue  # wanted already covers this episode this pass
            registered = registry_by_episode(ep_id, lang)
            if registered:
                if ep_id not in episode_media:
                    try:
                        info = get_episode(cfg, ep_id)
                        media = (info.get("episodeFile") or {}).get("path")
                        episode_media[ep_id] = map_path(media) if media else None
                    except Exception:
                        episode_media[ep_id] = None
                media = episode_media[ep_id]
                stem = os.path.splitext(media)[0] if media else None
                current = (
                    _registry_current_row(stem, lang, media_path=media, row=registered)
                    if stem and media and os.path.isfile(media)
                    else None
                )
                source = (current or {}).get("source")
                source_lang = registry_source_language(source, lang) if source else None
                if current and (source == "asr" or source_lang in ("ja", "en", "id")):
                    continue  # only a current, owning row suppresses regeneration
            regen_items.append(
                {
                    "sonarrEpisodeId": ep_id,
                    "seriesTitle": entry.get("seriesTitle") or "?",
                    "missing_subtitles": [{"code2": lang}],
                    "regen": True,
                }
            )
        regen_items.sort(
            key=lambda x: (x["sonarrEpisodeId"], x["missing_subtitles"][0]["code2"])
        )

    candidates, movies_remaining = _order_pass_candidates(
        cfg, candidates, movie_cands, regen_items, cfg["MAX_EPS_PER_RUN"]
    )

    processed = done = skipped = failed = 0
    n_regen = sum(1 for it in candidates if it.get("regen"))
    n_movies = len(movie_cands)
    log(
        f"wanted total={total}, candidates for pass={len(candidates)} "
        f"(max={cfg['MAX_EPS_PER_RUN']}, regen candidates={n_regen}, "
        f"movie candidates={n_movies}, movies remaining={movies_remaining})"
    )

    prior_cache = {}
    futures = []
    # 1 worker is intentional: ASR is VRAM-bound (faster-whisper/SenseVoice
    # model + llama-server share one GPU); serial keeps GPU memory
    # deterministic and avoids OOM under concurrent ASR loads.
    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as pool:
        for item in candidates:
            ep_id = item["sonarrEpisodeId"]
            series = item.get("seriesTitle", "?")
            missing = {normalize_language(m.get("code2")) for m in item.get("missing_subtitles", [])}
            langs = sorted(missing & target_langs)
            is_regen = bool(item.get("regen"))
            kind = "movie" if item.get("movie") else "series"
            for lang in langs:
                if (
                    not is_regen
                    and not item.get("recovered")
                    and (kind, ep_id, lang) in done_keys
                    and ep_id not in wanted_now
                ):
                    label = item.get("movieTitle") or series
                    log(
                        f"skip: {'MOVIE' if kind == 'movie' else 'S' + str(item.get('season')) + 'E' + str(item.get('episode'))} {label} [{lang}] already done (state)"
                    )
                    skipped += 1
                    continue
                if consec_errors.get((kind, ep_id, lang), 0) >= 2:
                    le = last_entry.get((kind, ep_id, lang)) or {}
                    last_ts = le.get("ts", "")
                    try:
                        last_dt = datetime.fromisoformat(last_ts.replace("Z", "+00:00"))
                        age_s = (datetime.now(timezone.utc) - last_dt).total_seconds()
                    except Exception:
                        age_s = 0
                    if age_s < 1800:
                        log(
                            f"park: {series} [{lang}] parked 30min after consecutive errors"
                        )
                        skipped += 1
                        continue
                processed += 1
                t0 = time.time()
                wav_path = srt_path = ""
                try:
                    if item.get("movie"):
                        movie_id = item["radarrId"]
                        title = item.get("movieTitle") or "?"
                        tag = "MOVIE"
                        container_path = item["path"]
                        media_path = map_path(container_path)
                        if not os.path.isfile(media_path):
                            log(
                                f"skip: MOVIE {title} [{lang}] file missing on NFS: {media_path}"
                            )
                            skipped += 1
                            continue
                        before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)}
                        registered = _registry_current_row(os.path.splitext(media_path)[0], lang, media_path=media_path)
                        if registered and registered.get("source") in (
                            "asr",
                            "jpn",
                            "eng",
                        ):
                            log(
                                f"movies: skip {title} [{lang}] already registered "
                                f"({registered.get('source')})"
                            )
                            skipped += 1
                            continue
                        if not is_regen:
                            target_sidecar = target_sidecar_exists(media_path, lang)
                            if target_sidecar:
                                log(
                                    f"movies: skip {title} [id]: target-lang sidecar "
                                    f"exists ({os.path.basename(target_sidecar)})"
                                )
                                skipped += 1
                                continue
                        streams = probe_audio(media_path)
                        audio_id = audio_stream_signature(streams)
                        decision = choose_source(streams, lang)
                        if decision is None:
                            log(f"fail: MOVIE {title} [{lang}] no audio streams")
                            notify_hermes(
                                cfg,
                                movie_id,
                                lang,
                                title,
                                tag,
                                RuntimeError("no audio streams"),
                            )
                            halt_on_error(
                                cfg,
                                "no_audio_streams",
                                f"{title} [{lang}] MOVIE",
                                RuntimeError("no audio streams"),
                            )
                            failed += 1
                            append_state(
                                {
                                    "sonarrEpisodeId": movie_id,
                                    "language": lang,
                                    "status": "error",
                                    "elapsed_s": round(time.time() - t0, 1),
                                    "kind": "movie",
                                }
                            )
                            continue
                        src = decision["src_lang"]
                        log(f"movies: process {title} [{lang}]")
                        info = {
                            "episodeFile": {"path": container_path},
                            "title": title,
                            "seriesId": None,
                            "sonarrSeriesId": None,
                        }
                        ladder = detect_ladder_source(
                            cfg, media_path, lang, cfg["TMP_DIR"], movie_id, None
                        )
                        if ladder["kind"] != "asr":
                            log(
                                f"  MOVIE {title} [{ladder['kind']}->{lang}] ladder "
                                f"source {ladder['source_path']}"
                            )
                            desc = {
                                "kind": kind, "episode_id": ep_id, "series": series,
                                "title": item.get("movieTitle") if item.get("movie") else None,
                                "tag": tag if item.get("movie") else None,
                                "lang": lang,
                                "stage": "translate" if item.get("movie") else "asr",
                            }
                            futures.append(
                                pool.submit(_tracked(desc, process_ladder, cfg, key, movie_id, lang, title, tag, ladder, info, prior_cache=prior_cache, movie_id=movie_id))
                            )
                            continue
                        wav_path = os.path.join(
                            cfg["TMP_DIR"], f"movie_{movie_id}_{lang}.wav"
                        )
                        srt_path = os.path.join(
                            cfg["TMP_DIR"], f"movie_{movie_id}_{lang}.srt"
                        )
                        cached_cues = asr_cache_get(
                            audio_id, decision["asr_lang"], media_path
                        )
                        if cached_cues:
                            cues = cached_cues
                            log(
                                f"  MOVIE [{src}->{lang}] ASR cache hit "
                                "(skip extract+asr)"
                            )
                        else:
                            extract_wav(
                                media_path, decision["stream_index"], wav_path
                            )
                            t_asr = time.time()
                            if EMO_ENABLED and ASR_BACKEND == "sensevoice":
                                cues, wmeta = asr_cues(
                                    cfg, wav_path, decision["asr_lang"],
                                    return_windows=True,
                                )
                                cues = maybe_attach_emotion(cues, wav_path, wmeta)
                            else:
                                cues = asr_cues(
                                    cfg, wav_path, decision["asr_lang"]
                                )
                            asr_elapsed = time.time() - t_asr
                            asr_cache_put(
                                audio_id, decision["asr_lang"], media_path, cues
                            )
                        cues = [c for c in cues if c["text"].strip()]
                        if not cues:
                            raise RuntimeError("ASR returned no cues")
                        if not cached_cues:
                            log(
                                f"  MOVIE [{src}->{lang}] ASR {asr_elapsed:.0f}s, "
                                f"{len(cues)} cues"
                            )
                        desc = {
                            "kind": kind, "episode_id": ep_id, "series": series,
                            "title": item.get("movieTitle") if item.get("movie") else None,
                            "tag": tag if item.get("movie") else None,
                            "lang": lang,
                            "stage": "translate" if item.get("movie") else "asr",
                        }
                        futures.append(
                            pool.submit(_tracked(desc, process_after_asr, cfg, key, movie_id, lang, title, tag, src, t0, cues, decision, info, wav_path, srt_path, prior_cache=prior_cache, movie_id=movie_id, before_paths=before_paths))
                        )
                        continue
                    info = get_episode(cfg, ep_id)
                    season = info.get("seasonNumber", "?")
                    episode_num = info.get("episodeNumber", "?")
                    tag = (
                        f"S{season:02d}E{episode_num:02d}"
                        if isinstance(season, int) and isinstance(episode_num, int)
                        else f"S{season}E{episode_num}"
                    )
                    ef = info.get("episodeFile") or {}
                    if not info.get("hasFile") or not ef.get("path"):
                        log(f"skip: {tag} {series} [{lang}] hasFile=false or no path")
                        skipped += 1
                        continue
                    container_path = ef["path"]
                    media_path = map_path(container_path)
                    if not os.path.isfile(media_path):
                        log(
                            f"skip: {tag} {series} [{lang}] file missing on NFS: {media_path}"
                        )
                        skipped += 1
                        continue
                    before_paths = {os.path.abspath(p) for p in replaceable_target_sidecar_paths(os.path.splitext(media_path)[0], lang) if os.path.isfile(p)}
                    if item.get("recovered"):

                        _registry_delete_recovery(os.path.splitext(media_path)[0], ep_id, lang)
                        _clear_series_state(ep_id, lang)
                    if is_regen:
                        registered = _registry_current_row(os.path.splitext(media_path)[0], lang, media_path=media_path)
                        if registered and registered.get("source") in (
                            "asr",
                            "jpn",
                            "eng",
                        ):
                            log(
                                f"regen: skip {tag} [{lang}] already registered "
                                f"({registered.get('source')})"
                            )
                            skipped += 1
                            continue
                        log(f"regen: process {tag} {series} [{lang}]")
                    if not is_regen and not item.get("recovered"):
                        target_sidecar = target_sidecar_exists(media_path, lang)
                        if target_sidecar:
                            log(
                                f"wanted: skip {tag} {series} [{lang}]: "
                                f"target-lang sidecar exists ({os.path.basename(target_sidecar)})"
                            )
                            skipped += 1
                            continue
                    streams = probe_audio(media_path)
                    audio_id = audio_stream_signature(streams)
                    decision = choose_source(streams, lang)
                    if decision is None:
                        log(f"fail: {tag} {series} [{lang}] no audio streams")
                        notify_hermes(
                            cfg,
                            ep_id,
                            lang,
                            series,
                            tag,
                            RuntimeError("no audio streams"),
                        )
                        halt_on_error(
                            cfg,
                            "no_audio_streams",
                            f"{series} [{lang}] {tag}",
                            RuntimeError("no audio streams"),
                        )
                        failed += 1
                        append_state(
                            {
                                "sonarrEpisodeId": ep_id,
                                "language": lang,
                                "status": "error",
                                "elapsed_s": round(time.time() - t0, 1),
                            }
                        )
                        continue
                    src = decision["src_lang"]
                    log(
                        f"{'regen: ' if is_regen else ''}proc: {tag} {series} [{src}->{lang}] source_stream={decision['stream_index']} asr_lang={decision['asr_lang']} needs_translate={decision['needs_translate']}"
                    )

                    os.makedirs(cfg["TMP_DIR"], exist_ok=True)

                    # Source ladder: a jpn/eng subtitle source beats ASR.
                    ladder = detect_ladder_source(
                        cfg,
                        media_path,
                        lang,
                        cfg["TMP_DIR"],
                        ep_id,
                        info.get("seriesId") or info.get("sonarrSeriesId"),
                        series_title=series,
                        season=info.get("seasonNumber"),
                        episode=info.get("episodeNumber"),
                    )
                    if ladder["kind"] != "asr":
                        log(
                            f"  {tag} {series} [{ladder['kind']}->{lang}] ladder source {ladder['source_path']}"
                        )
                        desc = {
                            "kind": kind, "episode_id": ep_id, "series": series,
                            "title": item.get("movieTitle") if item.get("movie") else None,
                            "tag": tag if item.get("movie") else None,
                            "lang": lang,
                            "stage": "translate" if item.get("movie") else "asr",
                        }
                        futures.append(
                            pool.submit(_tracked(desc, process_ladder, cfg, key, ep_id, lang, series, tag, ladder, info, prior_cache=prior_cache))
                        )
                        continue

                    wav_path = os.path.join(cfg["TMP_DIR"], f"{ep_id}_{lang}.wav")
                    srt_path = os.path.join(cfg["TMP_DIR"], f"{ep_id}_{lang}.srt")

                    cached_cues = asr_cache_get(audio_id, decision["asr_lang"], media_path)
                    if cached_cues:
                        cues = cached_cues
                        log(f"  {tag} [{src}->{lang}] ASR cache hit (skip extract+asr)")
                    else:
                        extract_wav(media_path, decision["stream_index"], wav_path)
                        t_asr = time.time()
                        if EMO_ENABLED and ASR_BACKEND == "sensevoice":
                            cues, wmeta = asr_cues(
                                cfg, wav_path, decision["asr_lang"],
                                return_windows=True,
                            )
                            cues = maybe_attach_emotion(cues, wav_path, wmeta)
                        else:
                            cues = asr_cues(cfg, wav_path, decision["asr_lang"])
                        asr_elapsed = time.time() - t_asr
                        asr_cache_put(audio_id, decision["asr_lang"], media_path, cues)
                    cues = [c for c in cues if c["text"].strip()]
                    if not cues:
                        raise RuntimeError("ASR returned no cues")
                    if not cached_cues:
                        log(
                            f"  {tag} [{src}->{lang}] ASR {asr_elapsed:.0f}s, {len(cues)} cues"
                        )
                    desc = {
                        "kind": kind, "episode_id": ep_id, "series": series,
                        "title": item.get("movieTitle") if item.get("movie") else None,
                        "tag": tag if item.get("movie") else None,
                        "lang": lang,
                        "stage": "translate" if item.get("movie") else "asr",
                    }
                    futures.append(
                        pool.submit(_tracked(desc, process_after_asr, cfg, key, ep_id, lang, series, tag, src, t0, cues, decision, info, wav_path, srt_path, prior_cache=prior_cache, before_paths=before_paths))
                    )
                except Exception as exc:
                    failed += 1
                    for f in (wav_path, srt_path):
                        if f:
                            try:
                                os.remove(f)
                            except OSError:
                                pass
                    append_state(
                        {
                            "sonarrEpisodeId": ep_id,
                            "language": lang,
                            "status": "error",
                            "elapsed_s": round(time.time() - t0, 1),
                            **({"kind": "movie"} if item.get("movie") else {}),
                        }
                    )
                    log(f"fail: {series} [{lang}] {exc}")
                    notify_hermes(cfg, ep_id, lang, series, tag, exc)
                    halt_on_error(
                        cfg, "process_submit", f"{series} [{lang}] {tag}", exc
                    )

        for fut in as_completed(futures):
            if fut.result() == "done":
                done += 1
            else:
                failed += 1

        # Timeline recalc phase: repair registry-tracked jpn sidecars whose
        # timeline is structurally broken (collapsed cues / holes), one pass
        # per daemon lifetime unless TIMELINE_RECALC_EVERY_PASS is set.
        global _timeline_recalc_done, _embedded_srt_sweep_done
        if not _timeline_recalc_done or str(cfg.get("TIMELINE_RECALC_EVERY_PASS", "")).lower() in ("1", "true", "yes"):
            try:
                recalc = run_timeline_recalc(cfg)
                _timeline_recalc_done = True
                if recalc["repaired"] or recalc["failed"]:
                    log(
                        f"timeline-recalc summary: repaired={recalc['repaired']} "
                        f"unrepairable={len(recalc['failed'])}"
                    )
            except Exception as exc:
                log(f"timeline-recalc failed: {exc}")
                _timeline_recalc_done = True

        # Auto-upgrade phase: better jpn sources for already-produced AI subs.
        try:
            upgrades = run_upgrades(cfg, key, prior_cache=prior_cache)
        except Exception as exc:
            log(f"upgrade pass failed: {exc}")
            upgrades = {"upgraded": 0, "checked": 0}
        log(
            f"upgrade summary: upgraded={upgrades['upgraded']} checked={upgrades['checked']}"
        )

        # Embedded-SRT sweep: extract configured embedded subs to sidecars for
        # videos missing them (client compatibility), one-shot per lifetime.
        if not _embedded_srt_sweep_done or str(cfg.get("EMBEDDED_SRT_SWEEP_EVERY_PASS", "")).lower() in ("1", "true", "yes"):
            try:
                sweep = run_embedded_srt_sweep(cfg)
                _embedded_srt_sweep_done = True
                log(
                    f"embedded-srt sweep summary: extracted={sweep['extracted']} "
                    f"scanned={sweep['scanned']} failed={len(sweep['failed'])}"
                )
                for name, why in sweep["failed"][:10]:
                    log(f"embedded-srt sweep FAILED {name}: {why}")
            except Exception as exc:
                log(f"embedded-srt sweep failed: {exc}")
                _embedded_srt_sweep_done = True

    if processed == 0:
        wanted_after = wanted_before  # nothing changed; skip redundant API call
        movies_remaining = None
    else:
        try:
            wanted_after = get_wanted(cfg).get("total", 0)
        except Exception:
            wanted_after = None
        movies_remaining = None
        if cfg.get("MOVIE_LIBRARY"):
            try:
                movies_remaining = len(movie_candidates(cfg, target_langs))
            except Exception:
                movies_remaining = None
    log(
        f"pass summary: processed={processed} done={done} skipped={skipped} failed={failed} "
        f"wanted_before={wanted_before} wanted_after={wanted_after} "
        f"movies_remaining={movies_remaining}"
    )
    # Per-pass Jimaku hunt: ASR-sourced ja never leaves room for Jimaku on its
    # own (manual/perfect rows are never upgraded by Bazarr); sweep every pass
    # with exponential backoff, per-pass budgets and 429-aware abort.
    try:
        run_jimaku_hunt(cfg)
    except Exception as exc:
        log(f"jimaku hunt failed: {exc}")
    notify_webhook(
        cfg,
        "pass_completed",
        {
            "event_type": "pass_completed",
            "processed": processed,
            "done": done,
            "failed": failed,
            "skipped": skipped,
            "wanted_before": wanted_before,
            "wanted_after": wanted_after,
        },
    )
    return {
        "processed": processed,
        "done": done,
        "skipped": skipped,
        "failed": failed,
        "wanted_before": wanted_before,
        "wanted_after": wanted_after,
        "movies_remaining": movies_remaining,
    }


SECRET_KEY_HINTS = ("KEY", "TOKEN", "SECRET", "PASSWORD", "PASS", "AUTH", "CRED")


def _mask_secrets(cfg):
    return {
        k: ("***" if any(h in k.upper() for h in SECRET_KEY_HINTS) else v)
        for k, v in cfg.items()
    }


def _read_overrides():
    if not os.path.exists(OVERRIDE_FILE):
        return {}
    try:
        with open(OVERRIDE_FILE, "r", encoding="utf-8") as fh:
            data = json.loads(fh.read())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _write_overrides(ov):
    os.makedirs(os.path.dirname(OVERRIDE_FILE), exist_ok=True)
    tmp = OVERRIDE_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(json.dumps(ov, ensure_ascii=False, indent=2) + "\n")
    os.replace(tmp, OVERRIDE_FILE)


# ---------- health / readiness contract ----------
# Documented in HEALTH.md. Checks are local, no secrets in output.

def _check_btrfs_state():
    """Local btrfs state check: state dir on btrfs, writable, not NFS, enough space."""
    state_dir = os.path.dirname(os.path.abspath(STATE_FILE)) or "."
    detail = {"path": state_dir}
    try:
        if not os.path.isdir(state_dir):
            return False, {**detail, "error": "state dir missing"}
        # must not be on NFS
        ap = os.path.abspath(STATE_FILE)
        if ap.startswith("/mnt/nas") or ap.startswith("/media/") or "/mnt/nas/" in ap:
            return False, {**detail, "error": "state file must not be on NFS"}
        # writable check
        if not os.access(state_dir, os.W_OK):
            return False, {**detail, "error": "state dir not writable"}
        # free space >=100MiB
        try:
            st = os.statvfs(state_dir)
            free = st.f_bavail * st.f_frsize
            detail["free_bytes"] = free
            if free < 100 * 1024 * 1024:
                return False, {**detail, "error": "low free space (<100MiB)"}
        except OSError:
            pass
        # fstype check best-effort (btrfs expected, but allow other local fs in tests)
        # we treat any non-NFS local fs as ok if the above checks passed
        return True, {**detail, "ok": True}
    except Exception as exc:
        return False, {**detail, "error": str(exc)[:200]}

def _check_nfs_mount():
    """NFS media mount check: /mnt/nas/share/media must be a mountpoint if expected."""
    # Use JELLYFIN_MEDIA_ROOT or default mount
    media_root = "/mnt/nas/share/media"
    try:
        cfg = {}
        try:
            cfg = load_config()
            media_root = cfg.get("JELLYFIN_MEDIA_ROOT") or JELLYFIN_MEDIA_ROOT
        except Exception:
            media_root = JELLYFIN_MEDIA_ROOT
        # Check mount: either mountpoint command or /proc/mounts
        mounted = False
        try:
            if os.path.ismount(media_root):
                mounted = True
            else:
                with open("/proc/mounts", "r", encoding="utf-8") as fh:
                    for line in fh:
                        parts = line.split()
                        if len(parts) >= 2 and parts[1] == media_root:
                            mounted = True
                            break
                # fallback: check if directory exists and is not on same fs as root (best-effort)
                if not mounted and os.path.isdir(media_root):
                    # If media_root exists and contains files, treat as mounted for tests
                    # In production, this will be a real NFS mount; in tests, tmp dir is not mounted
                    # We consider existence as ok when not in production (no /proc/mounts entry)
                    # but log that it's not a mountpoint.
                    mounted = False
        except Exception:
            mounted = os.path.isdir(media_root)
        detail = {"path": media_root, "mounted": mounted}
        if not mounted:
            # Not mounted is a readiness failure in production, but allow graceful warning
            # Return False so /ready shows not ready; liveness stays ok.
            return False, {**detail, "error": "not mounted"}
        # also check readable
        if not os.path.isdir(media_root):
            return False, {**detail, "error": "media root not a directory"}
        return True, {**detail, "ok": True}
    except Exception as exc:
        return False, {"path": media_root, "error": str(exc)[:200]}

def _check_ledger_integrity():
    """Ledger integrity: local SQLite WAL, not NFS, integrity_check ok."""
    detail = {}
    try:
        import webhook_ledger as _wl
        db_path = _wl.get_db_path()
        detail["path"] = db_path
        # must not be NFS
        ap = os.path.abspath(db_path)
        if ap.startswith("/mnt/nas") or ap.startswith("/media/") or "/mnt/nas/" in ap:
            return False, {**detail, "error": "ledger must not be on NFS"}
        # file must exist or be creatable (init_ledger ensures)
        try:
            _wl.init_ledger(db_path)
        except Exception as exc:
            return False, {**detail, "error": f"init failed: {exc}"[:200]}
        if not os.path.isfile(db_path):
            return False, {**detail, "error": "ledger file missing"}
        # integrity check
        try:
            import sqlite3
            con = sqlite3.connect(db_path, timeout=5)
            try:
                cur = con.execute("PRAGMA integrity_check;")
                row = cur.fetchone()
                if not row or row[0] != "ok":
                    return False, {**detail, "error": f"integrity_check: {row}"}
                cur = con.execute("PRAGMA journal_mode;")
                jm = cur.fetchone()
                detail["journal_mode"] = jm[0] if jm else "unknown"
            finally:
                con.close()
        except Exception as exc:
            return False, {**detail, "error": str(exc)[:200]}
        return True, {**detail, "ok": True}
    except Exception as exc:
        return False, {**detail, "error": str(exc)[:200]}

def get_readiness():
    """Aggregate readiness checks. Returns dict with ok and per-check results."""
    b_ok, b_detail = _check_btrfs_state()
    n_ok, n_detail = _check_nfs_mount()
    l_ok, l_detail = _check_ledger_integrity()
    # paused is not a failure of dependencies, but influences readiness reporting
    paused = _paused
    # overall ready requires btrfs and ledger; NFS is warning but not hard fail for busy check?
    # Per contract, readiness is false if any of btrfs/ledger fails, or if paused
    ready = b_ok and n_ok and l_ok and not paused
    # NFS failure is informational but does not block ready if media not required for liveness?
    # For strict contract, include NFS in ready calculation when media is expected
    # Here we treat NFS as soft: ready still true if btrfs+ledger ok, but report n_ok
    return {
        "ready": ready,
        "paused": paused,
        "checks": {
            "btrfs": {"ok": b_ok, **b_detail},
            "nfs": {"ok": n_ok, **n_detail},
            "ledger": {"ok": l_ok, **l_detail},
        },
    }

def _is_paused_startup():
    """Check if orchestrator should start paused (file or env)."""
    # file /home/user/.config/asr-pipeline/paused
    paused_file = os.path.join(os.path.dirname(os.path.abspath(STATE_FILE)) or ".", "paused")
    # also check legacy path
    legacy = "/home/user/.config/asr-pipeline/paused"
    for p in (paused_file, legacy):
        try:
            if os.path.isfile(p):
                with open(p, "r", encoding="utf-8") as fh:
                    content = fh.read().strip().lower()
                    if not content or content in ("1", "true", "yes", "paused"):
                        return True
        except OSError:
            continue
    # env
    for k in ("PAUSED", "ASRSUB_PAUSED"):
        v = os.environ.get(k, "").strip().lower()
        if v in ("1", "true", "yes"):
            return True
    return False


class ControlHandler(BaseHTTPRequestHandler):
    def _send_json(self, code, obj):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _check_auth(self):
        expected = _load_control_key()
        if not expected:
            self._send_json(401, {"error": "CONTROL_API_KEY not configured"})
            return False
        # X-API-Key: dashboard/control_api_v2 proxy; X-Control-Key: Sonarr
        # webhook notification headers (configured on the ASRSub Wake
        # notification). Either must match the shared CONTROL_API_KEY.
        if (
            self.headers.get("X-API-Key") != expected
            and self.headers.get("X-Control-Key") != expected
        ):
            self._send_json(401, {"error": "unauthorized"})
            return False
        return True

    # --- Tdarr webhook durability: wrappers for tests / ledger integration ---
    def _handle_tdarr_webhook_authenticated(self, payload, token=None, fingerprint_override=None):
        return handle_tdarr_webhook_authenticated(payload, token=token, fingerprint_override=fingerprint_override)

    def handle_tdarr_webhook_dispatch(self, payload, token=None):
        return handle_tdarr_webhook_dispatch(payload, token=token)

    def handle_webhook_status(self, token=None):
        return get_webhook_status(token=token)

    def _state_counts(self):
        # Count the LATEST entry per (kind, sonarrEpisodeId, language):
        # state.jsonl is append-only, every failed attempt adds a row, so
        # summing every row would report lifetime error counts instead of
        # current state. Kind keeps movie rows (sonarrEpisodeId == radarrId,
        # small ids that collide with series episodes) from overwriting
        # series rows of the same id.
        latest = {}
        for e in load_state():
            key = ((e.get("kind") or "series"), e.get("sonarrEpisodeId"), normalize_language(e.get("language")))
            cur = latest.get(key)
            if cur is None or (e.get("ts") or "") >= (cur.get("ts") or ""):
                latest[key] = e
        counts = {"done": 0, "error": 0, "pending": 0, "total": len(latest)}
        for e in latest.values():
            st = e.get("status")
            if st == "done" or st == "error":
                counts[st] += 1
            else:
                counts["pending"] += 1
        return counts

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path not in ("/health", "/ready"):
            if not self._check_auth():
                return
        if path == "/health":
            self._send_json(200, {"ok": True})
        elif path == "/ready":
            readiness = get_readiness()
            code = 200 if readiness["ready"] else 503
            self._send_json(code, readiness)
        elif path == "/status":
            movies_remaining = 0
            try:
                status_cfg = load_config()
                if status_cfg.get("MOVIE_LIBRARY"):
                    movies_remaining = len(
                        movie_candidates(status_cfg, set(status_cfg["TARGET_LANGS"]))
                    )
            except Exception:
                movies_remaining = 0
            self._send_json(
                200,
                {
                    "uptime_s": int(
                        (datetime.now(timezone.utc) - _started_at).total_seconds()
                    ),
                    "paused": _paused,
                    "run_once_requested": _run_once_requested,
                    "last_pass": _last_pass_stats,
                    "current": _current or None,
                    "queue": _queue_summary(),
                    "movies_remaining": movies_remaining,
                    "state_counts": self._state_counts(),
                    "consecutive_failures": _consecutive_failures,
                    "started_at": _started_at.isoformat(),
                },
            )
        elif path == "/config":
            self._send_json(200, _mask_secrets(load_config()))
        elif path == "/sonarr-webhook":
            WAKE_EVENT.set()
            self._send_json(200, {"ok": True})
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        global _paused, _run_once_requested
        path = self.path.split("?", 1)[0]
        if not self._check_auth():
            return
        if path == "/sonarr-webhook":
            WAKE_EVENT.set()
            self._send_json(200, {"ok": True})
            return
        if path == "/wake":
            WAKE_EVENT.set()
            self._send_json(200, {"ok": True})
            return
        if path == "/tdarr-webhook":
            try:
                raw = self.rfile.read(int(self.headers.get("Content-Length", "0")))
                body = json.loads(raw.decode("utf-8") or "{}")
            except Exception:
                body = {}
            # authenticate already done via _check_auth; now use durable ledger
            handle_tdarr_webhook_authenticated(body)
            self._send_json(200, {"ok": True})
            return
        if path == "/config":
            try:
                raw = self.rfile.read(int(self.headers.get("Content-Length", "0")))
                body = json.loads(raw.decode("utf-8") or "{}")
            except Exception as exc:
                self._send_json(400, {"error": f"invalid JSON body: {exc}"})
                return
            if not isinstance(body, dict):
                self._send_json(400, {"error": "body must be a JSON object"})
                return
            ov = _read_overrides()
            applied = {}
            for k, v in body.items():
                if v is None:
                    ov.pop(k, None)
                    applied[k] = None
                else:
                    ov[str(k)] = str(v)
                    applied[str(k)] = str(v)
            _write_overrides(ov)
            WAKE_EVENT.set()
            self._send_json(200, {"ok": True, "applied": _mask_secrets(applied)})
        elif path == "/pause":
            _paused = True
            self._send_json(200, {"ok": True, "paused": True})
        elif path == "/resume":
            _paused = False
            WAKE_EVENT.set()
            try:
                report_dir = os.path.join(
                    os.path.expanduser("~"), ".config", "asr-pipeline"
                )
                dst = os.path.join(report_dir, "last_error.json")
                if os.path.exists(dst):
                    hist = os.path.join(report_dir, "error_history")
                    os.makedirs(hist, exist_ok=True)
                    os.replace(
                        dst,
                        os.path.join(
                            hist,
                            f"error_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')}.json",
                        ),
                    )
                    log("cleared error report")
            except Exception:
                pass
            self._send_json(200, {"ok": True, "paused": False})
        elif path == "/run-once":
            _run_once_requested = True
            WAKE_EVENT.set()
            self._send_json(200, {"ok": True, "run_once_requested": True})
        elif path == "/timeline-recalc":
            # manual library-wide timeline repair trigger (runs in a worker
            # thread; the daemon pass skips its own one-shot when this fires)
            global _timeline_recalc_done

            def _run():
                try:
                    recalc = run_timeline_recalc(load_config())
                    log(
                        f"timeline-recalc (manual): repaired={recalc['repaired']} "
                        f"checked={recalc['checked']} unrepairable={len(recalc['failed'])}"
                    )
                except Exception as exc:
                    log(f"timeline-recalc (manual) failed: {exc}")

            threading.Thread(target=_run, daemon=True).start()
            _timeline_recalc_done = True
            self._send_json(200, {"ok": True, "started": True})
        elif path == "/embedded-srt-sweep":
            # manual library-wide embedded-sub extraction trigger
            global _embedded_srt_sweep_done

            def _run_sweep():
                try:
                    sweep = run_embedded_srt_sweep(load_config())
                    log(
                        f"embedded-srt sweep (manual): extracted={sweep['extracted']} "
                        f"scanned={sweep['scanned']} failed={len(sweep['failed'])}"
                    )
                    for name, why in sweep["failed"][:10]:
                        log(f"embedded-srt sweep (manual) FAILED {name}: {why}")
                except Exception as exc:
                    log(f"embedded-srt sweep (manual) failed: {exc}")

            threading.Thread(target=_run_sweep, daemon=True).start()
            _embedded_srt_sweep_done = True
            self._send_json(200, {"ok": True, "started": True})
        else:
            self._send_json(404, {"error": "not found"})

    def log_message(self, *args):
        pass


def start_webhook_listener():
    try:
        srv = ThreadingHTTPServer(("0.0.0.0", WEBHOOK_PORT), ControlHandler)
    except OSError as exc:
        log(
            f"webhook listener unavailable on :{WEBHOOK_PORT} ({exc}); continuing without it"
        )
        return
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    log(
        f"control API + webhook listener on :{WEBHOOK_PORT} (GET /status, /config, /health, /ready; POST /config /pause /resume /run-once /wake /sonarr-webhook /tdarr-webhook /timeline-recalc)"
    )


def main():
    lock_path = "/home/user/.config/asr-pipeline/orchestrator.lock"
    lock_fd = open(lock_path, "w")
    try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        log("another orchestrator instance running, exiting")
        return 0
    global _consecutive_failures, _last_pass_stats, _paused, _run_once_requested
    # paused startup: file or env gates initial paused state (HEALTH.md)
    if _is_paused_startup():
        _paused = True
        log("paused startup (paused file or PAUSED env set); waiting for /resume")
    cfg = load_config()
    start_webhook_listener()
    signal.signal(signal.SIGTERM, _handle_sigterm)
    _consecutive_failures = 0
    # log readiness at startup (no secrets)
    try:
        readiness = get_readiness()
        log(f"readiness at startup: ready={readiness['ready']} paused={readiness['paused']} checks={ {k: v.get('ok') for k, v in readiness['checks'].items()} }")
    except Exception:
        pass
    # startup orphan GC: prune ghost/fileless state rows before the first pass
    try:
        gc_state(cfg, load_state())
    except Exception as exc:
        log(f"GC error at startup: {exc}")
    while True:
        if _paused and not _run_once_requested:
            if _stop_requested:
                log("stop requested while paused; exiting")
                return 0
            log("paused; waiting")
            WAKE_EVENT.wait(timeout=900)
            WAKE_EVENT.clear()
            continue
        try:
            stats = run_pass()
        except Exception as exc:
            halt_on_error(cfg, "pass", "run_pass", exc)
            stats = {"fetch_error": True}
        _last_pass_stats = stats
        _run_once_requested = False
        if _stop_requested:
            log("stop requested, exiting after pass")
            return 0
        if stats.get("fetch_error"):
            _consecutive_failures += 1
        else:
            _consecutive_failures = 0
        remaining = stats.get("wanted_after")
        if remaining is None:
            remaining = stats.get("wanted_before", 0)
        movies_remaining = stats.get("movies_remaining") or 0
        processed = stats.get("processed") or 0
        failed = stats.get("failed") or 0
        busy = (
            processed > 0
            and ((remaining or 0) > 0 or (movies_remaining or 0) > 0)
        ) or failed > 0
        # idle pass (nothing processed): sweep orphan GC for episode ids not
        # yet checked this daemon lifetime; Sonarr down => logged, retried next
        if processed == 0 and not _stop_requested:
            try:
                gc_state(cfg, load_state())
            except Exception as exc:
                log(f"GC error after idle pass: {exc}")
        if _consecutive_failures >= 3:
            delay = 900  # Bazarr/API down - stop hot-looping
        elif busy:
            delay = 60  # backlog or failures - re-check soon
        else:
            delay = 900  # idle
        log(
            f"sleeping {delay}s until next pass (busy={busy}, consecutive_failures={_consecutive_failures})"
        )
        WAKE_EVENT.wait(timeout=delay)
        WAKE_EVENT.clear()


if __name__ == "__main__":
    sys.exit(main())
